20260115225323	{"-- Unified Sales Returns Functions\n-- Handles Wholesale, Individual Items, and Partial Quantity returns consistently\n\n-- Helper function to check permissions and workspace status\nCREATE OR REPLACE FUNCTION public.check_return_permissions(\n    p_sale_id UUID,\n    p_user_id UUID\n)\nRETURNS TABLE (\n    workspace_id UUID,\n    user_role TEXT,\n    allow_pos BOOLEAN\n) \nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        s.workspace_id,\n        pr.role,\n        w.allow_pos\n    FROM public.sales s\n    JOIN public.profiles pr ON pr.id = p_user_id AND pr.workspace_id = s.workspace_id\n    JOIN public.workspaces w ON w.id = s.workspace_id\n    WHERE s.id = p_sale_id;\nEND;\n$$;\n\n-- Refined return_sale_items function\nCREATE OR REPLACE FUNCTION public.return_sale_items(\n    p_sale_item_ids UUID[],\n    p_return_quantities INTEGER[],\n    p_return_reason TEXT\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_item_record RECORD;\n    v_sale_record RECORD;\n    v_workspace_id UUID;\n    v_user_role TEXT;\n    v_allow_pos BOOLEAN;\n    v_index INTEGER;\n    v_total_return_value NUMERIC := 0;\n    v_sale_id UUID;\nBEGIN\n    -- Basic validation\n    IF p_sale_item_ids IS NULL OR array_length(p_sale_item_ids, 1) = 0 THEN\n        RAISE EXCEPTION 'No items selected for return';\n    END IF;\n\n    IF p_return_quantities IS NULL OR array_length(p_return_quantities, 1) != array_length(p_sale_item_ids, 1) THEN\n        RAISE EXCEPTION 'Invalid quantities provided for return';\n    END IF;\n\n    -- Get workspace and sale info from the first item\n    SELECT si.sale_id, s.workspace_id \n    INTO v_sale_id, v_workspace_id\n    FROM public.sale_items si\n    JOIN public.sales s ON s.id = si.sale_id\n    WHERE si.id = p_sale_item_ids[1];\n\n    IF v_sale_id IS NULL THEN\n        RAISE EXCEPTION 'Sale not found for the provided items';\n    END IF;\n\n    -- Check permissions\n    SELECT p.workspace_id, p.role, p.allow_pos \n    INTO v_workspace_id, v_user_role, v_allow_pos\n    FROM public.check_return_permissions(v_sale_id, auth.uid()) p;\n\n    IF v_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'Unauthorized or workspace not found';\n    END IF;\n\n    IF NOT COALESCE(v_allow_pos, FALSE) THEN\n        RAISE EXCEPTION 'POS feature is not enabled for this workspace';\n    END IF;\n\n    IF v_user_role NOT IN ('admin', 'staff') THEN\n        RAISE EXCEPTION 'Unauthorized: Only admins and staff can return items';\n    END IF;\n\n    -- Process each item\n    FOR v_index IN 1..array_length(p_sale_item_ids, 1) LOOP\n        SELECT si.*, (si.quantity - si.returned_quantity) as available_quantity\n        INTO v_item_record\n        FROM public.sale_items si\n        WHERE si.id = p_sale_item_ids[v_index] AND si.sale_id = v_sale_id;\n\n        IF v_item_record IS NULL THEN\n            CONTINUE;\n        END IF;\n\n        IF p_return_quantities[v_index] <= 0 OR p_return_quantities[v_index] > v_item_record.available_quantity THEN\n            RAISE EXCEPTION 'Invalid return quantity for item %: must be between 1 and %', v_item_record.id, v_item_record.available_quantity;\n        END IF;\n\n        -- Calculate return value for this item\n        v_total_return_value := v_total_return_value + (p_return_quantities[v_index] * COALESCE(v_item_record.converted_unit_price, v_item_record.unit_price));\n\n        -- Update sale_item\n        UPDATE public.sale_items\n        SET \n            returned_quantity = returned_quantity + p_return_quantities[v_index],\n            return_reason = CASE \n                WHEN COALESCE(return_reason, '') = '' THEN p_return_reason\n                ELSE return_reason || '; ' || p_return_reason\n            END,\n            returned_at = NOW(),\n            returned_by = auth.uid(),\n            is_returned = CASE \n                WHEN (returned_quantity + p_return_quantities[v_index]) >= quantity THEN TRUE \n                ELSE FALSE \n            END\n        WHERE id = v_item_record.id;\n\n        -- Restore inventory\n        UPDATE public.products\n        SET quantity = quantity + p_return_quantities[v_index]\n        WHERE id = v_item_record.product_id AND workspace_id = v_workspace_id;\n    END LOOP;\n\n    -- Update main sale total\n    UPDATE public.sales\n    SET \n        total_amount = total_amount - v_total_return_value,\n        updated_at = NOW()\n    WHERE id = v_sale_id;\n\n    -- Check if entire sale is now returned\n    UPDATE public.sales s\n    SET \n        is_returned = TRUE,\n        returned_at = NOW(),\n        returned_by = auth.uid(),\n        return_reason = CASE \n            WHEN COALESCE(return_reason, '') = '' THEN 'All items returned'\n            ELSE return_reason || '; All items returned'\n        END\n    WHERE id = v_sale_id \n      AND NOT EXISTS (\n          SELECT 1 FROM public.sale_items si \n          WHERE si.sale_id = v_sale_id AND si.is_returned = FALSE\n      );\n\n    RETURN jsonb_build_object(\n        'success', true, \n        'message', 'Items returned successfully',\n        'sale_id', v_sale_id,\n        'return_value', v_total_return_value\n    );\nEND;\n$$;\n\n-- Refined return_whole_sale function (now uses return_sale_items logic)\nCREATE OR REPLACE FUNCTION public.return_whole_sale(\n    p_sale_id UUID,\n    p_return_reason TEXT\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_item_ids UUID[];\n    v_item_quantities INTEGER[];\n    v_user_role TEXT;\n    v_workspace_id UUID;\nBEGIN\n    -- Check permissions first (Whole sale return usually requires higher privilege)\n    SELECT p.role, p.workspace_id INTO v_user_role, v_workspace_id\n    FROM public.check_return_permissions(p_sale_id, auth.uid()) p;\n\n    IF v_user_role IS DISTINCT FROM 'admin' THEN\n        RAISE EXCEPTION 'Unauthorized: Only admins can return whole sales';\n    END IF;\n\n    -- Get all non-returned quantities\n    SELECT \n        array_agg(id),\n        array_agg(quantity - returned_quantity)\n    INTO v_item_ids, v_item_quantities\n    FROM public.sale_items\n    WHERE sale_id = p_sale_id AND is_returned = FALSE;\n\n    IF v_item_ids IS NULL OR array_length(v_item_ids, 1) = 0 THEN\n        RAISE EXCEPTION 'No returnable items found in this sale';\n    END IF;\n\n    -- Delegate to return_sale_items for consistency\n    RETURN public.return_sale_items(v_item_ids, v_item_quantities, p_return_reason);\nEND;\n$$;\n"}	consolidate_returns_unified	masteralan360@gmail.com	\N	\N
20260115225345	{"-- Update Sales Reports Functions to handle partial returns correctly\n-- Uses (quantity - returned_quantity) for accurate net calculations\n\n-- Function to get net revenue\nCREATE OR REPLACE FUNCTION public.get_net_revenue(\n    p_workspace_id UUID DEFAULT NULL,\n    p_start_date TIMESTAMPTZ DEFAULT NULL,\n    p_end_date TIMESTAMPTZ DEFAULT NULL\n)\nRETURNS TABLE (\n    total_revenue NUMERIC,\n    total_cost NUMERIC,\n    net_profit NUMERIC,\n    total_sales_count BIGINT,\n    total_items_count BIGINT\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    IF p_workspace_id IS NULL THEN\n        SELECT workspace_id INTO p_workspace_id FROM public.profiles WHERE id = auth.uid();\n    END IF;\n\n    RETURN QUERY\n    SELECT \n        COALESCE(SUM((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)), 0) as total_revenue,\n        COALESCE(SUM((si.quantity - si.returned_quantity) * si.cost_price), 0) as total_cost,\n        COALESCE(SUM(((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)) - ((si.quantity - si.returned_quantity) * si.cost_price)), 0) as net_profit,\n        COUNT(DISTINCT s.id) as total_sales_count,\n        SUM(si.quantity - si.returned_quantity) as total_items_count\n    FROM public.sales s\n    INNER JOIN public.sale_items si ON s.id = si.sale_id\n    WHERE s.workspace_id = p_workspace_id\n      AND COALESCE(s.is_returned, FALSE) = FALSE\n      AND (p_start_date IS NULL OR s.created_at >= p_start_date)\n      AND (p_end_date IS NULL OR s.created_at <= p_end_date);\nEND;\n$$;\n\n-- Function to get team performance\nCREATE OR REPLACE FUNCTION public.get_team_performance(\n    p_workspace_id UUID DEFAULT NULL,\n    p_start_date TIMESTAMPTZ DEFAULT NULL,\n    p_end_date TIMESTAMPTZ DEFAULT NULL\n)\nRETURNS TABLE (\n    cashier_id UUID,\n    cashier_name TEXT,\n    total_sales_count BIGINT,\n    total_revenue NUMERIC,\n    total_items_count BIGINT,\n    average_sale_value NUMERIC\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    IF p_workspace_id IS NULL THEN\n        SELECT workspace_id INTO p_workspace_id FROM public.profiles WHERE id = auth.uid();\n    END IF;\n\n    RETURN QUERY\n    SELECT \n        s.cashier_id,\n        COALESCE(p.name, 'Unknown') as cashier_name,\n        COUNT(DISTINCT s.id) as total_sales_count,\n        COALESCE(SUM((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)), 0) as total_revenue,\n        SUM(si.quantity - si.returned_quantity) as total_items_count,\n        COALESCE(AVG(s.total_amount), 0) as average_sale_value\n    FROM public.sales s\n    INNER JOIN public.sale_items si ON s.id = si.sale_id\n    LEFT JOIN public.profiles p ON s.cashier_id = p.id\n    WHERE s.workspace_id = p_workspace_id\n      AND COALESCE(s.is_returned, FALSE) = FALSE\n      AND (p_start_date IS NULL OR s.created_at >= p_start_date)\n      AND (p_end_date IS NULL OR s.created_at <= p_end_date)\n    GROUP BY s.cashier_id, p.name\n    ORDER BY total_revenue DESC;\nEND;\n$$;\n\n-- Function to get top selling products\nCREATE OR REPLACE FUNCTION public.get_top_products(\n    p_workspace_id UUID DEFAULT NULL,\n    p_start_date TIMESTAMPTZ DEFAULT NULL,\n    p_end_date TIMESTAMPTZ DEFAULT NULL,\n    p_limit INT DEFAULT 10\n)\nRETURNS TABLE (\n    product_id UUID,\n    product_name TEXT,\n    product_sku TEXT,\n    total_quantity_sold BIGINT,\n    total_revenue NUMERIC,\n    total_sales_count BIGINT\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    IF p_workspace_id IS NULL THEN\n        SELECT workspace_id INTO p_workspace_id FROM public.profiles WHERE id = auth.uid();\n    END IF;\n\n    RETURN QUERY\n    SELECT \n        pr.id as product_id,\n        pr.name as product_name,\n        pr.sku as product_sku,\n        SUM(si.quantity - si.returned_quantity) as total_quantity_sold,\n        COALESCE(SUM((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)), 0) as total_revenue,\n        COUNT(DISTINCT si.sale_id) as total_sales_count\n    FROM public.sale_items si\n    INNER JOIN public.sales s ON si.sale_id = s.id\n    INNER JOIN public.products pr ON si.product_id = pr.id\n    WHERE s.workspace_id = p_workspace_id\n      AND COALESCE(s.is_returned, FALSE) = FALSE\n      AND (p_start_date IS NULL OR s.created_at >= p_start_date)\n      AND (p_end_date IS NULL OR s.created_at <= p_end_date)\n    GROUP BY pr.id, pr.name, pr.sku\n    ORDER BY total_quantity_sold DESC\n    LIMIT p_limit;\nEND;\n$$;\n\n-- Function to get sales summary for dashboard\nCREATE OR REPLACE FUNCTION public.get_sales_summary(\n    p_workspace_id UUID DEFAULT NULL,\n    p_start_date TIMESTAMPTZ DEFAULT NULL,\n    p_end_date TIMESTAMPTZ DEFAULT NULL\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    result JSONB;\nBEGIN\n    IF p_workspace_id IS NULL THEN\n        SELECT workspace_id INTO p_workspace_id FROM public.profiles WHERE id = auth.uid();\n    END IF;\n\n    SELECT jsonb_build_object(\n        'totalRevenue', COALESCE(SUM(CASE WHEN COALESCE(s.is_returned, FALSE) = FALSE THEN (si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price) ELSE 0 END), 0),\n        'totalCost', COALESCE(SUM(CASE WHEN COALESCE(s.is_returned, FALSE) = FALSE THEN (si.quantity - si.returned_quantity) * si.cost_price ELSE 0 END), 0),\n        'netProfit', COALESCE(SUM(CASE WHEN COALESCE(s.is_returned, FALSE) = FALSE THEN ((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)) - ((si.quantity - si.returned_quantity) * si.cost_price) ELSE 0 END), 0),\n        'totalSales', COUNT(DISTINCT CASE WHEN COALESCE(s.is_returned, FALSE) = FALSE THEN s.id END),\n        'totalItems', SUM(CASE WHEN COALESCE(s.is_returned, FALSE) = FALSE THEN si.quantity - si.returned_quantity ELSE 0 END),\n        'averageSaleValue', COALESCE(AVG(CASE WHEN COALESCE(s.is_returned, FALSE) = FALSE THEN s.total_amount END), 0),\n        'returnedSales', COUNT(DISTINCT CASE WHEN s.is_returned = TRUE THEN s.id END),\n        'returnedItems', SUM(si.returned_quantity)\n    ) INTO result\n    FROM public.sales s\n    INNER JOIN public.sale_items si ON s.id = si.sale_id\n    WHERE s.workspace_id = p_workspace_id\n      AND (p_start_date IS NULL OR s.created_at >= p_start_date)\n      AND (p_end_date IS NULL OR s.created_at <= p_end_date);\n\n    RETURN result;\nEND;\n$$;\n"}	update_reports_for_partial_returns	masteralan360@gmail.com	\N	\N
20260115225854	{"-- Drop and recreate helper function to change return column name\nDROP FUNCTION IF EXISTS public.check_return_permissions(UUID, UUID);\n\nCREATE OR REPLACE FUNCTION public.check_return_permissions(\n    p_sale_id UUID,\n    p_user_id UUID\n)\nRETURNS TABLE (\n    workspace_id UUID,\n    role TEXT,\n    allow_pos BOOLEAN\n) \nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        s.workspace_id,\n        pr.role,\n        w.allow_pos\n    FROM public.sales s\n    JOIN public.profiles pr ON pr.id = p_user_id AND pr.workspace_id = s.workspace_id\n    JOIN public.workspaces w ON w.id = s.workspace_id\n    WHERE s.id = p_sale_id;\nEND;\n$$;\n"}	fix_return_permissions_column_name_v2	masteralan360@gmail.com	\N	\N
20260115230001	{"-- Fix non-existent updated_at column in sales table for returns\n-- This migration updates the unified return function to remove references to updated_at on the sales table\n\nCREATE OR REPLACE FUNCTION public.return_sale_items(\n    p_sale_item_ids UUID[],\n    p_return_quantities INTEGER[],\n    p_return_reason TEXT\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_item_record RECORD;\n    v_sale_record RECORD;\n    v_workspace_id UUID;\n    v_user_role TEXT;\n    v_allow_pos BOOLEAN;\n    v_index INTEGER;\n    v_total_return_value NUMERIC := 0;\n    v_sale_id UUID;\nBEGIN\n    -- Basic validation\n    IF p_sale_item_ids IS NULL OR array_length(p_sale_item_ids, 1) = 0 THEN\n        RAISE EXCEPTION 'No items selected for return';\n    END IF;\n\n    IF p_return_quantities IS NULL OR array_length(p_return_quantities, 1) != array_length(p_sale_item_ids, 1) THEN\n        RAISE EXCEPTION 'Invalid quantities provided for return';\n    END IF;\n\n    -- Get workspace and sale info from the first item\n    SELECT si.sale_id, s.workspace_id \n    INTO v_sale_id, v_workspace_id\n    FROM public.sale_items si\n    JOIN public.sales s ON s.id = si.sale_id\n    WHERE si.id = p_sale_item_ids[1];\n\n    IF v_sale_id IS NULL THEN\n        RAISE EXCEPTION 'Sale not found for the provided items';\n    END IF;\n\n    -- Check permissions using the fixed helper\n    SELECT p.workspace_id, p.role, p.allow_pos \n    INTO v_workspace_id, v_user_role, v_allow_pos\n    FROM public.check_return_permissions(v_sale_id, auth.uid()) p;\n\n    IF v_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'Unauthorized or workspace not found';\n    END IF;\n\n    IF NOT COALESCE(v_allow_pos, FALSE) THEN\n        RAISE EXCEPTION 'POS feature is not enabled for this workspace';\n    END IF;\n\n    IF v_user_role NOT IN ('admin', 'staff') THEN\n        RAISE EXCEPTION 'Unauthorized: Only admins and staff can return items';\n    END IF;\n\n    -- Process each item\n    FOR v_index IN 1..array_length(p_sale_item_ids, 1) LOOP\n        SELECT si.*, (si.quantity - si.returned_quantity) as available_quantity\n        INTO v_item_record\n        FROM public.sale_items si\n        WHERE si.id = p_sale_item_ids[v_index] AND si.sale_id = v_sale_id;\n\n        IF v_item_record IS NULL THEN\n            CONTINUE;\n        END IF;\n\n        IF p_return_quantities[v_index] <= 0 OR p_return_quantities[v_index] > v_item_record.available_quantity THEN\n            RAISE EXCEPTION 'Invalid return quantity for item %: must be between 1 and %', v_item_record.id, v_item_record.available_quantity;\n        END IF;\n\n        -- Calculate return value for this item\n        v_total_return_value := v_total_return_value + (p_return_quantities[v_index] * COALESCE(v_item_record.converted_unit_price, v_item_record.unit_price));\n\n        -- Update sale_item\n        UPDATE public.sale_items\n        SET \n            returned_quantity = returned_quantity + p_return_quantities[v_index],\n            return_reason = CASE \n                WHEN COALESCE(return_reason, '') = '' THEN p_return_reason\n                ELSE return_reason || '; ' || p_return_reason\n            END,\n            returned_at = NOW(),\n            returned_by = auth.uid(),\n            is_returned = CASE \n                WHEN (returned_quantity + p_return_quantities[v_index]) >= quantity THEN TRUE \n                ELSE FALSE \n            END\n        WHERE id = v_item_record.id;\n\n        -- Restore inventory\n        UPDATE public.products\n        SET quantity = quantity + p_return_quantities[v_index]\n        WHERE id = v_item_record.product_id AND workspace_id = v_workspace_id;\n    END LOOP;\n\n    -- Update main sale total (removed updated_at as it doesn't exist on sales table)\n    UPDATE public.sales\n    SET \n        total_amount = total_amount - v_total_return_value\n    WHERE id = v_sale_id;\n\n    -- Check if entire sale is now returned\n    UPDATE public.sales s\n    SET \n        is_returned = TRUE,\n        returned_at = NOW(),\n        returned_by = auth.uid(),\n        return_reason = CASE \n            WHEN COALESCE(return_reason, '') = '' THEN 'All items returned'\n            ELSE return_reason || '; All items returned'\n        END\n    WHERE id = v_sale_id \n      AND NOT EXISTS (\n          SELECT 1 FROM public.sale_items si \n          WHERE si.sale_id = v_sale_id AND si.is_returned = FALSE\n      );\n\n    RETURN jsonb_build_object(\n        'success', true, \n        'message', 'Items returned successfully',\n        'sale_id', v_sale_id,\n        'return_value', v_total_return_value\n    );\nEND;\n$$;\n"}	fix_sales_returns_updated_at_bug	masteralan360@gmail.com	\N	\N
