20260123182618	{"ALTER TABLE sales\nADD COLUMN IF NOT EXISTS system_verified boolean DEFAULT true,\nADD COLUMN IF NOT EXISTS system_review_status text DEFAULT 'approved' CHECK (system_review_status IN ('approved', 'flagged', 'inconsistent')),\nADD COLUMN IF NOT EXISTS system_review_reason text;\n\nALTER TABLE sale_items\nADD COLUMN IF NOT EXISTS inventory_snapshot integer DEFAULT 0;\n\nALTER TABLE workspaces\nADD COLUMN IF NOT EXISTS max_discount_percent integer DEFAULT 100;"}	add_verification_and_snapshot_columns	masteralan360@gmail.com	\N	\N
20260123182730	{"CREATE OR REPLACE FUNCTION public.complete_sale(payload JSONB)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    new_sale_id UUID;\n    item JSONB;\n    p_workspace_id UUID;\n    total_sale_amount NUMERIC := 0;\n    v_allow_pos BOOLEAN;\nBEGIN\n    -- Extract workspace_id from the first item or assume user has one. \n    -- Better: Get current user's workspace.\n    SELECT workspace_id INTO p_workspace_id \n    FROM public.profiles \n    WHERE id = auth.uid();\n\n    IF p_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'User does not belong to a workspace';\n    END IF;\n\n    -- Check if POS feature is enabled for this workspace\n    SELECT allow_pos INTO v_allow_pos\n    FROM public.workspaces\n    WHERE id = p_workspace_id;\n\n    IF NOT COALESCE(v_allow_pos, false) THEN\n        RAISE EXCEPTION 'POS feature is not enabled for this workspace';\n    END IF;\n\n    -- Calculate total (or trust payload? Trusting payload for now, but usually backend recalculates)\n    -- We will insert what frontend sends but verification of total usually happens here.\n    -- For simplicity/MVP, we extract `totalAmount` from payload or sum items.\n    \n    total_sale_amount := (payload->>'total_amount')::NUMERIC;\n\n    -- Insert Sale Record\n    INSERT INTO public.sales (\n        id,\n        workspace_id, \n        cashier_id, \n        total_amount, \n        settlement_currency,\n        exchange_source,\n        exchange_rate,\n        exchange_rate_timestamp,\n        exchange_rates,\n        origin,\n        payment_method,\n        system_verified,\n        system_review_status,\n        system_review_reason\n    )\n    VALUES (\n        COALESCE((payload->>'id')::UUID, gen_random_uuid()),\n        p_workspace_id, \n        auth.uid(), \n        total_sale_amount, \n        COALESCE(payload->>'settlement_currency', 'usd'),\n        COALESCE(payload->>'exchange_source', 'xeiqd'),\n        COALESCE((payload->>'exchange_rate')::NUMERIC, 0),\n        COALESCE((payload->>'exchange_rate_timestamp')::TIMESTAMPTZ, NOW()),\n        COALESCE((payload->'exchange_rates'), '[]'::jsonb),\n        COALESCE(payload->>'origin', 'pos'),\n        COALESCE(payload->>'payment_method', 'cash'),\n        COALESCE((payload->>'system_verified')::BOOLEAN, true),\n        COALESCE(payload->>'system_review_status', 'approved'),\n        payload->>'system_review_reason'\n    )\n    RETURNING id INTO new_sale_id;\n\n    -- Process Items\n    FOR item IN SELECT * FROM jsonb_array_elements(payload->'items')\n    LOOP\n        -- Insert Sale Item\n        INSERT INTO public.sale_items (\n            sale_id, \n            product_id, \n            quantity, \n            unit_price, \n            total_price,\n            cost_price,\n            converted_cost_price,\n            original_currency,\n            original_unit_price,\n            converted_unit_price,\n            settlement_currency,\n            negotiated_price,\n            inventory_snapshot\n        )\n        VALUES (\n            new_sale_id,\n            (item->>'product_id')::UUID,\n            (item->>'quantity')::INTEGER,\n            (item->>'unit_price')::NUMERIC,\n            (item->>'total_price')::NUMERIC,\n            COALESCE((item->>'cost_price')::NUMERIC, 0),\n            COALESCE((item->>'converted_cost_price')::NUMERIC, 0),\n            COALESCE(item->>'original_currency', 'usd'),\n            COALESCE((item->>'original_unit_price')::NUMERIC, (item->>'unit_price')::NUMERIC),\n            COALESCE((item->>'converted_unit_price')::NUMERIC, (item->>'unit_price')::NUMERIC),\n            COALESCE(item->>'settlement_currency', 'usd'),\n            (item->>'negotiated_price')::NUMERIC,\n            COALESCE((item->>'inventory_snapshot')::INTEGER, 0)\n        );\n\n        -- Update Inventory\n        UPDATE public.products\n        SET quantity = quantity - (item->>'quantity')::INTEGER\n        WHERE id = (item->>'product_id')::UUID\n          AND workspace_id = p_workspace_id;\n          \n        -- Optional: Check for negative stock if enforced?\n    END LOOP;\n\n    RETURN jsonb_build_object('success', true, 'sale_id', new_sale_id);\nEND;\n$$;"}	update_complete_sale_rpc_for_verification	masteralan360@gmail.com	\N	\N
20260123194321	{"CREATE OR REPLACE FUNCTION public.return_sale_items(\n    p_sale_item_ids UUID[],\n    p_return_quantities INTEGER[],\n    p_return_reason TEXT\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    item_record RECORD;\n    p_workspace_id UUID;\n    v_user_role TEXT;\n    v_allow_pos BOOLEAN;\n    sale_id UUID;\n    v_index INTEGER;\nBEGIN\n    -- Check if arrays are empty or mismatched\n    IF p_sale_item_ids IS NULL OR array_length(p_sale_item_ids, 1) IS NULL THEN\n        RAISE EXCEPTION 'No items selected for return';\n    END IF;\n    \n    IF p_return_quantities IS NULL OR array_length(p_return_quantities, 1) IS NULL THEN\n        RAISE EXCEPTION 'No quantities provided for return';\n    END IF;\n    \n    IF array_length(p_sale_item_ids, 1) != array_length(p_return_quantities, 1) THEN\n        RAISE EXCEPTION 'Items and quantities arrays must have the same length';\n    END IF;\n\n    -- Get first item to determine workspace and sale\n    SELECT si.*, s.workspace_id\n    INTO item_record\n    FROM public.sale_items si\n    JOIN public.sales s ON s.id = si.sale_id\n    WHERE si.id = ANY(p_sale_item_ids)\n    LIMIT 1;\n    \n    -- Extract workspace_id from the record\n    p_workspace_id := item_record.workspace_id;\n    \n    IF item_record IS NULL THEN\n        RAISE EXCEPTION 'Sale items not found';\n    END IF;\n\n    -- Check if POS feature is enabled\n    SELECT allow_pos INTO v_allow_pos\n    FROM public.workspaces\n    WHERE id = p_workspace_id;\n\n    IF NOT COALESCE(v_allow_pos, false) THEN\n        RAISE EXCEPTION 'POS feature is not enabled for this workspace';\n    END IF;\n\n    -- Check user permissions (Admin or Staff can return items)\n    SELECT role INTO v_user_role\n    FROM public.profiles \n    WHERE id = auth.uid() \n    AND workspace_id = p_workspace_id;\n\n    IF v_user_role NOT IN ('admin', 'staff') THEN\n        RAISE EXCEPTION 'Unauthorized: Only admins and staff can return items';\n    END IF;\n\n    -- Process each item with its quantity\n    FOR v_index IN 1..array_length(p_sale_item_ids, 1) LOOP\n        -- Get the current item\n        SELECT si.*, s.id as sale_id\n        INTO item_record\n        FROM public.sale_items si\n        JOIN public.sales s ON s.id = si.sale_id\n        WHERE si.id = p_sale_item_ids[v_index];\n        \n        -- Check if item exists\n        IF item_record IS NULL THEN\n            CONTINUE; -- Skip if item not found\n        END IF;\n        \n        -- Check if item is already fully returned\n        IF item_record.is_returned = TRUE THEN\n            CONTINUE; -- Skip already returned items\n        END IF;\n        \n        -- Validate return quantity\n        -- Allow returning remaining quantity: quantity - returned_quantity\n        IF p_return_quantities[v_index] <= 0 OR p_return_quantities[v_index] > (item_record.quantity - COALESCE(item_record.returned_quantity, 0)) THEN\n            RAISE EXCEPTION 'Invalid return quantity for item %: exceeds remaining quantity', item_record.id;\n        END IF;\n        \n        -- Check if this is a partial return or full return (based on cumulative returns)\n        IF (COALESCE(item_record.returned_quantity, 0) + p_return_quantities[v_index]) >= item_record.quantity THEN\n            -- Full return (cumulative) - mark item as returned\n            UPDATE public.sale_items\n            SET \n                is_returned = TRUE,\n                return_reason = CASE \n                    WHEN COALESCE(returned_quantity, 0) = 0 THEN p_return_reason\n                    ELSE COALESCE(return_reason, '') || ', ' || p_return_reason\n                END,\n                returned_at = NOW(),\n                returned_by = auth.uid(),\n                returned_quantity = COALESCE(returned_quantity, 0) + p_return_quantities[v_index]\n            WHERE id = item_record.id;\n        ELSE\n            -- Partial return - update returned_quantity ONLY\n            UPDATE public.sale_items\n            SET \n                returned_quantity = COALESCE(returned_quantity, 0) + p_return_quantities[v_index],\n                return_reason = CASE \n                    WHEN COALESCE(returned_quantity, 0) = 0 THEN p_return_reason\n                    ELSE COALESCE(return_reason, '') || ', ' || p_return_reason\n                END,\n                returned_at = NOW(),\n                returned_by = CASE \n                    WHEN COALESCE(returned_quantity, 0) = 0 THEN auth.uid()\n                    ELSE COALESCE(returned_by, auth.uid())\n                END\n            WHERE id = item_record.id;\n        END IF;\n        \n        -- Restore inventory for returned quantity\n        UPDATE public.products\n        SET quantity = quantity + p_return_quantities[v_index]\n        WHERE id = item_record.product_id\n          AND workspace_id = p_workspace_id;\n    END LOOP;\n\n    RETURN jsonb_build_object('success', true, 'message', 'Items returned successfully');\nEND;\n$$;"}	fix_return_sale_items_rpc_logic	masteralan360@gmail.com	\N	\N
20260123220236	{"ALTER TABLE sales ADD COLUMN IF NOT EXISTS sequence_id BIGINT GENERATED BY DEFAULT AS IDENTITY;"}	add_sequence_id_to_sales	masteralan360@gmail.com	\N	\N
20260124192703	{"ALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS logo_url TEXT;\n\nCREATE OR REPLACE FUNCTION public.configure_workspace(\n    p_allow_pos boolean DEFAULT false, \n    p_allow_customers boolean DEFAULT false, \n    p_allow_orders boolean DEFAULT false, \n    p_allow_invoices boolean DEFAULT false,\n    p_logo_url TEXT DEFAULT NULL\n)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_workspace_id UUID;\n    v_user_role TEXT;\nBEGIN\n    -- Get user's workspace and role\n    SELECT workspace_id, role INTO v_workspace_id, v_user_role\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'User does not belong to a workspace';\n    END IF;\n\n    IF v_user_role != 'admin' THEN\n        RAISE EXCEPTION 'Unauthorized: Only admins can configure workspace features';\n    END IF;\n\n    -- Update workspace with feature flags and logo\n    UPDATE public.workspaces\n    SET \n        allow_pos = p_allow_pos,\n        allow_customers = p_allow_customers,\n        allow_orders = p_allow_orders,\n        allow_invoices = p_allow_invoices,\n        logo_url = p_logo_url,\n        is_configured = true\n    WHERE id = v_workspace_id;\n\n    RETURN jsonb_build_object(\n        'success', true,\n        'allow_pos', p_allow_pos,\n        'allow_customers', p_allow_customers,\n        'allow_orders', p_allow_orders,\n        'allow_invoices', p_allow_invoices,\n        'logo_url', p_logo_url\n    );\nEND;\n$function$;"}	add_workspace_logo_url	masteralan360@gmail.com	\N	\N
20260124234718	{"-- Ensure column exists\nALTER TABLE public.workspaces \nADD COLUMN IF NOT EXISTS allow_whatsapp BOOLEAN DEFAULT false;\n\n-- Drop existing function to change return type\nDROP FUNCTION IF EXISTS public.get_workspace_features();\n\n-- Recreate with new schema\nCREATE OR REPLACE FUNCTION public.get_workspace_features()\nRETURNS TABLE (\n    allow_pos boolean,\n    allow_customers boolean,\n    allow_orders boolean,\n    allow_invoices boolean,\n    is_configured boolean,\n    default_currency text,\n    iqd_display_preference text,\n    workspace_name text,\n    eur_conversion_enabled boolean,\n    try_conversion_enabled boolean,\n    locked_workspace boolean,\n    allow_whatsapp boolean\n) AS $$\nDECLARE\n    p_workspace_id UUID;\nBEGIN\n    -- Get current user's workspace\n    SELECT workspace_id INTO p_workspace_id \n    FROM public.profiles \n    WHERE id = auth.uid();\n\n    IF p_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'User does not belong to a workspace';\n    END IF;\n\n    RETURN QUERY\n    SELECT \n        w.allow_pos,\n        w.allow_customers,\n        w.allow_orders,\n        w.allow_invoices,\n        w.is_configured,\n        w.default_currency,\n        COALESCE(w.iqd_display_preference, 'IQD')::TEXT,\n        w.name as workspace_name,\n        COALESCE(w.eur_conversion_enabled, false),\n        COALESCE(w.try_conversion_enabled, false),\n        COALESCE(w.locked_workspace, false),\n        COALESCE(w.allow_whatsapp, false)\n    FROM public.workspaces w\n    WHERE w.id = p_workspace_id;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n"}	recreate_get_workspace_features_rpc	masteralan360@gmail.com	\N	\N
20260126185408	{"-- Consolidated Workspace Settings & RPC Fix\n-- Redefines the RPCs to include all workspace configuration fields\n\n-- 1. Update get_workspace_features RPC\n-- This is used by the frontend on every refresh/initialization\nDROP FUNCTION IF EXISTS public.get_workspace_features();\n\nCREATE OR REPLACE FUNCTION public.get_workspace_features()\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    -- Get user's workspace\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_customers', false,\n            'allow_orders', false,\n            'allow_invoices', false,\n            'is_configured', false\n        );\n    END IF;\n\n    -- Get ALL workspace features and settings\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'allow_pos', COALESCE(allow_pos, false),\n        'allow_customers', COALESCE(allow_customers, false),\n        'allow_orders', COALESCE(allow_orders, false),\n        'allow_invoices', COALESCE(allow_invoices, false),\n        'is_configured', COALESCE(is_configured, false),\n        'default_currency', COALESCE(default_currency, 'usd'),\n        'iqd_display_preference', COALESCE(iqd_display_preference, 'IQD'),\n        'eur_conversion_enabled', COALESCE(eur_conversion_enabled, false),\n        'try_conversion_enabled', COALESCE(try_conversion_enabled, false),\n        'locked_workspace', COALESCE(locked_workspace, false),\n        'logo_url', logo_url,\n        'max_discount_percent', COALESCE(max_discount_percent, 100),\n        'allow_whatsapp', COALESCE(allow_whatsapp, false)\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN v_result;\nEND;\n$$;\n\n-- 2. Update admin_get_all_workspaces\n-- Ensures Super-Admins can see all these settings in the admin dashboard\nDROP FUNCTION IF EXISTS public.get_all_workspaces(text);\n\nCREATE OR REPLACE FUNCTION public.get_all_workspaces(provided_key TEXT)\nRETURNS TABLE (\n    id UUID,\n    name TEXT,\n    code TEXT,\n    created_at TIMESTAMPTZ,\n    allow_pos BOOLEAN,\n    allow_customers BOOLEAN,\n    allow_orders BOOLEAN,\n    allow_invoices BOOLEAN,\n    is_configured BOOLEAN,\n    deleted_at TIMESTAMPTZ,\n    logo_url TEXT,\n    allow_whatsapp BOOLEAN,\n    locked_workspace BOOLEAN\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    IF NOT public.verify_admin_passkey(provided_key) THEN\n        RAISE EXCEPTION 'Unauthorized: Invalid admin passkey';\n    END IF;\n\n    RETURN QUERY\n    SELECT \n        w.id,\n        w.name,\n        w.code,\n        w.created_at,\n        COALESCE(w.allow_pos, false),\n        COALESCE(w.allow_customers, false),\n        COALESCE(w.allow_orders, false),\n        COALESCE(w.allow_invoices, false),\n        COALESCE(w.is_configured, false),\n        w.deleted_at,\n        w.logo_url,\n        COALESCE(w.allow_whatsapp, false),\n        COALESCE(w.locked_workspace, false)\n    FROM public.workspaces w\n    ORDER BY w.created_at DESC;\nEND;\n$$;\n"}	fix_workspace_rpc_consolidation	masteralan360@gmail.com	\N	\N
20260127171746	{"-- =============================================================================\n-- P2P Sync Queue Migration\n-- Enables Store-and-Forward image synchronization between workspace users\n-- =============================================================================\n\n-- Create the sync_queue table\nCREATE TABLE IF NOT EXISTS public.sync_queue (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n    uploader_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,\n    file_name TEXT NOT NULL,\n    storage_path TEXT NOT NULL,\n    file_size BIGINT DEFAULT 0,\n    synced_by JSONB NOT NULL DEFAULT '[]'::jsonb,\n    expires_at TIMESTAMPTZ NOT NULL DEFAULT (now() + INTERVAL '48 hours')\n);\n\n-- Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_sync_queue_workspace_id ON public.sync_queue(workspace_id);\nCREATE INDEX IF NOT EXISTS idx_sync_queue_expires_at ON public.sync_queue(expires_at);\n\n-- Enable RLS\nALTER TABLE public.sync_queue ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies\n-- Members can view items in their workspace (via profiles.workspace_id)\nCREATE POLICY \\"sync_queue_select_policy\\" ON public.sync_queue\n    FOR SELECT\n    USING (\n        workspace_id = (SELECT workspace_id FROM public.profiles WHERE id = auth.uid())\n    );\n\n-- Members can insert items\nCREATE POLICY \\"sync_queue_insert_policy\\" ON public.sync_queue\n    FOR INSERT\n    WITH CHECK (\n        workspace_id = (SELECT workspace_id FROM public.profiles WHERE id = auth.uid())\n        AND uploader_id = auth.uid()\n    );\n\n-- Members can update (to mark as synced)\nCREATE POLICY \\"sync_queue_update_policy\\" ON public.sync_queue\n    FOR UPDATE\n    USING (\n        workspace_id = (SELECT workspace_id FROM public.profiles WHERE id = auth.uid())\n    );\n\n-- Members can delete (for cleanup)\nCREATE POLICY \\"sync_queue_delete_policy\\" ON public.sync_queue\n    FOR DELETE\n    USING (\n        workspace_id = (SELECT workspace_id FROM public.profiles WHERE id = auth.uid())\n    );\n\n-- Grant access\nGRANT ALL ON public.sync_queue TO authenticated;\nGRANT ALL ON public.sync_queue TO service_role;"}	p2p_sync_queue	masteralan360@gmail.com	\N	\N
20260127193641	{"ALTER TABLE workspaces ADD COLUMN IF NOT EXISTS member_count INTEGER DEFAULT 0;\n\nCREATE INDEX IF NOT EXISTS idx_profiles_workspace_id ON profiles(workspace_id);\n\nCREATE OR REPLACE FUNCTION update_workspace_member_count()\nRETURNS TRIGGER AS $$\nBEGIN\n    IF (TG_OP = 'INSERT') THEN\n        IF NEW.workspace_id IS NOT NULL THEN\n            UPDATE workspaces SET member_count = member_count + 1 WHERE id = NEW.workspace_id;\n        END IF;\n    ELSIF (TG_OP = 'DELETE') THEN\n        IF OLD.workspace_id IS NOT NULL THEN\n            UPDATE workspaces SET member_count = member_count - 1 WHERE id = OLD.workspace_id;\n        END IF;\n    ELSIF (TG_OP = 'UPDATE') THEN\n        IF OLD.workspace_id IS DISTINCT FROM NEW.workspace_id THEN\n            IF OLD.workspace_id IS NOT NULL THEN\n                UPDATE workspaces SET member_count = member_count - 1 WHERE id = OLD.workspace_id;\n            END IF;\n            IF NEW.workspace_id IS NOT NULL THEN\n                UPDATE workspaces SET member_count = member_count + 1 WHERE id = NEW.workspace_id;\n            END IF;\n        END IF;\n    END IF;\n    RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nDROP TRIGGER IF EXISTS trg_workspace_member_count ON profiles;\nCREATE TRIGGER trg_workspace_member_count\nAFTER INSERT OR UPDATE OF workspace_id OR DELETE ON profiles\nFOR EACH ROW\nEXECUTE FUNCTION update_workspace_member_count();\n\nUPDATE workspaces SET member_count = (SELECT count(*) FROM profiles WHERE profiles.workspace_id = workspaces.id);"}	add_member_count	masteralan360@gmail.com	\N	\N
20260127194637	{"create or replace function acknowledge_p2p_sync(\n  p_queue_id uuid,\n  p_user_id uuid\n)\nreturns table (\n  is_complete boolean,\n  storage_path text,\n  file_name text\n)\nlanguage plpgsql\nsecurity definer\nas $$\ndeclare\n  v_workspace_id uuid;\n  v_member_count int;\n  v_current_synced jsonb; \n  v_storage_path text;\n  v_file_name text;\n  v_synced_array text[];\nbegin\n  -- 1. Get current item details\n  select workspace_id, storage_path, file_name, synced_by\n  into v_workspace_id, v_storage_path, v_file_name, v_current_synced\n  from sync_queue\n  where id = p_queue_id;\n\n  if v_workspace_id is null then\n    return; -- Item gone already\n  end if;\n\n  -- 2. Update if not present using JSONB containment\n  if not (v_current_synced @> to_jsonb(p_user_id::text)) then\n    -- Append to JSONB array properly\n    -- If it's single value, wrap it. If array, append.\n    -- Better: use jsonb_set or simple concatenation if it's an array\n    update sync_queue\n    set synced_by = coalesce(synced_by, '[]'::jsonb) || to_jsonb(p_user_id::text)\n    where id = p_queue_id\n    returning synced_by into v_current_synced;\n  end if;\n\n  -- 3. Get Workspace Member Count\n  select member_count into v_member_count\n  from workspaces\n  where id = v_workspace_id;\n\n  -- 4. Convert JSONB array to text array for length check or just use jsonb_array_length\n  if jsonb_array_length(v_current_synced) >= v_member_count then\n    return query select true, v_storage_path, v_file_name;\n  else\n    return query select false, v_storage_path, v_file_name;\n  end if;\nend;\n$$;"}	add_p2p_ack_rpc	masteralan360@gmail.com	\N	\N
20260127195456	{"create or replace function acknowledge_p2p_sync(\n  p_queue_id uuid,\n  p_user_id uuid\n)\nreturns table (\n  is_complete boolean,\n  storage_path text,\n  file_name text\n)\nlanguage plpgsql\nsecurity definer\nas $$\ndeclare\n  v_workspace_id uuid;\n  v_member_count int;\n  v_current_synced jsonb;\n  v_storage_path text;\n  v_file_name text;\nbegin\n  -- 1. Get current item details\n  select sq.workspace_id, sq.storage_path, sq.file_name, sq.synced_by\n  into v_workspace_id, v_storage_path, v_file_name, v_current_synced\n  from sync_queue sq\n  where sq.id = p_queue_id;\n\n  if v_workspace_id is null then\n    return;\n  end if;\n\n  -- 2. Update if not present\n  if not (v_current_synced @> to_jsonb(p_user_id::text)) then\n    update sync_queue sq\n    set synced_by = coalesce(sq.synced_by, '[]'::jsonb) || to_jsonb(p_user_id::text)\n    where sq.id = p_queue_id\n    returning sq.synced_by into v_current_synced;\n  end if;\n\n  -- 3. Get Workspace Member Count\n  select w.member_count into v_member_count\n  from workspaces w\n  where w.id = v_workspace_id;\n\n  -- 4. Check completion\n  if jsonb_array_length(v_current_synced) >= v_member_count then\n    return query select true, v_storage_path, v_file_name;\n  else\n    return query select false, v_storage_path, v_file_name;\n  end if;\nend;\n$$;"}	fix_p2p_rpc_ambiguity	masteralan360@gmail.com	\N	\N
20260127214003	{"alter table public.sync_queue add column if not exists uploader_session_id uuid;\ncomment on column public.sync_queue.uploader_session_id is 'The specific session ID of the uploader to avoid self-sync on same device';"}	add_uploader_session_id_to_sync_queue	masteralan360@gmail.com	\N	\N
20260127214040	{"DROP FUNCTION IF EXISTS acknowledge_p2p_sync(uuid, uuid);\n\nCREATE OR REPLACE FUNCTION acknowledge_p2p_sync(p_queue_id uuid, p_session_id uuid)\nRETURNS TABLE(is_complete boolean, storage_path text, file_name text) \nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, auth\nAS $$\ndeclare\n  v_workspace_id uuid;\n  v_session_count int;\n  v_current_synced jsonb;\n  v_storage_path text;\n  v_file_name text;\nbegin\n  -- 1. Get current item details\n  select sq.workspace_id, sq.storage_path, sq.file_name, sq.synced_by\n  into v_workspace_id, v_storage_path, v_file_name, v_current_synced\n  from sync_queue sq\n  where sq.id = p_queue_id;\n\n  if v_workspace_id is null then\n    return;\n  end if;\n\n  -- 2. Update if not present (track by session_id)\n  if not (v_current_synced @> to_jsonb(p_session_id::text)) then\n    update sync_queue sq\n    set synced_by = coalesce(sq.synced_by, '[]'::jsonb) || to_jsonb(p_session_id::text)\n    where sq.id = p_queue_id\n    returning sq.synced_by into v_current_synced;\n  end if;\n\n  -- 3. Get Workspace Total Session Count\n  -- Join auth.sessions with profiles table to target direct workspace\n  select count(s.id) into v_session_count\n  from auth.sessions s\n  join public.profiles p on s.user_id = p.id\n  where p.workspace_id = v_workspace_id;\n\n  -- 4. Check completion\n  if jsonb_array_length(v_current_synced) >= v_session_count then\n    return query select true, v_storage_path, v_file_name;\n  else\n    return query select false, v_storage_path, v_file_name;\n  end if;\nend;\n$$;"}	update_acknowledge_p2p_sync_for_sessions	masteralan360@gmail.com	\N	\N
20260127222911	{"CREATE OR REPLACE FUNCTION public.check_registration_passkey()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\ndeclare\n    provided_key text;\n    requested_role text;\n    required_key_name text;\n    valid_key text;\n    general_key text;\nbegin\n    provided_key := NEW.raw_user_meta_data->>'passkey';\n    requested_role := NEW.raw_user_meta_data->>'role';\n    \n    if requested_role is null then\n        raise exception 'Role is required for registration';\n    end if;\n\n    case requested_role\n        when 'admin' then required_key_name := 'admin_passkey';\n        when 'staff' then required_key_name := 'staff_passkey';\n        when 'viewer' then required_key_name := 'viewer_passkey';\n        else raise exception 'Invalid role requested: %', requested_role;\n    end case;\n\n    -- Get the role-specific key\n    select key_value into valid_key from public.app_permissions where key_name = required_key_name;\n    -- Get the general registration key as fallback\n    select key_value into general_key from public.app_permissions where key_name = 'registration_passkey';\n\n    if provided_key is null or (provided_key != valid_key and provided_key != general_key) then\n        raise exception 'Invalid Access Code. For %, please use the correct passkey.', requested_role;\n    end if;\n    \n    return NEW;\nend;\n$function$;"}	fix_registration_passkey_trigger	masteralan360@gmail.com	\N	\N
20260127223531	{"CREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\ndeclare\n    raw_ws_id text;\n    valid_ws_id uuid;\nbegin\n    raw_ws_id := new.raw_user_meta_data->>'workspace_id';\n    \n    -- Safely parse UUID\n    if raw_ws_id is not null and raw_ws_id != '' then\n        begin\n            valid_ws_id := raw_ws_id::uuid;\n        exception when others then\n            valid_ws_id := null;\n        end;\n    else\n        valid_ws_id := null;\n    end if;\n\n    INSERT INTO public.profiles (id, name, role, workspace_id)\n    VALUES (\n        new.id,\n        new.raw_user_meta_data->>'name',\n        new.raw_user_meta_data->>'role',\n        valid_ws_id\n    );\n    RETURN new;\nEND;\n$function$;"}	resilient_handle_new_user	masteralan360@gmail.com	\N	\N
20260127225037	{"CREATE OR REPLACE FUNCTION public.update_workspace_member_count()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nbegin\n    if (TG_OP = 'INSERT' and NEW.workspace_id is not null) then\n        update public.workspaces set member_count = member_count + 1 where id = NEW.workspace_id;\n    elsif (TG_OP = 'DELETE' and OLD.workspace_id is not null) then\n        update public.workspaces set member_count = member_count - 1 where id = OLD.workspace_id;\n    elsif (TG_OP = 'UPDATE') then\n        if (OLD.workspace_id is distinct from NEW.workspace_id) then\n            if (OLD.workspace_id is not null) then\n                update public.workspaces set member_count = member_count - 1 where id = OLD.workspace_id;\n            end if;\n            if (NEW.workspace_id is not null) then\n                update public.workspaces set member_count = member_count + 1 where id = NEW.workspace_id;\n            end if;\n        end if;\n    end if;\n    return NEW;\nend;\n$function$;"}	fix_member_count_trigger_schema	masteralan360@gmail.com	\N	\N
20260127225057	{"CREATE OR REPLACE FUNCTION public.check_registration_passkey()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\ndeclare\n    provided_key text;\n    requested_role text;\n    required_key_name text;\n    valid_key text;\n    general_key text;\nbegin\n    provided_key := NEW.raw_user_meta_data->>'passkey';\n    requested_role := NEW.raw_user_meta_data->>'role';\n    \n    if requested_role is null then\n        raise exception 'Role is required for registration. Meta: %', NEW.raw_user_meta_data;\n    end if;\n\n    case requested_role\n        when 'admin' then required_key_name := 'admin_passkey';\n        when 'staff' then required_key_name := 'staff_passkey';\n        when 'viewer' then required_key_name := 'viewer_passkey';\n        else raise exception 'Invalid role requested: %. Meta: %', requested_role, NEW.raw_user_meta_data;\n    end case;\n\n    -- Get the role-specific key\n    select key_value into valid_key from public.app_permissions where key_name = required_key_name;\n    -- Get the general registration key as fallback\n    select key_value into general_key from public.app_permissions where key_name = 'registration_passkey';\n\n    if provided_key is null or (provided_key != coalesce(valid_key, 'MISSING') and provided_key != coalesce(general_key, 'MISSING')) then\n        raise exception 'Invalid Passkey provided: \\"%\\". For role: %. (Expected role-specific or general key)', provided_key, requested_role;\n    end if;\n    \n    return NEW;\nend;\n$function$;"}	verbose_passkey_check	masteralan360@gmail.com	\N	\N
20260128201007	{"ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS profile_url TEXT;\n\n-- Update RLS if needed (assuming profiles is already manageable by the user)\n-- This ensures users can update their own profile_url\nDO $$ \nBEGIN\n    IF EXISTS (\n        SELECT 1 FROM pg_policies \n        WHERE tablename = 'profiles' AND policyname = 'Users can update own profile'\n    ) THEN\n        -- Policy already exists, common pattern in this project\n    ELSE\n        CREATE POLICY \\"Users can update own profile\\" ON public.profiles\n            FOR UPDATE USING (auth.uid() = id);\n    END IF;\nEND $$;"}	add_profile_url_to_profiles	masteralan360@gmail.com	\N	\N
