20260202221332	{"-- Drop old tables\nDROP TABLE IF EXISTS orders CASCADE;\nDROP TABLE IF EXISTS customers CASCADE;\n\n-- Create suppliers\nCREATE TABLE suppliers (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    workspace_id UUID NOT NULL,\n    created_by UUID REFERENCES auth.users(id),\n    name TEXT NOT NULL,\n    contact_name TEXT,\n    phone TEXT,\n    email TEXT,\n    address TEXT,\n    notes TEXT,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\n-- RLS for suppliers\nALTER TABLE suppliers ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Users can view workspace suppliers\\" ON suppliers FOR SELECT USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can insert workspace suppliers\\" ON suppliers FOR INSERT WITH CHECK ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can update workspace suppliers\\" ON suppliers FOR UPDATE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can delete workspace suppliers\\" ON suppliers FOR DELETE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\n-- Create customers (new schema)\nCREATE TABLE customers (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    workspace_id UUID NOT NULL,\n    created_by UUID REFERENCES auth.users(id),\n    name TEXT NOT NULL,\n    contact_name TEXT,\n    phone TEXT,\n    email TEXT,\n    address TEXT,\n    credit_limit DECIMAL(12, 2) DEFAULT 0,\n    current_balance DECIMAL(12, 2) DEFAULT 0,\n    notes TEXT,\n    total_orders INTEGER DEFAULT 0,\n    total_spent DECIMAL(12, 2) DEFAULT 0,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\n-- RLS for customers\nALTER TABLE customers ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Users can view workspace customers\\" ON customers FOR SELECT USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can insert workspace customers\\" ON customers FOR INSERT WITH CHECK ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can update workspace customers\\" ON customers FOR UPDATE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can delete workspace customers\\" ON customers FOR DELETE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\n-- Create purchase_orders\nCREATE TABLE purchase_orders (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    workspace_id UUID NOT NULL,\n    created_by UUID REFERENCES auth.users(id),\n    supplier_id UUID REFERENCES suppliers(id) ON DELETE SET NULL,\n    order_number TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'pending',\n    payment_status TEXT NOT NULL DEFAULT 'unpaid',\n    subtotal DECIMAL(12, 2) DEFAULT 0,\n    tax DECIMAL(12, 2) DEFAULT 0,\n    discount DECIMAL(12, 2) DEFAULT 0,\n    total DECIMAL(12, 2) DEFAULT 0,\n    notes TEXT,\n    expected_date TIMESTAMP WITH TIME ZONE,\n    received_at TIMESTAMP WITH TIME ZONE,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\n-- RLS for purchase_orders\nALTER TABLE purchase_orders ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Users can view workspace purchase_orders\\" ON purchase_orders FOR SELECT USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can insert workspace purchase_orders\\" ON purchase_orders FOR INSERT WITH CHECK ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can update workspace purchase_orders\\" ON purchase_orders FOR UPDATE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can delete workspace purchase_orders\\" ON purchase_orders FOR DELETE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\n-- Create purchase_order_items\nCREATE TABLE purchase_order_items (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    workspace_id UUID NOT NULL,\n    order_id UUID NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE,\n    product_id UUID REFERENCES products(id) ON DELETE SET NULL,\n    product_name TEXT NOT NULL,\n    quantity INTEGER NOT NULL DEFAULT 1,\n    unit_price DECIMAL(12, 2) NOT NULL DEFAULT 0,\n    total DECIMAL(12, 2) NOT NULL DEFAULT 0,\n    received_quantity INTEGER DEFAULT 0\n);\n\n-- RLS for purchase_order_items\nALTER TABLE purchase_order_items ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Users can view workspace purchase_order_items\\" ON purchase_order_items FOR SELECT USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can insert workspace purchase_order_items\\" ON purchase_order_items FOR INSERT WITH CHECK ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can update workspace purchase_order_items\\" ON purchase_order_items FOR UPDATE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can delete workspace purchase_order_items\\" ON purchase_order_items FOR DELETE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\n-- Create sales_orders\nCREATE TABLE sales_orders (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    workspace_id UUID NOT NULL,\n    created_by UUID REFERENCES auth.users(id),\n    customer_id UUID REFERENCES customers(id) ON DELETE SET NULL,\n    order_number TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'pending',\n    payment_status TEXT NOT NULL DEFAULT 'unpaid',\n    subtotal DECIMAL(12, 2) DEFAULT 0,\n    tax DECIMAL(12, 2) DEFAULT 0,\n    discount DECIMAL(12, 2) DEFAULT 0,\n    total DECIMAL(12, 2) DEFAULT 0,\n    notes TEXT,\n    shipping_address TEXT,\n    invoice_id UUID,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n\n-- RLS for sales_orders\nALTER TABLE sales_orders ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Users can view workspace sales_orders\\" ON sales_orders FOR SELECT USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can insert workspace sales_orders\\" ON sales_orders FOR INSERT WITH CHECK ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can update workspace sales_orders\\" ON sales_orders FOR UPDATE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can delete workspace sales_orders\\" ON sales_orders FOR DELETE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\n-- Create sales_order_items\nCREATE TABLE sales_order_items (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    workspace_id UUID NOT NULL,\n    order_id UUID NOT NULL REFERENCES sales_orders(id) ON DELETE CASCADE,\n    product_id UUID REFERENCES products(id) ON DELETE SET NULL,\n    product_name TEXT NOT NULL,\n    quantity INTEGER NOT NULL DEFAULT 1,\n    unit_price DECIMAL(12, 2) NOT NULL DEFAULT 0,\n    total DECIMAL(12, 2) NOT NULL DEFAULT 0\n);\n\n-- RLS for sales_order_items\nALTER TABLE sales_order_items ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"Users can view workspace sales_order_items\\" ON sales_order_items FOR SELECT USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can insert workspace sales_order_items\\" ON sales_order_items FOR INSERT WITH CHECK ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can update workspace sales_order_items\\" ON sales_order_items FOR UPDATE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\nCREATE POLICY \\"Users can delete workspace sales_order_items\\" ON sales_order_items FOR DELETE USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\n-- Indexes\nCREATE INDEX idx_suppliers_workspace_id ON suppliers(workspace_id);\nCREATE INDEX idx_customers_workspace_id ON customers(workspace_id);\nCREATE INDEX idx_purchase_orders_workspace_id ON purchase_orders(workspace_id);\nCREATE INDEX idx_purchase_orders_supplier_id ON purchase_orders(supplier_id);\nCREATE INDEX idx_sales_orders_workspace_id ON sales_orders(workspace_id);\nCREATE INDEX idx_sales_orders_customer_id ON sales_orders(customer_id);\n"}	orders_restructure_migration.sql	masteralan360@gmail.com	\N	\N
20260202221817	{"-- Fix missing columns for restructure tables\nALTER TABLE customers ADD COLUMN IF NOT EXISTS is_deleted BOOLEAN DEFAULT FALSE;\nALTER TABLE customers ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 1;\n\nALTER TABLE suppliers ADD COLUMN IF NOT EXISTS is_deleted BOOLEAN DEFAULT FALSE;\nALTER TABLE suppliers ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 1;\n\nALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS is_deleted BOOLEAN DEFAULT FALSE;\nALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 1;\n\nALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS is_deleted BOOLEAN DEFAULT FALSE;\nALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 1;\n"}	fix_missing_columns.sql	masteralan360@gmail.com	\N	\N
20260202222408	{"-- Migration Phase 5: Multi-Currency Support\n\n-- Add currency to customers (Preferred/Balance Currency)\nALTER TABLE customers ADD COLUMN IF NOT EXISTS currency TEXT DEFAULT 'usd';\n\n-- Add currency to suppliers (Preferred/Balance Currency)\nALTER TABLE suppliers ADD COLUMN IF NOT EXISTS currency TEXT DEFAULT 'usd';\n\n-- Add currency and rate to purchase_orders\nALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS currency TEXT DEFAULT 'usd';\nALTER TABLE purchase_orders ADD COLUMN IF NOT EXISTS exchange_rate DECIMAL(12, 6) DEFAULT 1.0;\n\n-- Add currency and rate to sales_orders\nALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS currency TEXT DEFAULT 'usd';\nALTER TABLE sales_orders ADD COLUMN IF NOT EXISTS exchange_rate DECIMAL(12, 6) DEFAULT 1.0;\n"}	multi_currency_orders_restructure.sql	masteralan360@gmail.com	\N	\N
20260202233024	{"-- 1. Correct Suppliers table naming\nALTER TABLE public.suppliers RENAME COLUMN currency TO default_currency;\n\n-- 2. Standardize 'created_by' across tables\n-- Products: Rename user_id to created_by\nALTER TABLE public.products RENAME COLUMN user_id TO created_by;\n\n-- Customers: We saw both user_id and created_by. Let's ensure created_by is the primary.\n-- If user_id exists and has data, we might want to migrate it, but for now let's just ensure renaming if only user_id exists.\n-- Actually, the audit showed both. I'll leave customers for now or just ensure created_by is used.\n\n-- 3. Ensure workspace_id and created_by are present and correctly typed (UUID)\n-- Most are already there based on audit.\n\n-- 4. Add missing columns to sales_orders if any\n-- Audit showed sales_orders has currency and exchange_rate.\n\n-- 5. Categories\n-- Ensure categories has created_by (it was missing in some previous checks, let me verify audit)\n-- Audit didn't show columns for categories specifically in the second query, but first list_tables did.\n-- Wait, let me check list_tables for categories. It wasn't in the list_tables output (truncated).\n-- I'll check categories columns quickly.\n"}	align_schemas_and_naming	masteralan360@gmail.com	\N	\N
