20260202233410	{"-- Align customers table\nDO $$ \nBEGIN \n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='customers' AND column_name='default_currency') THEN\n        ALTER TABLE customers ADD COLUMN default_currency text;\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='customers' AND column_name='workspace_id') THEN\n        ALTER TABLE customers ADD COLUMN workspace_id uuid REFERENCES workspaces(id);\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='customers' AND column_name='created_by') THEN\n        ALTER TABLE customers ADD COLUMN created_by uuid REFERENCES auth.users(id);\n    END IF;\nEND $$;\n\n-- Align suppliers table\nDO $$ \nBEGIN \n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='suppliers' AND column_name='default_currency') THEN\n        ALTER TABLE suppliers ADD COLUMN default_currency text;\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='suppliers' AND column_name='workspace_id') THEN\n        ALTER TABLE suppliers ADD COLUMN workspace_id uuid REFERENCES workspaces(id);\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='suppliers' AND column_name='created_by') THEN\n        ALTER TABLE suppliers ADD COLUMN created_by uuid REFERENCES auth.users(id);\n    END IF;\nEND $$;\n\n-- Align sales_orders table\nDO $$ \nBEGIN \n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='sales_orders' AND column_name='created_by') THEN\n        ALTER TABLE sales_orders ADD COLUMN created_by uuid REFERENCES auth.users(id);\n    END IF;\nEND $$;\n"}	fix_sync_schema_mismatch	masteralan360@gmail.com	\N	\N
20260203002623	{"-- Migration for Suppliers, Customers, and Orders\n-- Created: 2026-02-03\n\n-- 1. Suppliers Table\nCREATE TABLE IF NOT EXISTS public.suppliers (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id),\n    name TEXT NOT NULL,\n    contact_name TEXT,\n    email TEXT,\n    phone TEXT,\n    address TEXT,\n    city TEXT,\n    country TEXT,\n    default_currency TEXT NOT NULL DEFAULT 'usd' CHECK (default_currency IN ('usd', 'eur', 'iqd', 'try')),\n    notes TEXT,\n    total_purchases NUMERIC DEFAULT 0,\n    total_spent NUMERIC DEFAULT 0,\n    \n    -- Sync fields\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    sync_status TEXT DEFAULT 'synced',\n    version BIGINT DEFAULT 1,\n    is_deleted BOOLEAN DEFAULT FALSE\n);\n\n-- Enable RLS for Suppliers\nALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY;\n\n-- Policies (Drop first to avoid duplication errors if re-running without unique names? Or use DO block?)\n-- Simple names might collide if run twice. I'll use DO block for policies too.\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'suppliers' AND policyname = 'Users can view their workspace suppliers') THEN\n        CREATE POLICY \\"Users can view their workspace suppliers\\" ON public.suppliers FOR SELECT USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'suppliers' AND policyname = 'Users can insert their workspace suppliers') THEN\n        CREATE POLICY \\"Users can insert their workspace suppliers\\" ON public.suppliers FOR INSERT WITH CHECK (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'suppliers' AND policyname = 'Users can update their workspace suppliers') THEN\n        CREATE POLICY \\"Users can update their workspace suppliers\\" ON public.suppliers FOR UPDATE USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'suppliers' AND policyname = 'Users can delete their workspace suppliers') THEN\n        CREATE POLICY \\"Users can delete their workspace suppliers\\" ON public.suppliers FOR DELETE USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\nEND $$;\n\n\n-- 2. Customers Table (Enhancements)\nCREATE TABLE IF NOT EXISTS public.customers (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id),\n    name TEXT NOT NULL,\n    email TEXT,\n    phone TEXT,\n    address TEXT,\n    city TEXT,\n    country TEXT,\n    notes TEXT,\n    \n    -- New fields\n    default_currency TEXT NOT NULL DEFAULT 'usd' CHECK (default_currency IN ('usd', 'eur', 'iqd', 'try')),\n    total_orders NUMERIC DEFAULT 0,\n    total_spent NUMERIC DEFAULT 0,\n    outstanding_balance NUMERIC DEFAULT 0,\n\n    -- Sync fields\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    sync_status TEXT DEFAULT 'synced',\n    version BIGINT DEFAULT 1,\n    is_deleted BOOLEAN DEFAULT FALSE\n);\n\n-- Add columns if they don't exist\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'customers' AND column_name = 'default_currency') THEN\n        ALTER TABLE public.customers ADD COLUMN default_currency TEXT NOT NULL DEFAULT 'usd' CHECK (default_currency IN ('usd', 'eur', 'iqd', 'try'));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'customers' AND column_name = 'outstanding_balance') THEN\n        ALTER TABLE public.customers ADD COLUMN outstanding_balance NUMERIC DEFAULT 0;\n    END IF;\nEND $$;\n\nALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;\n\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'customers' AND policyname = 'Users can view their workspace customers') THEN\n        CREATE POLICY \\"Users can view their workspace customers\\" ON public.customers FOR SELECT USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'customers' AND policyname = 'Users can insert their workspace customers') THEN\n        CREATE POLICY \\"Users can insert their workspace customers\\" ON public.customers FOR INSERT WITH CHECK (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'customers' AND policyname = 'Users can update their workspace customers') THEN\n        CREATE POLICY \\"Users can update their workspace customers\\" ON public.customers FOR UPDATE USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'customers' AND policyname = 'Users can delete their workspace customers') THEN\n        CREATE POLICY \\"Users can delete their workspace customers\\" ON public.customers FOR DELETE USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\nEND $$;\n\n\n-- 3. Purchase Orders Table\nCREATE TABLE IF NOT EXISTS public.purchase_orders (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id),\n    order_number TEXT NOT NULL,\n    supplier_id UUID NOT NULL REFERENCES public.suppliers(id),\n    supplier_name TEXT,\n    subtotal NUMERIC DEFAULT 0,\n    discount NUMERIC DEFAULT 0,\n    total NUMERIC DEFAULT 0,\n    currency TEXT NOT NULL CHECK (currency IN ('usd', 'eur', 'iqd', 'try')),\n    \n    exchange_rate NUMERIC,\n    exchange_rate_source TEXT,\n    exchange_rate_timestamp TIMESTAMPTZ,\n    exchange_rates JSONB,\n    \n    status TEXT NOT NULL,\n    expected_delivery_date TIMESTAMPTZ,\n    actual_delivery_date TIMESTAMPTZ,\n    \n    is_paid BOOLEAN DEFAULT FALSE,\n    paid_at TIMESTAMPTZ,\n    payment_method TEXT,\n    notes TEXT,\n\n    items JSONB DEFAULT '[]'::jsonb, \n\n    -- Sync fields\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    sync_status TEXT DEFAULT 'synced',\n    version BIGINT DEFAULT 1,\n    is_deleted BOOLEAN DEFAULT FALSE\n);\n\nALTER TABLE public.purchase_orders ENABLE ROW LEVEL SECURITY;\n\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'purchase_orders' AND policyname = 'Users can view their workspace purchase_orders') THEN\n        CREATE POLICY \\"Users can view their workspace purchase_orders\\" ON public.purchase_orders FOR SELECT USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'purchase_orders' AND policyname = 'Users can insert their workspace purchase_orders') THEN\n        CREATE POLICY \\"Users can insert their workspace purchase_orders\\" ON public.purchase_orders FOR INSERT WITH CHECK (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'purchase_orders' AND policyname = 'Users can update their workspace purchase_orders') THEN\n        CREATE POLICY \\"Users can update their workspace purchase_orders\\" ON public.purchase_orders FOR UPDATE USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'purchase_orders' AND policyname = 'Users can delete their workspace purchase_orders') THEN\n        CREATE POLICY \\"Users can delete their workspace purchase_orders\\" ON public.purchase_orders FOR DELETE USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\nEND $$;\n\n\n-- 4. Sales Orders Table\nCREATE TABLE IF NOT EXISTS public.sales_orders (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id),\n    order_number TEXT NOT NULL,\n    customer_id UUID NOT NULL REFERENCES public.customers(id),\n    customer_name TEXT,\n    subtotal NUMERIC DEFAULT 0,\n    discount NUMERIC DEFAULT 0,\n    tax NUMERIC DEFAULT 0,\n    total NUMERIC DEFAULT 0,\n    currency TEXT NOT NULL CHECK (currency IN ('usd', 'eur', 'iqd', 'try')),\n    \n    exchange_rate NUMERIC,\n    exchange_rate_source TEXT,\n    exchange_rate_timestamp TIMESTAMPTZ,\n    exchange_rates JSONB,\n    \n    status TEXT NOT NULL,\n    expected_delivery_date TIMESTAMPTZ,\n    actual_delivery_date TIMESTAMPTZ,\n    \n    is_paid BOOLEAN DEFAULT FALSE,\n    paid_at TIMESTAMPTZ,\n    payment_method TEXT,\n    \n    reserved_at TIMESTAMPTZ,\n    shipping_address TEXT,\n    notes TEXT,\n\n    items JSONB DEFAULT '[]'::jsonb,\n\n    -- Sync fields\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    sync_status TEXT DEFAULT 'synced',\n    version BIGINT DEFAULT 1,\n    is_deleted BOOLEAN DEFAULT FALSE\n);\n\nALTER TABLE public.sales_orders ENABLE ROW LEVEL SECURITY;\n\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'sales_orders' AND policyname = 'Users can view their workspace sales_orders') THEN\n        CREATE POLICY \\"Users can view their workspace sales_orders\\" ON public.sales_orders FOR SELECT USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'sales_orders' AND policyname = 'Users can insert their workspace sales_orders') THEN\n        CREATE POLICY \\"Users can insert their workspace sales_orders\\" ON public.sales_orders FOR INSERT WITH CHECK (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'sales_orders' AND policyname = 'Users can update their workspace sales_orders') THEN\n        CREATE POLICY \\"Users can update their workspace sales_orders\\" ON public.sales_orders FOR UPDATE USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'sales_orders' AND policyname = 'Users can delete their workspace sales_orders') THEN\n        CREATE POLICY \\"Users can delete their workspace sales_orders\\" ON public.sales_orders FOR DELETE USING (workspace_id = (SELECT workspace_id FROM profiles WHERE id = auth.uid()));\n    END IF;\nEND $$;\n\n\n-- 5. Workspace Features Update (Suppliers & others)\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS allow_suppliers BOOLEAN NOT NULL DEFAULT true;\n\n-- Update configure_workspace\nCREATE OR REPLACE FUNCTION public.configure_workspace(\n    p_allow_pos BOOLEAN DEFAULT false,\n    p_allow_customers BOOLEAN DEFAULT false,\n    p_allow_suppliers BOOLEAN DEFAULT false, -- New\n    p_allow_orders BOOLEAN DEFAULT false,\n    p_allow_invoices BOOLEAN DEFAULT false\n)\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_workspace_id UUID;\n    v_user_role TEXT;\nBEGIN\n    SELECT workspace_id, role INTO v_workspace_id, v_user_role\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'User does not belong to a workspace';\n    END IF;\n\n    IF v_user_role != 'admin' THEN\n        RAISE EXCEPTION 'Unauthorized: Only admins can configure workspace features';\n    END IF;\n\n    UPDATE public.workspaces\n    SET \n        allow_pos = p_allow_pos,\n        allow_customers = p_allow_customers,\n        allow_suppliers = p_allow_suppliers,\n        allow_orders = p_allow_orders,\n        allow_invoices = p_allow_invoices,\n        is_configured = true\n    WHERE id = v_workspace_id;\n\n    RETURN jsonb_build_object(\n        'success', true,\n        'allow_pos', p_allow_pos,\n        'allow_customers', p_allow_customers,\n        'allow_suppliers', p_allow_suppliers,\n        'allow_orders', p_allow_orders,\n        'allow_invoices', p_allow_invoices\n    );\nEND;\n$$;\n\n-- Update get_workspace_features (COMPREHENSIVE)\nCREATE OR REPLACE FUNCTION public.get_workspace_features()\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_customers', false,\n            'allow_suppliers', false,\n            'allow_orders', false,\n            'allow_invoices', false,\n            'is_configured', false\n        );\n    END IF;\n\n    -- Return ALL settings fields used by frontend\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'allow_pos', allow_pos,\n        'allow_customers', allow_customers,\n        'allow_suppliers', allow_suppliers,\n        'allow_orders', allow_orders,\n        'allow_invoices', allow_invoices,\n        'is_configured', is_configured,\n        'default_currency', default_currency,\n        'iqd_display_preference', iqd_display_preference,\n        'eur_conversion_enabled', eur_conversion_enabled,\n        'try_conversion_enabled', try_conversion_enabled,\n        'locked_workspace', locked_workspace,\n        'max_discount_percent', max_discount_percent,\n        'allow_whatsapp', allow_whatsapp,\n        'logo_url', logo_url\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN COALESCE(v_result, jsonb_build_object(\n        'allow_pos', false,\n        'allow_customers', false,\n        'allow_suppliers', false,\n        'allow_orders', false,\n        'allow_invoices', false,\n        'is_configured', false\n    ));\nEND;\n$$;\n"}	suppliers_orders_migration	masteralan360@gmail.com	\N	\N
20260203003622	{"ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS credit_limit NUMERIC DEFAULT 0;\nALTER TABLE public.customers ADD COLUMN IF NOT EXISTS credit_limit NUMERIC DEFAULT 0;"}	add_credit_limit	masteralan360@gmail.com	\N	\N
20260204210801	{"-- Create Storages Table\ncreate table if not exists public.storages (\n    id uuid not null default gen_random_uuid(),\n    workspace_id uuid not null references public.workspaces(id),\n    name text not null,\n    is_system boolean not null default false,      -- For \\"Main\\" and \\"Reserve\\"\n    is_protected boolean not null default false,   -- Cannot be deleted\n    created_at timestamptz not null default now(),\n    updated_at timestamptz not null default now(),\n    is_deleted boolean not null default false,\n    \n    primary key (id),\n    constraint unique_storage_name_per_workspace unique (workspace_id, name)\n);\n\n-- Separate Stocks Table (Normalized)\ncreate table if not exists public.stocks (\n    id uuid not null default gen_random_uuid(),\n    workspace_id uuid not null references public.workspaces(id),\n    product_id uuid not null references public.products(id),\n    storage_id uuid not null references public.storages(id),\n    quantity numeric not null default 0,\n    created_at timestamptz not null default now(),\n    updated_at timestamptz not null default now(),\n    \n    primary key (id),\n    constraint unique_product_per_storage unique (product_id, storage_id)\n);\n\n-- RLS Policies\nalter table public.storages enable row level security;\nalter table public.stocks enable row level security;\n\n-- Drop existing policies if they exist (to be safe for re-runs)\ndrop policy if exists \\"Users can view storages in their workspace\\" on public.storages;\ndrop policy if exists \\"Users can insert storages in their workspace\\" on public.storages;\ndrop policy if exists \\"Users can update storages in their workspace\\" on public.storages;\ndrop policy if exists \\"Users can view stocks in their workspace\\" on public.stocks;\ndrop policy if exists \\"Users can insert stocks in their workspace\\" on public.stocks;\ndrop policy if exists \\"Users can update stocks in their workspace\\" on public.stocks;\n\ncreate policy \\"Users can view storages in their workspace\\"\n    on public.storages for select\n    using (workspace_id = ((auth.jwt() -> 'user_metadata') ->> 'workspace_id')::uuid);\n\ncreate policy \\"Users can insert storages in their workspace\\"\n    on public.storages for insert\n    with check (workspace_id = ((auth.jwt() -> 'user_metadata') ->> 'workspace_id')::uuid);\n\ncreate policy \\"Users can update storages in their workspace\\"\n    on public.storages for update\n    using (workspace_id = ((auth.jwt() -> 'user_metadata') ->> 'workspace_id')::uuid);\n\ncreate policy \\"Users can view stocks in their workspace\\"\n    on public.stocks for select\n    using (workspace_id = ((auth.jwt() -> 'user_metadata') ->> 'workspace_id')::uuid);\n\ncreate policy \\"Users can insert stocks in their workspace\\"\n    on public.stocks for insert\n    with check (workspace_id = ((auth.jwt() -> 'user_metadata') ->> 'workspace_id')::uuid);\n\ncreate policy \\"Users can update stocks in their workspace\\"\n    on public.stocks for update\n    using (workspace_id = ((auth.jwt() -> 'user_metadata') ->> 'workspace_id')::uuid);\n\n-- Grant access\ngrant all on public.storages to authenticated;\ngrant all on public.stocks to authenticated;\ngrant all on public.storages to service_role;\ngrant all on public.stocks to service_role;\n\n-- Realtime: Check if already added? \n-- 'alter publication ... add table' throws error if table already exists.\n-- Supabase doesn't have 'add table if not exists'. \n-- We can ignore error or use DO block.\ndo $$\nbegin\n  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'storages') then\n    alter publication supabase_realtime add table public.storages;\n  end if;\n  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'stocks') then\n    alter publication supabase_realtime add table public.stocks;\n  end if;\nend $$;\n\n-- RPC to migrate existing products to 'Main' storage\ncreate or replace function migrate_products_to_main_storage(p_workspace_id uuid)\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n    v_main_storage_id uuid;\nbegin\n    -- 1. Ensure 'Main' storage exists\n    insert into public.storages (workspace_id, name, is_system, is_protected)\n    values (p_workspace_id, 'Main', true, true)\n    on conflict (workspace_id, name) do update set is_system = true\n    returning id into v_main_storage_id;\n\n    -- 2. Ensure 'Reserve' storage exists (optional)\n    insert into public.storages (workspace_id, name, is_system, is_protected)\n    values (p_workspace_id, 'Reserve', true, true)\n    on conflict do nothing;\n\n    -- 3. Move quantity from products to stocks (MAIN)\n    insert into public.stocks (workspace_id, product_id, storage_id, quantity)\n    select \n        p.workspace_id,\n        p.id,\n        v_main_storage_id,\n        coalesce(p.quantity, 0)\n    from public.products p\n    where p.workspace_id = p_workspace_id\n    on conflict (product_id, storage_id) do update \n    set quantity = EXCLUDED.quantity;\nend;\n$$;\n"}	20260205_create_storage	masteralan360@gmail.com	\N	\N
20260205134107	{"-- Add storage_id to products\nALTER TABLE public.products \nADD COLUMN IF NOT EXISTS storage_id UUID REFERENCES public.storages(id);\n\n-- Create index for faster lookups\nCREATE INDEX IF NOT EXISTS idx_products_storage_id ON public.products(storage_id);"}	add_storage_id_to_products	masteralan360@gmail.com	\N	\N
20260205235639	{"-- HR & Budget Tables Migration\n-- Run this to enable backend synchronization for Asaas ERP\n\n-- 1. Employees table\nCREATE TABLE IF NOT EXISTS public.employees (\n    id UUID PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,\n    name TEXT NOT NULL,\n    email TEXT,\n    phone TEXT,\n    gender TEXT CHECK (gender IN ('male', 'female', 'other')),\n    role TEXT NOT NULL, -- Internal labeling roles\n    location TEXT,\n    joining_date DATE NOT NULL DEFAULT CURRENT_DATE,\n    salary NUMERIC(15, 2) NOT NULL DEFAULT 0,\n    salary_currency TEXT NOT NULL DEFAULT 'usd',\n    \n    -- Sync Metadata\n    version INTEGER NOT NULL DEFAULT 1,\n    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- 2. Expenses table\nCREATE TABLE IF NOT EXISTS public.expenses (\n    id UUID PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,\n    description TEXT,\n    type TEXT CHECK (type IN ('recurring', 'one-time')),\n    category TEXT CHECK (category IN ('rent', 'electricity', 'payroll', 'utility', 'marketing', 'general', 'other')),\n    amount NUMERIC(15, 2) NOT NULL DEFAULT 0,\n    currency TEXT NOT NULL DEFAULT 'usd',\n    status TEXT CHECK (status IN ('pending', 'paid', 'snoozed')),\n    due_date TIMESTAMPTZ NOT NULL,\n    paid_at TIMESTAMPTZ,\n    snooze_until TIMESTAMPTZ,\n    snooze_count INTEGER NOT NULL DEFAULT 0,\n    employee_id UUID REFERENCES public.employees(id) ON DELETE SET NULL,\n    \n    -- Sync Metadata\n    version INTEGER NOT NULL DEFAULT 1,\n    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- 3. Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_employees_workspace_id ON public.employees(workspace_id);\nCREATE INDEX IF NOT EXISTS idx_expenses_workspace_id ON public.expenses(workspace_id);\nCREATE INDEX IF NOT EXISTS idx_expenses_due_date ON public.expenses(due_date);\n\n-- 4. Enable Row Level Security (RLS)\nALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY;\n\n-- 5. Policies (Workspace isolation)\nDO $$ \nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'employees' AND policyname = 'Workspaces members can view employees') THEN\n        CREATE POLICY \\"Workspaces members can view employees\\" ON public.employees\n            FOR ALL USING (\n                workspace_id IN (\n                    SELECT workspace_id FROM public.profiles WHERE id = auth.uid()\n                )\n            );\n    END IF;\n\n    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'expenses' AND policyname = 'Workspaces members can view expenses') THEN\n        CREATE POLICY \\"Workspaces members can view expenses\\" ON public.expenses\n            FOR ALL USING (\n                workspace_id IN (\n                    SELECT workspace_id FROM public.profiles WHERE id = auth.uid()\n                )\n            );\n    END IF;\nEND $$;\n\n-- 6. Trigger for updated_at\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'update_employees_updated_at') THEN\n        CREATE TRIGGER update_employees_updated_at BEFORE UPDATE ON public.employees\n            FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n    END IF;\n\n    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'update_expenses_updated_at') THEN\n        CREATE TRIGGER update_expenses_updated_at BEFORE UPDATE ON public.expenses\n            FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n    END IF;\nEND $$;"}	hr_budget_migration	masteralan360@gmail.com	\N	\N
20260206001213	{"\n-- Budget Allocations Table\nCREATE TABLE IF NOT EXISTS public.budget_allocations (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,\n    month TEXT NOT NULL, -- Format: YYYY-MM\n    type TEXT NOT NULL CHECK (type IN ('fixed', 'percentage')),\n    amount NUMERIC NOT NULL DEFAULT 0,\n    currency TEXT NOT NULL DEFAULT 'usd',\n    version INTEGER NOT NULL DEFAULT 1,\n    is_deleted BOOLEAN NOT NULL DEFAULT false,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    UNIQUE(workspace_id, month)\n);\n\n-- RLS Policies\nALTER TABLE public.budget_allocations ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"Allow workspace members to read budget allocations\\" ON public.budget_allocations\n    FOR SELECT USING (\n        workspace_id IN (\n            SELECT workspace_id FROM public.profiles WHERE id = auth.uid()\n        )\n    );\n\nCREATE POLICY \\"Allow workspace members to insert budget allocations\\" ON public.budget_allocations\n    FOR INSERT WITH CHECK (\n        workspace_id IN (\n            SELECT workspace_id FROM public.profiles WHERE id = auth.uid()\n        )\n    );\n\nCREATE POLICY \\"Allow workspace members to update budget allocations\\" ON public.budget_allocations\n    FOR UPDATE USING (\n        workspace_id IN (\n            SELECT workspace_id FROM public.profiles WHERE id = auth.uid()\n        )\n    );\n\n-- Trigger for updated_at\nCREATE TRIGGER update_budget_allocations_updated_at BEFORE UPDATE ON public.budget_allocations\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n"}	budget_allocation_v3_migration	masteralan360@gmail.com	\N	\N
