20260211212144	{"CREATE OR REPLACE FUNCTION public.get_workspace_features()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_customers', false,\n            'allow_suppliers', false,\n            'allow_orders', false,\n            'allow_invoices', false,\n            'is_configured', false\n        );\n    END IF;\n\n    -- Return ALL settings fields used by frontend\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'allow_pos', allow_pos,\n        'allow_customers', allow_customers,\n        'allow_suppliers', allow_suppliers,\n        'allow_orders', allow_orders,\n        'allow_invoices', allow_invoices,\n        'is_configured', is_configured,\n        'default_currency', default_currency,\n        'iqd_display_preference', iqd_display_preference,\n        'eur_conversion_enabled', eur_conversion_enabled,\n        'try_conversion_enabled', try_conversion_enabled,\n        'locked_workspace', locked_workspace,\n        'max_discount_percent', max_discount_percent,\n        'allow_whatsapp', allow_whatsapp,\n        'logo_url', logo_url,\n        'print_lang', print_lang\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN COALESCE(v_result, jsonb_build_object(\n        'allow_pos', false,\n        'allow_customers', false,\n        'allow_suppliers', false,\n        'allow_orders', false,\n        'allow_invoices', false,\n        'is_configured', false\n    ));\nEND;\n$function$;\n"}	update_get_workspace_features_rpc	masteralan360@gmail.com	\N	\N
