20260222123855	{"-- Install moddatetime extension\nCREATE EXTENSION IF NOT EXISTS moddatetime SCHEMA extensions;\n\n-- Create workspace_phones table\nCREATE TABLE IF NOT EXISTS public.workspace_phones (\n    id UUID PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,\n    phone TEXT NOT NULL,\n    label TEXT,\n    is_primary BOOLEAN DEFAULT false,\n    created_at TIMESTAMPTZ DEFAULT now(),\n    updated_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.workspace_phones ENABLE ROW LEVEL SECURITY;\n\n-- Add RLS Policies\n-- Using a subquery on profiles to ensure the user belongs to the workspace\nCREATE POLICY \\"Users can view phones of their own workspace\\"\n    ON public.workspace_phones FOR SELECT\n    USING (\n        workspace_id IN (\n            SELECT workspace_id FROM public.profiles WHERE id = auth.uid()\n        )\n    );\n\nCREATE POLICY \\"Admins can manage phones of their own workspace\\"\n    ON public.workspace_phones FOR ALL\n    USING (\n        workspace_id IN (\n            SELECT workspace_id FROM public.profiles WHERE id = auth.uid() AND role = 'admin'\n        )\n    );\n\n-- Add updated_at trigger\n-- Use the installed moddatetime function\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'update_workspace_phones_updated_at') THEN\n        CREATE TRIGGER update_workspace_phones_updated_at\n            BEFORE UPDATE ON public.workspace_phones\n            FOR EACH ROW EXECUTE FUNCTION extensions.moddatetime (updated_at);\n    END IF;\nEND $$;\n"}	setup_moddatetime_and_workspace_phones	masteralan360@gmail.com	\N	\N
20260311205522	{"-- Add sync_status and last_synced_at to budget_settings\nALTER TABLE budget.budget_settings \nADD COLUMN IF NOT EXISTS sync_status text DEFAULT 'synced',\nADD COLUMN IF NOT EXISTS last_synced_at timestamp with time zone;\n\n-- Add sync_status and last_synced_at to budget_allocations\nALTER TABLE budget.budget_allocations \nADD COLUMN IF NOT EXISTS sync_status text DEFAULT 'synced',\nADD COLUMN IF NOT EXISTS last_synced_at timestamp with time zone;\n\n-- Add sync_status and last_synced_at to expense_series\nALTER TABLE budget.expense_series \nADD COLUMN IF NOT EXISTS sync_status text DEFAULT 'synced',\nADD COLUMN IF NOT EXISTS last_synced_at timestamp with time zone;\n\n-- Add sync_status and last_synced_at to expense_items\nALTER TABLE budget.expense_items \nADD COLUMN IF NOT EXISTS sync_status text DEFAULT 'synced',\nADD COLUMN IF NOT EXISTS last_synced_at timestamp with time zone;\n\n-- Add sync_status and last_synced_at to payroll_statuses\nALTER TABLE budget.payroll_statuses \nADD COLUMN IF NOT EXISTS sync_status text DEFAULT 'synced',\nADD COLUMN IF NOT EXISTS last_synced_at timestamp with time zone;\n\n-- Add sync_status and last_synced_at to dividend_statuses\nALTER TABLE budget.dividend_statuses \nADD COLUMN IF NOT EXISTS sync_status text DEFAULT 'synced',\nADD COLUMN IF NOT EXISTS last_synced_at timestamp with time zone;"}	add_sync_metadata_to_budget_schema	masteralan360@gmail.com	\N	\N
20260222172839	{"-- Drop the old table if it exists\nDROP TABLE IF EXISTS public.workspace_phones;\nDROP TABLE IF EXISTS public.workspace_contacts;\n\n-- Create the new table\nCREATE TABLE public.workspace_contacts (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    workspace_id UUID NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,\n    type TEXT NOT NULL CHECK (type IN ('phone', 'email', 'address')),\n    value TEXT NOT NULL,\n    label TEXT,\n    is_primary BOOLEAN DEFAULT false,\n    sync_status TEXT DEFAULT 'synced',\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,\n    is_deleted BOOLEAN DEFAULT false\n);\n\n-- RLS Policies\nALTER TABLE public.workspace_contacts ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"Users can view workspace contacts\\"\n    ON public.workspace_contacts FOR SELECT\n    USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\nCREATE POLICY \\"Users can insert workspace contacts\\"\n    ON public.workspace_contacts FOR INSERT\n    WITH CHECK ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\nCREATE POLICY \\"Users can update workspace contacts\\"\n    ON public.workspace_contacts FOR UPDATE\n    USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id)\n    WITH CHECK ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);\n\nCREATE POLICY \\"Users can delete workspace contacts\\"\n    ON public.workspace_contacts FOR DELETE\n    USING ((auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid = workspace_id);"}	create_workspace_contacts_table	masteralan360@gmail.com	\N	\N
