20260223143805	{"CREATE OR REPLACE FUNCTION public.get_workspace_features()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    -- Get user's workspace\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_customers', false,\n            'allow_suppliers', false,\n            'allow_orders', false,\n            'allow_invoices', false,\n            'is_configured', false\n        );\n    END IF;\n\n    -- Get ALL workspace features and settings\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'allow_pos', COALESCE(allow_pos, false),\n        'allow_customers', COALESCE(allow_customers, false),\n        'allow_suppliers', COALESCE(allow_suppliers, false),\n        'allow_orders', COALESCE(allow_orders, false),\n        'allow_invoices', COALESCE(allow_invoices, false),\n        'is_configured', COALESCE(is_configured, false),\n        'default_currency', COALESCE(default_currency, 'usd'),\n        'iqd_display_preference', COALESCE(iqd_display_preference, 'IQD'),\n        'eur_conversion_enabled', COALESCE(eur_conversion_enabled, false),\n        'try_conversion_enabled', COALESCE(try_conversion_enabled, false),\n        'locked_workspace', COALESCE(locked_workspace, false),\n        'logo_url', logo_url,\n        'max_discount_percent', COALESCE(max_discount_percent, 100),\n        'allow_whatsapp', COALESCE(allow_whatsapp, false),\n        'print_lang', COALESCE(print_lang, 'auto'),\n        'print_qr', COALESCE(print_qr, false),\n        'receipt_template', COALESCE(receipt_template, 'primary'),\n        'a4_template: ', COALESCE(a4_template, 'primary'),\n        'print_quality', COALESCE(print_quality, 'low'),\n        'subscription_expires_at', subscription_expires_at\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN v_result;\nEND;\n$function$;"}	update_get_workspace_features_rpc_v2	masteralan360@gmail.com	\N	\N
20260223143825	{"CREATE OR REPLACE FUNCTION public.get_workspace_features()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    -- Get user's workspace\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_customers', false,\n            'allow_suppliers', false,\n            'allow_orders', false,\n            'allow_invoices', false,\n            'is_configured', false\n        );\n    END IF;\n\n    -- Get ALL workspace features and settings\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'allow_pos', COALESCE(allow_pos, false),\n        'allow_customers', COALESCE(allow_customers, false),\n        'allow_suppliers', COALESCE(allow_suppliers, false),\n        'allow_orders', COALESCE(allow_orders, false),\n        'allow_invoices', COALESCE(allow_invoices, false),\n        'is_configured', COALESCE(is_configured, false),\n        'default_currency', COALESCE(default_currency, 'usd'),\n        'iqd_display_preference', COALESCE(iqd_display_preference, 'IQD'),\n        'eur_conversion_enabled', COALESCE(eur_conversion_enabled, false),\n        'try_conversion_enabled', COALESCE(try_conversion_enabled, false),\n        'locked_workspace', COALESCE(locked_workspace, false),\n        'logo_url', logo_url,\n        'max_discount_percent', COALESCE(max_discount_percent, 100),\n        'allow_whatsapp', COALESCE(allow_whatsapp, false),\n        'print_lang', COALESCE(print_lang, 'auto'),\n        'print_qr', COALESCE(print_qr, false),\n        'receipt_template', COALESCE(receipt_template, 'primary'),\n        'a4_template', COALESCE(a4_template, 'primary'),\n        'print_quality', COALESCE(print_quality, 'low'),\n        'subscription_expires_at', subscription_expires_at\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN v_result;\nEND;\n$function$;"}	fix_get_workspace_features_rpc_typo	masteralan360@gmail.com	\N	\N
20260310214725	{"-- Admin Workspace Functions\n-- Functions for Super Admins to manage workspaces and their feature flags\n\n-- 1. Get All Workspaces (Admin Only)\n-- Drops the function first to allow return type changes\nDROP FUNCTION IF EXISTS public.get_all_workspaces(text);\n\nCREATE OR REPLACE FUNCTION public.get_all_workspaces(provided_key TEXT)\nRETURNS TABLE (\n    id UUID,\n    name TEXT,\n    code TEXT,\n    created_at TIMESTAMPTZ,\n    allow_pos BOOLEAN,\n    allow_customers BOOLEAN,\n    allow_orders BOOLEAN,\n    allow_invoices BOOLEAN,\n    is_configured BOOLEAN,\n    deleted_at TIMESTAMPTZ,\n    coordination TEXT,\n    logo_url TEXT\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    IF NOT public.verify_admin_passkey(provided_key) THEN\n        RAISE EXCEPTION 'Unauthorized: Invalid admin passkey';\n    END IF;\n\n    RETURN QUERY\n    SELECT \n        w.id,\n        w.name,\n        w.code,\n        w.created_at,\n        COALESCE(w.allow_pos, false),\n        COALESCE(w.allow_customers, false),\n        COALESCE(w.allow_orders, false),\n        COALESCE(w.allow_invoices, false),\n        COALESCE(w.is_configured, false),\n        w.deleted_at,\n        w.coordination,\n        w.logo_url\n    FROM public.workspaces w\n    ORDER BY w.created_at DESC;\nEND;\n$$;\n\n\n-- 2. Update Workspace Features (Admin Only)\nCREATE OR REPLACE FUNCTION public.admin_update_workspace_features(\n    provided_key TEXT,\n    target_workspace_id UUID,\n    new_allow_pos BOOLEAN,\n    new_allow_customers BOOLEAN,\n    new_allow_orders BOOLEAN,\n    new_allow_invoices BOOLEAN\n)\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    IF NOT public.verify_admin_passkey(provided_key) THEN\n        RAISE EXCEPTION 'Unauthorized: Invalid admin passkey';\n    END IF;\n\n    UPDATE public.workspaces\n    SET \n        allow_pos = new_allow_pos,\n        allow_customers = new_allow_customers,\n        allow_orders = new_allow_orders,\n        allow_invoices = new_allow_invoices,\n        is_configured = true -- Ensure it's marked configured if admin touches it\n    WHERE id = target_workspace_id;\nEND;\n$$;"}	admin_workspace_functions	masteralan360@gmail.com	\N	\N
20260310220735	{"-- Admin Workspace Functions (v2)\n-- Functions for Super Admins to manage workspaces and their feature flags\n\n-- 1. Get All Workspaces (Admin Only)\n-- Drops the function first to allow return type changes\nDROP FUNCTION IF EXISTS public.get_all_workspaces(text);\n\nCREATE OR REPLACE FUNCTION public.get_all_workspaces(provided_key TEXT)\nRETURNS TABLE (\n    id UUID,\n    name TEXT,\n    code TEXT,\n    created_at TIMESTAMPTZ,\n    allow_pos BOOLEAN,\n    allow_customers BOOLEAN,\n    allow_orders BOOLEAN,\n    allow_invoices BOOLEAN,\n    is_configured BOOLEAN,\n    deleted_at TIMESTAMPTZ,\n    coordination TEXT,\n    logo_url TEXT,\n    subscription_expires_at TIMESTAMPTZ\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nBEGIN\n    IF NOT public.verify_admin_passkey(provided_key) THEN\n        RAISE EXCEPTION 'Unauthorized: Invalid admin passkey';\n    END IF;\n\n    RETURN QUERY\n    SELECT \n        w.id,\n        w.name,\n        w.code,\n        w.created_at,\n        COALESCE(w.allow_pos, false),\n        COALESCE(w.allow_customers, false),\n        COALESCE(w.allow_orders, false),\n        COALESCE(w.allow_invoices, false),\n        COALESCE(w.is_configured, false),\n        w.deleted_at,\n        w.coordination,\n        w.logo_url,\n        w.subscription_expires_at\n    FROM public.workspaces w\n    ORDER BY w.created_at DESC;\nEND;\n$$;"}	fix_admin_workspace_subscriptions_v2	masteralan360@gmail.com	\N	\N
