20260312183917	{"-- Update the detection function to group dividends\nCREATE OR REPLACE FUNCTION notifications.detect_overdue_events()\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = notifications, public, budget, auth, extensions\nAS $$\nBEGIN\n    -- 1. Budget: expense items (Individual as before)\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        e.workspace_id,\n        p.id AS user_id,\n        'budget_expense' AS entity_type,\n        e.id::TEXT AS entity_id,\n        e.due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_expense',\n            'title', COALESCE(s.name, 'Expense'),\n            'amount', e.amount,\n            'currency', e.currency,\n            'due_date', e.due_date,\n            'expense_id', e.id,\n            'series_id', e.series_id,\n            'month', e.month\n        )\n    FROM budget.expense_items e\n    LEFT JOIN budget.expense_series s ON s.id = e.series_id\n    INNER JOIN public.profiles p ON p.workspace_id = e.workspace_id AND p.role = 'admin'\n    WHERE e.is_deleted = FALSE\n      AND e.due_date < CURRENT_DATE\n      AND e.status <> 'paid'\n      AND (\n        e.status <> 'snoozed'\n        OR (e.snoozed_indefinite = FALSE AND e.snoozed_until IS NOT NULL AND e.snoozed_until <= NOW())\n      )\n    ON CONFLICT DO NOTHING;\n\n    -- 2. Budget: payroll statuses (Individual as before)\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        ps.workspace_id,\n        p.id AS user_id,\n        'budget_payroll' AS entity_type,\n        ps.id::TEXT AS entity_id,\n        due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_payroll',\n            'title', COALESCE(emp.name, 'Payroll'),\n            'amount', emp.salary,\n            'currency', emp.salary_currency,\n            'due_date', due_date,\n            'month', ps.month,\n            'employee_id', emp.id,\n            'status_id', ps.id\n        )\n    FROM budget.payroll_statuses ps\n    INNER JOIN public.employees emp ON emp.id = ps.employee_id\n    INNER JOIN public.profiles p ON p.workspace_id = ps.workspace_id AND p.role = 'admin'\n    CROSS JOIN LATERAL notifications.compute_due_date(ps.month, emp.salary_payday) AS due_date\n    WHERE ps.is_deleted = FALSE\n      AND due_date IS NOT NULL\n      AND due_date < CURRENT_DATE\n      AND ps.status <> 'paid'\n      AND (\n        ps.status <> 'snoozed'\n        OR (ps.snoozed_indefinite = FALSE AND ps.snoozed_until IS NOT NULL AND ps.snoozed_until <= NOW())\n      )\n    ON CONFLICT DO NOTHING;\n\n    -- 3. Budget: dividend statuses (GROUPED per month/workspace)\n    WITH overdue_divs AS (\n        SELECT\n            ds.workspace_id,\n            ds.month,\n            MIN(due_date) as oldest_due_date,\n            COUNT(*) as holder_count\n        FROM budget.dividend_statuses ds\n        INNER JOIN public.employees emp ON emp.id = ds.employee_id\n        CROSS JOIN LATERAL notifications.compute_due_date(ds.month, emp.dividend_payday) AS due_date\n        WHERE ds.is_deleted = FALSE\n          AND emp.has_dividends = TRUE\n          AND due_date IS NOT NULL\n          AND due_date < CURRENT_DATE\n          AND ds.status <> 'paid'\n          AND (\n            ds.status <> 'snoozed'\n            OR (ds.snoozed_indefinite = FALSE AND ds.snoozed_until IS NOT NULL AND ds.snoozed_until <= NOW())\n          )\n        GROUP BY ds.workspace_id, ds.month\n    )\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        o.workspace_id,\n        p.id AS user_id,\n        'budget_dividend' AS entity_type,\n        o.month AS entity_id, -- Unique per month/workspace\n        o.oldest_due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_dividend',\n            'title', 'Outstanding Dividends',\n            'content', 'Some shareholders have not yet withdrawn their dividends for the month of ' || o.month || '.',\n            'holder_count', o.holder_count,\n            'month', o.month,\n            'due_date', o.oldest_due_date\n        )\n    FROM overdue_divs o\n    INNER JOIN public.profiles p ON p.workspace_id = o.workspace_id AND p.role = 'admin'\n    ON CONFLICT DO NOTHING;\n\n    -- 4. Loans: aggregated overdue installments (Grouped as before)\n    WITH overdue_loans AS (\n        SELECT\n            li.loan_id,\n            l.workspace_id,\n            MIN(li.due_date) AS oldest_due_date,\n            SUM(li.balance_amount) AS overdue_amount,\n            COUNT(*) AS overdue_installment_count\n        FROM public.loan_installments li\n        INNER JOIN public.loans l ON l.id = li.loan_id\n        WHERE li.is_deleted = FALSE\n          AND l.is_deleted = FALSE\n          AND li.balance_amount > 0\n          AND li.due_date < CURRENT_DATE\n        GROUP BY li.loan_id, l.workspace_id\n    )\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        o.workspace_id,\n        p.id AS user_id,\n        'loan_overdue' AS entity_type,\n        l.id::TEXT AS entity_id,\n        o.oldest_due_date,\n        jsonb_build_object(\n            'entity_type', 'loan_overdue',\n            'title', l.loan_no,\n            'loan_id', l.id,\n            'loan_no', l.loan_no,\n            'borrower_name', l.borrower_name,\n            'due_date', o.oldest_due_date,\n            'overdue_amount', o.overdue_amount,\n            'overdue_installment_count', o.overdue_installment_count,\n            'balance_amount', l.balance_amount,\n            'currency', l.settlement_currency\n        )\n    FROM overdue_loans o\n    INNER JOIN public.loans l ON l.id = o.loan_id\n    INNER JOIN public.profiles p ON p.workspace_id = o.workspace_id AND p.role = 'admin'\n    WHERE l.is_deleted = FALSE\n      AND (l.overdue_reminder_snoozed_for_due_date IS NULL OR l.overdue_reminder_snoozed_for_due_date <> o.oldest_due_date)\n    ON CONFLICT DO NOTHING;\nEND;\n$$;\n"}	group_dividend_notifications	masteralan360@gmail.com	\N	\N
20260312184519	{"-- Fix the detection function to include 'amount' and 'balance_amount' explicitly in payload\nCREATE OR REPLACE FUNCTION notifications.detect_overdue_events()\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = notifications, public, budget, auth, extensions\nAS $$\nBEGIN\n    -- 1. Budget: expense items (Individual)\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        e.workspace_id,\n        p.id AS user_id,\n        'budget_expense' AS entity_type,\n        e.id::TEXT AS entity_id,\n        e.due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_expense',\n            'title', COALESCE(s.name, 'Expense'),\n            'amount', e.amount,\n            'currency', e.currency,\n            'due_date', e.due_date,\n            'expense_id', e.id,\n            'series_id', e.series_id,\n            'month', e.month\n        )\n    FROM budget.expense_items e\n    LEFT JOIN budget.expense_series s ON s.id = e.series_id\n    INNER JOIN public.profiles p ON p.workspace_id = e.workspace_id AND p.role = 'admin'\n    WHERE e.is_deleted = FALSE\n      AND e.due_date < CURRENT_DATE\n      AND e.status <> 'paid'\n      AND (\n        e.status <> 'snoozed'\n        OR (e.snoozed_indefinite = FALSE AND e.snoozed_until IS NOT NULL AND e.snoozed_until <= NOW())\n      )\n    ON CONFLICT DO NOTHING;\n\n    -- 2. Budget: payroll statuses (Individual)\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        ps.workspace_id,\n        p.id AS user_id,\n        'budget_payroll' AS entity_type,\n        ps.id::TEXT AS entity_id,\n        due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_payroll',\n            'title', COALESCE(emp.name, 'Payroll'),\n            'amount', emp.salary,\n            'currency', emp.salary_currency,\n            'due_date', due_date,\n            'month', ps.month,\n            'employee_id', emp.id,\n            'status_id', ps.id\n        )\n    FROM budget.payroll_statuses ps\n    INNER JOIN public.employees emp ON emp.id = ps.employee_id\n    INNER JOIN public.profiles p ON p.workspace_id = ps.workspace_id AND p.role = 'admin'\n    CROSS JOIN LATERAL notifications.compute_due_date(ps.month, emp.salary_payday) AS due_date\n    WHERE ps.is_deleted = FALSE\n      AND due_date IS NOT NULL\n      AND due_date < CURRENT_DATE\n      AND ps.status <> 'paid'\n      AND (\n        ps.status <> 'snoozed'\n        OR (ps.snoozed_indefinite = FALSE AND ps.snoozed_until IS NOT NULL AND ps.snoozed_until <= NOW())\n      )\n    ON CONFLICT DO NOTHING;\n\n    -- 3. Budget: dividend statuses (GROUPED per month/workspace)\n    WITH overdue_divs AS (\n        SELECT\n            ds.workspace_id,\n            ds.month,\n            MIN(due_date) as oldest_due_date,\n            COUNT(*) as holder_count\n        FROM budget.dividend_statuses ds\n        INNER JOIN public.employees emp ON emp.id = ds.employee_id\n        CROSS JOIN LATERAL notifications.compute_due_date(ds.month, emp.dividend_payday) AS due_date\n        WHERE ds.is_deleted = FALSE\n          AND emp.has_dividends = TRUE\n          AND due_date IS NOT NULL\n          AND due_date < CURRENT_DATE\n          AND ds.status <> 'paid'\n          AND (\n            ds.status <> 'snoozed'\n            OR (ds.snoozed_indefinite = FALSE AND ds.snoozed_until IS NOT NULL AND ds.snoozed_until <= NOW())\n          )\n        GROUP BY ds.workspace_id, ds.month\n    )\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        o.workspace_id,\n        p.id AS user_id,\n        'budget_dividend' AS entity_type,\n        o.month AS entity_id,\n        o.oldest_due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_dividend',\n            'title', 'Outstanding Dividends',\n            'content', 'Some shareholders have not yet withdrawn their dividends for the month of ' || o.month || '.',\n            'holder_count', o.holder_count,\n            'month', o.month,\n            'due_date', o.oldest_due_date\n        )\n    FROM overdue_divs o\n    INNER JOIN public.profiles p ON p.workspace_id = o.workspace_id AND p.role = 'admin'\n    ON CONFLICT DO NOTHING;\n\n    -- 4. Loans: aggregated overdue installments (Grouped)\n    WITH overdue_loans AS (\n        SELECT\n            li.loan_id,\n            l.workspace_id,\n            MIN(li.due_date) AS oldest_due_date,\n            SUM(li.balance_amount) AS overdue_amount,\n            COUNT(*) AS overdue_installment_count\n        FROM public.loan_installments li\n        INNER JOIN public.loans l ON l.id = li.loan_id\n        WHERE li.is_deleted = FALSE\n          AND l.is_deleted = FALSE\n          AND li.balance_amount > 0\n          AND li.due_date < CURRENT_DATE\n        GROUP BY li.loan_id, l.workspace_id\n    )\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        o.workspace_id,\n        p.id AS user_id,\n        'loan_overdue' AS entity_type,\n        l.id::TEXT AS entity_id,\n        o.oldest_due_date,\n        jsonb_build_object(\n            'entity_type', 'loan_overdue',\n            'title', l.loan_no,\n            'loan_id', l.id,\n            'loan_no', l.loan_no,\n            'borrower_name', l.borrower_name,\n            'due_date', o.oldest_due_date,\n            'amount', o.overdue_amount, -- Specifically used for 'Amount iqd' display in UI\n            'overdue_amount', o.overdue_amount,\n            'overdue_installment_count', o.overdue_installment_count,\n            'balance_amount', l.balance_amount, -- Remaining principal/total balance\n            'currency', l.settlement_currency\n        )\n    FROM overdue_loans o\n    INNER JOIN public.loans l ON l.id = o.loan_id\n    INNER JOIN public.profiles p ON p.workspace_id = o.workspace_id AND p.role = 'admin'\n    WHERE l.is_deleted = FALSE\n      AND (l.overdue_reminder_snoozed_for_due_date IS NULL OR l.overdue_reminder_snoozed_for_due_date <> o.oldest_due_date)\n    ON CONFLICT DO NOTHING;\nEND;\n$$;\n"}	fix_loan_notification_amounts	masteralan360@gmail.com	\N	\N
20260312184821	{"-- Update the detection function to use borrower_name as title for loans\nCREATE OR REPLACE FUNCTION notifications.detect_overdue_events()\nRETURNS VOID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = notifications, public, budget, auth, extensions\nAS $$\nBEGIN\n    -- 1. Budget: expense items (Individual)\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        e.workspace_id,\n        p.id AS user_id,\n        'budget_expense' AS entity_type,\n        e.id::TEXT AS entity_id,\n        e.due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_expense',\n            'title', COALESCE(s.name, 'Expense'),\n            'amount', e.amount,\n            'currency', e.currency,\n            'due_date', e.due_date,\n            'expense_id', e.id,\n            'series_id', e.series_id,\n            'month', e.month\n        )\n    FROM budget.expense_items e\n    LEFT JOIN budget.expense_series s ON s.id = e.series_id\n    INNER JOIN public.profiles p ON p.workspace_id = e.workspace_id AND p.role = 'admin'\n    WHERE e.is_deleted = FALSE\n      AND e.due_date < CURRENT_DATE\n      AND e.status <> 'paid'\n      AND (\n        e.status <> 'snoozed'\n        OR (e.snoozed_indefinite = FALSE AND e.snoozed_until IS NOT NULL AND e.snoozed_until <= NOW())\n      )\n    ON CONFLICT DO NOTHING;\n\n    -- 2. Budget: payroll statuses (Individual)\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        ps.workspace_id,\n        p.id AS user_id,\n        'budget_payroll' AS entity_type,\n        ps.id::TEXT AS entity_id,\n        due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_payroll',\n            'title', COALESCE(emp.name, 'Payroll'),\n            'amount', emp.salary,\n            'currency', emp.salary_currency,\n            'due_date', due_date,\n            'month', ps.month,\n            'employee_id', emp.id,\n            'status_id', ps.id\n        )\n    FROM budget.payroll_statuses ps\n    INNER JOIN public.employees emp ON emp.id = ps.employee_id\n    INNER JOIN public.profiles p ON p.workspace_id = ps.workspace_id AND p.role = 'admin'\n    CROSS JOIN LATERAL notifications.compute_due_date(ps.month, emp.salary_payday) AS due_date\n    WHERE ps.is_deleted = FALSE\n      AND due_date IS NOT NULL\n      AND due_date < CURRENT_DATE\n      AND ps.status <> 'paid'\n      AND (\n        ps.status <> 'snoozed'\n        OR (ps.snoozed_indefinite = FALSE AND ps.snoozed_until IS NOT NULL AND ps.snoozed_until <= NOW())\n      )\n    ON CONFLICT DO NOTHING;\n\n    -- 3. Budget: dividend statuses (GROUPED per month/workspace)\n    WITH overdue_divs AS (\n        SELECT\n            ds.workspace_id,\n            ds.month,\n            MIN(due_date) as oldest_due_date,\n            COUNT(*) as holder_count\n        FROM budget.dividend_statuses ds\n        INNER JOIN public.employees emp ON emp.id = ds.employee_id\n        CROSS JOIN LATERAL notifications.compute_due_date(ds.month, emp.dividend_payday) AS due_date\n        WHERE ds.is_deleted = FALSE\n          AND emp.has_dividends = TRUE\n          AND due_date IS NOT NULL\n          AND due_date < CURRENT_DATE\n          AND ds.status <> 'paid'\n          AND (\n            ds.status <> 'snoozed'\n            OR (ds.snoozed_indefinite = FALSE AND ds.snoozed_until IS NOT NULL AND ds.snoozed_until <= NOW())\n          )\n        GROUP BY ds.workspace_id, ds.month\n    )\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        o.workspace_id,\n        p.id AS user_id,\n        'budget_dividend' AS entity_type,\n        o.month AS entity_id,\n        o.oldest_due_date,\n        jsonb_build_object(\n            'entity_type', 'budget_dividend',\n            'title', 'Outstanding Dividends',\n            'content', 'Some shareholders have not yet withdrawn their dividends for the month of ' || o.month || '.',\n            'holder_count', o.holder_count,\n            'month', o.month,\n            'due_date', o.oldest_due_date\n        )\n    FROM overdue_divs o\n    INNER JOIN public.profiles p ON p.workspace_id = o.workspace_id AND p.role = 'admin'\n    ON CONFLICT DO NOTHING;\n\n    -- 4. Loans: aggregated overdue installments (Grouped)\n    WITH overdue_loans AS (\n        SELECT\n            li.loan_id,\n            l.workspace_id,\n            MIN(li.due_date) AS oldest_due_date,\n            SUM(li.balance_amount) AS overdue_amount,\n            COUNT(*) AS overdue_installment_count\n        FROM public.loan_installments li\n        INNER JOIN public.loans l ON l.id = li.loan_id\n        WHERE li.is_deleted = FALSE\n          AND l.is_deleted = FALSE\n          AND li.balance_amount > 0\n          AND li.due_date < CURRENT_DATE\n        GROUP BY li.loan_id, l.workspace_id\n    )\n    INSERT INTO notifications.events (workspace_id, user_id, entity_type, entity_id, due_date, payload)\n    SELECT\n        o.workspace_id,\n        p.id AS user_id,\n        'loan_overdue' AS entity_type,\n        l.id::TEXT AS entity_id,\n        o.oldest_due_date,\n        jsonb_build_object(\n            'entity_type', 'loan_overdue',\n            'title', l.borrower_name, -- CHANGED: Use borrower_name instead of loan_no\n            'loan_id', l.id,\n            'loan_no', l.loan_no,\n            'borrower_name', l.borrower_name,\n            'due_date', o.oldest_due_date,\n            'amount', o.overdue_amount,\n            'overdue_amount', o.overdue_amount,\n            'overdue_installment_count', o.overdue_installment_count,\n            'balance_amount', l.balance_amount,\n            'currency', l.settlement_currency\n        )\n    FROM overdue_loans o\n    INNER JOIN public.loans l ON l.id = o.loan_id\n    INNER JOIN public.profiles p ON p.workspace_id = o.workspace_id AND p.role = 'admin'\n    WHERE l.is_deleted = FALSE\n      AND (l.overdue_reminder_snoozed_for_due_date IS NULL OR l.overdue_reminder_snoozed_for_due_date <> o.oldest_due_date)\n    ON CONFLICT DO NOTHING;\nEND;\n$$;\n"}	use_borrower_name_as_title	masteralan360@gmail.com	\N	\N
20260315194607	{"CREATE OR REPLACE FUNCTION public.complete_sale(payload jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    new_sale_id UUID;\n    v_sequence_id BIGINT;\n    item JSONB;\n    p_workspace_id UUID;\n    total_sale_amount NUMERIC := 0;\n    v_allow_pos BOOLEAN;\nBEGIN\n    -- Get current user's workspace\n    SELECT workspace_id INTO p_workspace_id \n    FROM public.profiles \n    WHERE id = auth.uid();\n\n    IF p_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'User does not belong to a workspace';\n    END IF;\n\n    -- Check if POS feature is enabled for this workspace\n    SELECT allow_pos INTO v_allow_pos\n    FROM public.workspaces\n    WHERE id = p_workspace_id;\n\n    IF NOT COALESCE(v_allow_pos, false) THEN\n        RAISE EXCEPTION 'POS feature is not enabled for this workspace';\n    END IF;\n\n    total_sale_amount := (payload->>'total_amount')::NUMERIC;\n\n    -- Insert Sale Record\n    INSERT INTO public.sales (\n        id,\n        workspace_id, \n        cashier_id, \n        total_amount, \n        settlement_currency,\n        exchange_source,\n        exchange_rate,\n        exchange_rate_timestamp,\n        exchange_rates,\n        origin,\n        payment_method,\n        system_verified,\n        system_review_status,\n        system_review_reason,\n        notes -- Added field\n    )\n    VALUES (\n        COALESCE((payload->>'id')::UUID, gen_random_uuid()),\n        p_workspace_id, \n        auth.uid(), \n        total_sale_amount, \n        COALESCE(payload->>'settlement_currency', 'usd'),\n        COALESCE(payload->>'exchange_source', 'xeiqd'),\n        COALESCE((payload->>'exchange_rate')::NUMERIC, 0),\n        COALESCE((payload->>'exchange_rate_timestamp')::TIMESTAMPTZ, NOW()),\n        COALESCE((payload->'exchange_rates'), '[]'::jsonb),\n        COALESCE(payload->>'origin', 'pos'),\n        COALESCE(payload->>'payment_method', 'cash'),\n        COALESCE((payload->>'system_verified')::BOOLEAN, true),\n        COALESCE(payload->>'system_review_status', 'approved'),\n        payload->>'system_review_reason',\n        payload->>'notes' -- Added field\n    )\n    RETURNING id, sequence_id INTO new_sale_id, v_sequence_id;\n\n    -- Process Items\n    FOR item IN SELECT * FROM jsonb_array_elements(payload->'items')\n    LOOP\n        -- Insert Sale Item\n        INSERT INTO public.sale_items (\n            sale_id, \n            product_id, \n            quantity, \n            unit_price, \n            total_price,\n            cost_price,\n            converted_cost_price,\n            original_currency,\n            original_unit_price,\n            converted_unit_price,\n            settlement_currency,\n            negotiated_price,\n            inventory_snapshot\n        )\n        VALUES (\n            new_sale_id,\n            (item->>'product_id')::UUID,\n            (item->>'quantity')::INTEGER,\n            (item->>'unit_price')::NUMERIC,\n            (item->>'total_price')::NUMERIC,\n            COALESCE((item->>'cost_price')::NUMERIC, 0),\n            COALESCE((item->>'converted_cost_price')::NUMERIC, 0),\n            COALESCE(item->>'original_currency', 'usd'),\n            COALESCE((item->>'original_unit_price')::NUMERIC, (item->>'unit_price')::NUMERIC),\n            COALESCE((item->>'converted_unit_price')::NUMERIC, (item->>'unit_price')::NUMERIC),\n            COALESCE(item->>'settlement_currency', 'usd'),\n            (item->>'negotiated_price')::NUMERIC,\n            COALESCE((item->>'inventory_snapshot')::INTEGER, 0)\n        );\n\n        -- Update Inventory\n        UPDATE public.products\n        SET quantity = quantity - (item->>'quantity')::INTEGER\n        WHERE id = (item->>'product_id')::UUID\n          AND workspace_id = p_workspace_id;\n    END LOOP;\n\n    RETURN jsonb_build_object(\n        'success', true, \n        'sale_id', new_sale_id,\n        'sequence_id', v_sequence_id\n    );\nEND;\n$function$"}	add_notes_to_complete_sale_rpc	masteralan360@gmail.com	\N	\N
20260317194725	{"\n-- Fix duplicate: regenerate admin_passkey to a unique value using pgcrypto\nUPDATE public.app_permissions\nSET key_value = encode(gen_random_bytes(13), 'hex')\nWHERE key_name = 'admin_passkey';\n\n-- Add rotation tracking column\nALTER TABLE public.app_permissions\n  ADD COLUMN rotated_at timestamptz NOT NULL DEFAULT now();\n\n-- Backfill existing rows\nUPDATE public.app_permissions SET rotated_at = now();\n\n-- Enforce uniqueness on key_value\nALTER TABLE public.app_permissions\n  ADD CONSTRAINT app_permissions_key_value_unique UNIQUE (key_value);\n"}	add_rotated_at_and_unique_key_value	masteralan360@gmail.com	\N	\N
20260317194739	{"\n-- Reusable cryptographically secure alphanumeric key generator\n-- Uses pgcrypto's gen_random_bytes for CSPRNG\nCREATE OR REPLACE FUNCTION generate_secure_key(key_length int DEFAULT 32)\nRETURNS text\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  chars text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';\n  result text := '';\n  random_bytes bytea;\n  i int;\nBEGIN\n  random_bytes := gen_random_bytes(key_length);\n  FOR i IN 0..key_length - 1 LOOP\n    result := result || substr(chars, (get_byte(random_bytes, i) % 62) + 1, 1);\n  END LOOP;\n  RETURN result;\nEND;\n$$;\n"}	create_generate_secure_key_function	masteralan360@gmail.com	\N	\N
20260317194806	{"\n-- Trigger function: auto-create a key in app_permissions on user registration\nCREATE OR REPLACE FUNCTION create_user_api_key()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n  new_key text;\n  max_attempts int := 5;\n  attempt int := 0;\nBEGIN\n  LOOP\n    attempt := attempt + 1;\n    new_key := generate_secure_key(32);\n\n    BEGIN\n      INSERT INTO public.app_permissions (key_name, key_value, rotated_at)\n      VALUES ('user_' || NEW.id, new_key, now());\n      EXIT; -- success, break out of loop\n    EXCEPTION\n      WHEN unique_violation THEN\n        IF attempt >= max_attempts THEN\n          RAISE EXCEPTION 'Failed to generate unique API key after % attempts', max_attempts;\n        END IF;\n        -- retry with a new key\n    END;\n  END LOOP;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- Fire AFTER INSERT on auth.users (separate from handle_new_user)\nCREATE TRIGGER on_auth_user_created_api_key\n  AFTER INSERT ON auth.users\n  FOR EACH ROW\n  EXECUTE FUNCTION create_user_api_key();\n"}	create_user_api_key_trigger	masteralan360@gmail.com	\N	\N
20260317194819	{"\n-- Weekly key rotation function\n-- Only rotates keys older than 7 days. Idempotent and safe for concurrent/repeated runs.\nCREATE OR REPLACE FUNCTION rotate_app_permission_keys()\nRETURNS int\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n  rotated_count int := 0;\n  rec record;\n  new_key text;\n  attempt int;\nBEGIN\n  FOR rec IN\n    SELECT key_name\n    FROM public.app_permissions\n    WHERE rotated_at < now() - interval '7 days'\n    FOR UPDATE SKIP LOCKED\n  LOOP\n    attempt := 0;\n    LOOP\n      attempt := attempt + 1;\n      new_key := generate_secure_key(32);\n\n      BEGIN\n        UPDATE public.app_permissions\n        SET key_value = new_key, rotated_at = now()\n        WHERE key_name = rec.key_name;\n        rotated_count := rotated_count + 1;\n        EXIT;\n      EXCEPTION\n        WHEN unique_violation THEN\n          IF attempt >= 5 THEN\n            RAISE WARNING 'Skipping key % after 5 failed unique-key attempts', rec.key_name;\n            EXIT;\n          END IF;\n      END;\n    END LOOP;\n  END LOOP;\n\n  RAISE LOG 'Key rotation complete: % keys rotated', rotated_count;\n  RETURN rotated_count;\nEND;\n$$;\n\n-- Schedule weekly rotation: Sunday 03:00 UTC\nSELECT cron.schedule(\n  'rotate-app-permission-keys',\n  '0 3 * * 0',\n  'SELECT rotate_app_permission_keys();'\n);\n"}	create_rotation_function_and_cron_job	masteralan360@gmail.com	\N	\N
20260317195623	{"\n-- Fix: schema-qualify function calls and set search_path so auth trigger can find them\nCREATE OR REPLACE FUNCTION public.create_user_api_key()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  new_key text;\n  max_attempts int := 5;\n  attempt int := 0;\nBEGIN\n  LOOP\n    attempt := attempt + 1;\n    new_key := public.generate_secure_key(32);\n\n    BEGIN\n      INSERT INTO public.app_permissions (key_name, key_value, rotated_at)\n      VALUES ('user_' || NEW.id, new_key, now());\n      EXIT;\n    EXCEPTION\n      WHEN unique_violation THEN\n        IF attempt >= max_attempts THEN\n          RAISE EXCEPTION 'Failed to generate unique API key after % attempts', max_attempts;\n        END IF;\n    END;\n  END LOOP;\n\n  RETURN NEW;\nEND;\n$$;\n"}	fix_create_user_api_key_search_path	masteralan360@gmail.com	\N	\N
20260317195804	{"\n-- Fix generate_secure_key: include extensions schema for gen_random_bytes\nCREATE OR REPLACE FUNCTION public.generate_secure_key(key_length int DEFAULT 32)\nRETURNS text\nLANGUAGE plpgsql\nSET search_path = public, extensions\nAS $$\nDECLARE\n  chars text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';\n  result text := '';\n  random_bytes bytea;\n  i int;\nBEGIN\n  random_bytes := extensions.gen_random_bytes(key_length);\n  FOR i IN 0..key_length - 1 LOOP\n    result := result || substr(chars, (get_byte(random_bytes, i) % 62) + 1, 1);\n  END LOOP;\n  RETURN result;\nEND;\n$$;\n\n-- Fix create_user_api_key: include extensions in search_path\nCREATE OR REPLACE FUNCTION public.create_user_api_key()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, extensions\nAS $$\nDECLARE\n  new_key text;\n  max_attempts int := 5;\n  attempt int := 0;\nBEGIN\n  LOOP\n    attempt := attempt + 1;\n    new_key := public.generate_secure_key(32);\n\n    BEGIN\n      INSERT INTO public.app_permissions (key_name, key_value, rotated_at)\n      VALUES ('user_' || NEW.id, new_key, now());\n      EXIT;\n    EXCEPTION\n      WHEN unique_violation THEN\n        IF attempt >= max_attempts THEN\n          RAISE EXCEPTION 'Failed to generate unique API key after % attempts', max_attempts;\n        END IF;\n    END;\n  END LOOP;\n\n  RETURN NEW;\nEND;\n$$;\n"}	fix_search_path_for_extensions	masteralan360@gmail.com	\N	\N
20260317195953	{"\n-- 1. Remove pg_cron job\nSELECT cron.unschedule('rotate-app-permission-keys');\n\n-- 2. Drop the registration trigger\nDROP TRIGGER IF EXISTS on_auth_user_created_api_key ON auth.users;\n\n-- 3. Drop all created functions\nDROP FUNCTION IF EXISTS public.create_user_api_key() CASCADE;\nDROP FUNCTION IF EXISTS public.rotate_app_permission_keys() CASCADE;\nDROP FUNCTION IF EXISTS public.generate_secure_key(int) CASCADE;\n\n-- 4. Delete any user-generated keys (user_* rows)\nDELETE FROM public.app_permissions WHERE key_name LIKE 'user_%';\n\n-- 5. Drop the UNIQUE constraint on key_value\nALTER TABLE public.app_permissions DROP CONSTRAINT IF EXISTS app_permissions_key_value_unique;\n\n-- 6. Drop the rotated_at column\nALTER TABLE public.app_permissions DROP COLUMN IF EXISTS rotated_at;\n\n-- 7. Restore original admin_passkey value (was same as registration_passkey)\nUPDATE public.app_permissions\nSET key_value = (SELECT key_value FROM public.app_permissions WHERE key_name = 'registration_passkey')\nWHERE key_name = 'admin_passkey';\n"}	revert_key_rotation_system	masteralan360@gmail.com	\N	\N
20260318153905	{"begin;\n\ncreate or replace function public.rotate_signup_safe_app_permissions_keys()\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\nbegin\n    update public.app_permissions\n    set key_value = public.generate_random_alphanumeric_key(32)\n    where key_name in (\n        'connection_admin',\n        'update_key'\n    );\nend;\n$function$;\n\ncreate or replace function public.trigger_rotate_keys_on_register()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\nbegin\n    perform public.rotate_signup_safe_app_permissions_keys();\n    return new;\nend;\n$function$;\n\ncommit;"}	rotate_signup_safe_app_permissions_keys	masteralan360@gmail.com	\N	\N
20260319180335	{"-- Drop tables and cascade\nDROP TABLE IF EXISTS public.purchase_orders CASCADE;\nDROP TABLE IF EXISTS public.sales_orders CASCADE;\nDROP TABLE IF EXISTS public.suppliers CASCADE;\nDROP TABLE IF EXISTS public.customers CASCADE;\n\n-- Remove columns from workspaces\nALTER TABLE public.workspaces \nDROP COLUMN IF EXISTS allow_customers,\nDROP COLUMN IF EXISTS allow_suppliers,\nDROP COLUMN IF EXISTS allow_orders;\n\n-- Drop functions before recreating them to avoid type mismatch errors\nDROP FUNCTION IF EXISTS public.admin_update_workspace_features(text, uuid, boolean, boolean, boolean, boolean);\nDROP FUNCTION IF EXISTS public.admin_update_workspace_features(text, uuid, boolean, boolean, boolean, boolean, boolean);\nDROP FUNCTION IF EXISTS public.configure_workspace(boolean, boolean, boolean, boolean, text);\nDROP FUNCTION IF EXISTS public.configure_workspace(text, boolean, boolean, boolean, boolean, boolean, text);\nDROP FUNCTION IF EXISTS public.get_all_workspaces(text);\nDROP FUNCTION IF EXISTS public.get_workspace_features();\n\n-- Recreate Functions\n-- 1. admin_update_workspace_features\nCREATE OR REPLACE FUNCTION public.admin_update_workspace_features(provided_key text, target_workspace_id uuid, new_allow_pos boolean, new_allow_invoices boolean, new_locked_workspace boolean DEFAULT NULL::boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n    -- Verify admin passkey\n    IF NOT public.verify_admin_passkey(provided_key) THEN\n        RAISE EXCEPTION 'Invalid admin passkey';\n    END IF;\n\n    UPDATE public.workspaces\n    SET \n        allow_pos = new_allow_pos,\n        allow_invoices = new_allow_invoices,\n        locked_workspace = COALESCE(new_locked_workspace, locked_workspace)\n    WHERE id = target_workspace_id;\n\n    RETURN true;\nEND;\n$function$;\n\n-- 2. configure_workspace\nCREATE OR REPLACE FUNCTION public.configure_workspace(p_data_mode text DEFAULT 'cloud'::text, p_allow_pos boolean DEFAULT false, p_allow_invoices boolean DEFAULT false, p_logo_url text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\ndeclare\n    v_workspace_id uuid;\n    v_user_role text;\n    v_is_configured boolean;\n    normalized_mode text;\nbegin\n    select workspace_id, role into v_workspace_id, v_user_role\n    from public.profiles\n    where id = auth.uid();\n\n    if v_workspace_id is null then\n        raise exception 'User does not belong to a workspace';\n    end if;\n\n    if v_user_role != 'admin' then\n        raise exception 'Unauthorized: Only admins can configure workspace features';\n    end if;\n\n    select coalesce(is_configured, false)\n    into v_is_configured\n    from public.workspaces\n    where id = v_workspace_id;\n\n    if v_is_configured then\n        raise exception 'Workspace has already been configured. Mode changes are not allowed.';\n    end if;\n\n    normalized_mode := lower(coalesce(p_data_mode, 'cloud'));\n\n    if normalized_mode not in ('cloud', 'local') then\n        raise exception 'Invalid workspace mode: %', p_data_mode;\n    end if;\n\n    update public.workspaces\n    set\n        data_mode = normalized_mode,\n        allow_pos = p_allow_pos,\n        allow_invoices = p_allow_invoices,\n        logo_url = p_logo_url,\n        is_configured = true\n    where id = v_workspace_id;\n\n    return jsonb_build_object(\n        'success', true,\n        'data_mode', normalized_mode,\n        'allow_pos', p_allow_pos,\n        'allow_invoices', p_allow_invoices,\n        'logo_url', p_logo_url\n    );\nend;\n$function$;\n\n-- 3. get_all_workspaces\nCREATE OR REPLACE FUNCTION public.get_all_workspaces(provided_key text)\n RETURNS TABLE(id uuid, name text, code text, created_at timestamp with time zone, data_mode text, allow_pos boolean, allow_invoices boolean, is_configured boolean, locked_workspace boolean, deleted_at timestamp with time zone, coordination text, logo_url text, subscription_expires_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nbegin\n    if not public.verify_admin_passkey(provided_key) then\n        raise exception 'Unauthorized: Invalid admin passkey';\n    end if;\n\n    return query\n    select\n        w.id,\n        w.name,\n        w.code,\n        w.created_at,\n        coalesce(w.data_mode, 'cloud'),\n        coalesce(w.allow_pos, false),\n        coalesce(w.allow_invoices, false),\n        coalesce(w.is_configured, false),\n        coalesce(w.locked_workspace, false),\n        w.deleted_at,\n        w.coordination,\n        w.logo_url,\n        w.subscription_expires_at\n    from public.workspaces w\n    order by w.created_at desc;\nend;\n$function$;\n\n-- 4. get_workspace_features\nCREATE OR REPLACE FUNCTION public.get_workspace_features()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\ndeclare\n    v_workspace_id uuid;\n    v_result jsonb;\nbegin\n    select workspace_id into v_workspace_id\n    from public.profiles\n    where id = auth.uid();\n\n    if v_workspace_id is null then\n        return jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_invoices', false,\n            'is_configured', false,\n            'coordination', null,\n            'print_quality', 'low',\n            'kds_enabled', false\n        );\n    end if;\n\n    select jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'data_mode', coalesce(data_mode, 'cloud'),\n        'allow_pos', coalesce(allow_pos, false),\n        'allow_invoices', coalesce(allow_invoices, false),\n        'is_configured', coalesce(is_configured, false),\n        'default_currency', coalesce(default_currency, 'usd'),\n        'iqd_display_preference', coalesce(iqd_display_preference, 'IQD'),\n        'eur_conversion_enabled', coalesce(eur_conversion_enabled, false),\n        'try_conversion_enabled', coalesce(try_conversion_enabled, false),\n        'locked_workspace', coalesce(locked_workspace, false),\n        'logo_url', logo_url,\n        'coordination', coordination,\n        'max_discount_percent', coalesce(max_discount_percent, 100),\n        'allow_whatsapp', coalesce(allow_whatsapp, false),\n        'kds_enabled', coalesce(kds_enabled, false),\n        'print_lang', coalesce(print_lang, 'auto'),\n        'print_qr', coalesce(print_qr, false),\n        'receipt_template', coalesce(receipt_template, 'primary'),\n        'a4_template', coalesce(a4_template, 'primary'),\n        'print_quality', coalesce(print_quality, 'low'),\n        'subscription_expires_at', subscription_expires_at\n    ) into v_result\n    from public.workspaces\n    where id = v_workspace_id;\n\n    return v_result;\nend;\n$function$;\n"}	remove_suppliers_customers_orders_v2	masteralan360@gmail.com	\N	\N
