20260324165734	{"\n-- Step 1: Create the enum type\nCREATE TYPE workspace_data_mode AS ENUM ('cloud', 'local');\n\n-- Step 2: Fill any NULLs\nUPDATE workspaces SET data_mode = 'cloud' WHERE data_mode IS NULL;\n\n-- Step 3: Drop the CHECK constraint (enum enforces valid values)\nALTER TABLE workspaces DROP CONSTRAINT workspaces_data_mode_check;\n\n-- Step 4: Drop existing default, convert type, set new default + NOT NULL\nALTER TABLE workspaces ALTER COLUMN data_mode DROP DEFAULT;\nALTER TABLE workspaces ALTER COLUMN data_mode TYPE workspace_data_mode USING data_mode::workspace_data_mode;\nALTER TABLE workspaces ALTER COLUMN data_mode SET DEFAULT 'cloud'::workspace_data_mode;\nALTER TABLE workspaces ALTER COLUMN data_mode SET NOT NULL;\n\n-- Step 5: Recreate trigger function (same logic, now works with enum type)\nCREATE OR REPLACE FUNCTION public.prevent_workspace_mode_switch()\nRETURNS trigger\nLANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF NEW.data_mode IS DISTINCT FROM OLD.data_mode AND COALESCE(OLD.is_configured, false) THEN\n    RAISE EXCEPTION 'Workspace mode cannot be changed after initial configuration';\n  END IF;\n  RETURN NEW;\nEND;\n$function$;\n\n-- Step 6: Update RPC function (data_mode is now a proper enum, no COALESCE needed)\nCREATE OR REPLACE FUNCTION get_workspace_features()\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_crm', true,\n            'allow_invoices', false,\n            'is_configured', false,\n            'coordination', null,\n            'print_quality', 'low',\n            'kds_enabled', false\n        );\n    END IF;\n\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'data_mode', data_mode,\n        'allow_pos', COALESCE(allow_pos, false),\n        'allow_crm', COALESCE(allow_crm, true),\n        'allow_invoices', COALESCE(allow_invoices, false),\n        'is_configured', COALESCE(is_configured, false),\n        'default_currency', COALESCE(default_currency, 'usd'),\n        'iqd_display_preference', COALESCE(iqd_display_preference, 'IQD'),\n        'eur_conversion_enabled', COALESCE(eur_conversion_enabled, false),\n        'try_conversion_enabled', COALESCE(try_conversion_enabled, false),\n        'locked_workspace', COALESCE(locked_workspace, false),\n        'logo_url', logo_url,\n        'coordination', coordination,\n        'max_discount_percent', COALESCE(max_discount_percent, 100),\n        'allow_whatsapp', COALESCE(allow_whatsapp, false),\n        'kds_enabled', COALESCE(kds_enabled, false),\n        'print_lang', COALESCE(print_lang, 'auto'),\n        'print_qr', COALESCE(print_qr, false),\n        'receipt_template', COALESCE(receipt_template, 'primary'),\n        'a4_template', COALESCE(a4_template, 'primary'),\n        'print_quality', COALESCE(print_quality, 'low'),\n        'subscription_expires_at', subscription_expires_at,\n        'allow_customers', COALESCE(allow_customers, false),\n        'allow_orders', COALESCE(allow_orders, false),\n        'allow_suppliers', COALESCE(allow_suppliers, false)\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN v_result;\nEND;\n$$;\n"}	convert_data_mode_to_enum_v3	masteralan360@gmail.com	\N	\N
20260324170216	{"\n-- Create enum types\nCREATE TYPE print_quality_type AS ENUM ('low', 'high');\nCREATE TYPE template_style AS ENUM ('primary', 'modern');\n\n-- Fill NULLs\nUPDATE workspaces SET print_quality = 'low' WHERE print_quality IS NULL;\nUPDATE workspaces SET receipt_template = 'primary' WHERE receipt_template IS NULL;\nUPDATE workspaces SET a4_template = 'primary' WHERE a4_template IS NULL;\n\n-- Drop CHECK constraints\nALTER TABLE workspaces DROP CONSTRAINT workspaces_print_quality_check;\nALTER TABLE workspaces DROP CONSTRAINT workspaces_receipt_template_check;\nALTER TABLE workspaces DROP CONSTRAINT workspaces_a4_template_check;\n\n-- Convert print_quality\nALTER TABLE workspaces ALTER COLUMN print_quality DROP DEFAULT;\nALTER TABLE workspaces ALTER COLUMN print_quality TYPE print_quality_type USING print_quality::print_quality_type;\nALTER TABLE workspaces ALTER COLUMN print_quality SET DEFAULT 'low'::print_quality_type;\nALTER TABLE workspaces ALTER COLUMN print_quality SET NOT NULL;\n\n-- Convert receipt_template\nALTER TABLE workspaces ALTER COLUMN receipt_template DROP DEFAULT;\nALTER TABLE workspaces ALTER COLUMN receipt_template TYPE template_style USING receipt_template::template_style;\nALTER TABLE workspaces ALTER COLUMN receipt_template SET DEFAULT 'primary'::template_style;\nALTER TABLE workspaces ALTER COLUMN receipt_template SET NOT NULL;\n\n-- Convert a4_template\nALTER TABLE workspaces ALTER COLUMN a4_template DROP DEFAULT;\nALTER TABLE workspaces ALTER COLUMN a4_template TYPE template_style USING a4_template::template_style;\nALTER TABLE workspaces ALTER COLUMN a4_template SET DEFAULT 'primary'::template_style;\nALTER TABLE workspaces ALTER COLUMN a4_template SET NOT NULL;\n\n-- Update RPC function\nCREATE OR REPLACE FUNCTION get_workspace_features()\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_crm', true,\n            'allow_invoices', false,\n            'is_configured', false,\n            'coordination', null,\n            'print_quality', 'low',\n            'kds_enabled', false\n        );\n    END IF;\n\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'data_mode', data_mode,\n        'allow_pos', COALESCE(allow_pos, false),\n        'allow_crm', COALESCE(allow_crm, true),\n        'allow_invoices', COALESCE(allow_invoices, false),\n        'is_configured', COALESCE(is_configured, false),\n        'default_currency', COALESCE(default_currency, 'usd'),\n        'iqd_display_preference', COALESCE(iqd_display_preference, 'IQD'),\n        'eur_conversion_enabled', COALESCE(eur_conversion_enabled, false),\n        'try_conversion_enabled', COALESCE(try_conversion_enabled, false),\n        'locked_workspace', COALESCE(locked_workspace, false),\n        'logo_url', logo_url,\n        'coordination', coordination,\n        'max_discount_percent', COALESCE(max_discount_percent, 100),\n        'allow_whatsapp', COALESCE(allow_whatsapp, false),\n        'kds_enabled', COALESCE(kds_enabled, false),\n        'print_lang', COALESCE(print_lang, 'auto'),\n        'print_qr', COALESCE(print_qr, false),\n        'receipt_template', receipt_template,\n        'a4_template', a4_template,\n        'print_quality', print_quality,\n        'subscription_expires_at', subscription_expires_at,\n        'allow_customers', COALESCE(allow_customers, false),\n        'allow_orders', COALESCE(allow_orders, false),\n        'allow_suppliers', COALESCE(allow_suppliers, false)\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN v_result;\nEND;\n$$;\n"}	convert_template_and_quality_to_enums	masteralan360@gmail.com	\N	\N
20260324170658	{"\n-- Step 1: Create the enum types\nCREATE TYPE currency_code AS ENUM ('usd', 'eur', 'iqd', 'try');\nCREATE TYPE iqd_display_preference_enum AS ENUM ('IQD', 'د.ع');\nCREATE TYPE print_lang_enum AS ENUM ('auto', 'en', 'ar', 'ku');\n\n-- Step 2: Handle any NULLs or invalid values for print_lang (default_currency and iqd_display_preference were already NOT NULL)\nUPDATE workspaces SET print_lang = 'auto' WHERE print_lang IS NULL OR print_lang NOT IN ('auto', 'en', 'ar', 'ku');\n\n-- Step 3: Drop existing defaults\nALTER TABLE workspaces ALTER COLUMN default_currency DROP DEFAULT;\nALTER TABLE workspaces ALTER COLUMN iqd_display_preference DROP DEFAULT;\nALTER TABLE workspaces ALTER COLUMN print_lang DROP DEFAULT;\n\n-- Step 4: Convert column types\nALTER TABLE workspaces ALTER COLUMN default_currency TYPE currency_code USING default_currency::currency_code;\nALTER TABLE workspaces ALTER COLUMN iqd_display_preference TYPE iqd_display_preference_enum USING iqd_display_preference::iqd_display_preference_enum;\nALTER TABLE workspaces ALTER COLUMN print_lang TYPE print_lang_enum USING print_lang::print_lang_enum;\n\n-- Step 5: Set new defaults and NOT NULL for print_lang\nALTER TABLE workspaces ALTER COLUMN default_currency SET DEFAULT 'usd'::currency_code;\nALTER TABLE workspaces ALTER COLUMN iqd_display_preference SET DEFAULT 'IQD'::iqd_display_preference_enum;\nALTER TABLE workspaces ALTER COLUMN print_lang SET DEFAULT 'auto'::print_lang_enum;\nALTER TABLE workspaces ALTER COLUMN print_lang SET NOT NULL;\n\n-- Step 6: Update the get_workspace_features RPC to return enums directly\nCREATE OR REPLACE FUNCTION get_workspace_features()\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_crm', true,\n            'allow_invoices', false,\n            'is_configured', false,\n            'coordination', null,\n            'print_quality', 'low',\n            'kds_enabled', false\n        );\n    END IF;\n\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'data_mode', data_mode,\n        'allow_pos', COALESCE(allow_pos, false),\n        'allow_crm', COALESCE(allow_crm, true),\n        'allow_invoices', COALESCE(allow_invoices, false),\n        'is_configured', COALESCE(is_configured, false),\n        'default_currency', default_currency,\n        'iqd_display_preference', iqd_display_preference,\n        'eur_conversion_enabled', COALESCE(eur_conversion_enabled, false),\n        'try_conversion_enabled', COALESCE(try_conversion_enabled, false),\n        'locked_workspace', COALESCE(locked_workspace, false),\n        'logo_url', logo_url,\n        'coordination', coordination,\n        'max_discount_percent', COALESCE(max_discount_percent, 100),\n        'allow_whatsapp', COALESCE(allow_whatsapp, false),\n        'kds_enabled', COALESCE(kds_enabled, false),\n        'print_lang', print_lang,\n        'print_qr', COALESCE(print_qr, false),\n        'receipt_template', receipt_template,\n        'a4_template', a4_template,\n        'print_quality', print_quality,\n        'subscription_expires_at', subscription_expires_at,\n        'allow_customers', COALESCE(allow_customers, false),\n        'allow_orders', COALESCE(allow_orders, false),\n        'allow_suppliers', COALESCE(allow_suppliers, false)\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN v_result;\nEND;\n$$;\n"}	convert_currency_display_and_lang_to_enums_v10	masteralan360@gmail.com	\N	\N
20260324170948	{"\n-- Step 1: Ensure no NULLs exist (all currently default to false, but let's be safe)\nUPDATE workspaces SET eur_conversion_enabled = COALESCE(eur_conversion_enabled, false);\nUPDATE workspaces SET try_conversion_enabled = COALESCE(try_conversion_enabled, false);\nUPDATE workspaces SET locked_workspace = COALESCE(locked_workspace, false);\nUPDATE workspaces SET allow_whatsapp = COALESCE(allow_whatsapp, false);\nUPDATE workspaces SET print_qr = COALESCE(print_qr, false);\n\n-- Step 2: Alter columns to NOT NULL\nALTER TABLE workspaces ALTER COLUMN eur_conversion_enabled SET NOT NULL;\nALTER TABLE workspaces ALTER COLUMN try_conversion_enabled SET NOT NULL;\nALTER TABLE workspaces ALTER COLUMN locked_workspace SET NOT NULL;\nALTER TABLE workspaces ALTER COLUMN allow_whatsapp SET NOT NULL;\nALTER TABLE workspaces ALTER COLUMN print_qr SET NOT NULL;\n\n-- Step 3: Update the get_workspace_features RPC function to remove COALESCE for these fields\nCREATE OR REPLACE FUNCTION get_workspace_features()\nRETURNS JSONB\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'allow_pos', false,\n            'allow_crm', true,\n            'allow_invoices', false,\n            'is_configured', false,\n            'coordination', null,\n            'print_quality', 'low',\n            'kds_enabled', false\n        );\n    END IF;\n\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'data_mode', data_mode,\n        'allow_pos', COALESCE(allow_pos, false),\n        'allow_crm', COALESCE(allow_crm, true),\n        'allow_invoices', COALESCE(allow_invoices, false),\n        'is_configured', COALESCE(is_configured, false),\n        'default_currency', default_currency,\n        'iqd_display_preference', iqd_display_preference,\n        'eur_conversion_enabled', eur_conversion_enabled,\n        'try_conversion_enabled', try_conversion_enabled,\n        'locked_workspace', locked_workspace,\n        'logo_url', logo_url,\n        'coordination', coordination,\n        'max_discount_percent', COALESCE(max_discount_percent, 100),\n        'allow_whatsapp', allow_whatsapp,\n        'kds_enabled', COALESCE(kds_enabled, false),\n        'print_lang', print_lang,\n        'print_qr', print_qr,\n        'receipt_template', receipt_template,\n        'a4_template', a4_template,\n        'print_quality', print_quality,\n        'subscription_expires_at', subscription_expires_at,\n        'allow_customers', COALESCE(allow_customers, false),\n        'allow_orders', COALESCE(allow_orders, false),\n        'allow_suppliers', COALESCE(allow_suppliers, false)\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN v_result;\nEND;\n$$;\n"}	make_booleans_not_null_v11	masteralan360@gmail.com	\N	\N
20260324174315	{"\n-- 1. Rename existing allow_* columns\nALTER TABLE public.workspaces RENAME COLUMN allow_pos TO pos;\nALTER TABLE public.workspaces RENAME COLUMN allow_crm TO crm;\nALTER TABLE public.workspaces RENAME COLUMN allow_invoices TO invoices_history;\n\n-- 2. Drop CRM sub-columns (folded into crm)\nALTER TABLE public.workspaces DROP COLUMN IF EXISTS allow_customers;\nALTER TABLE public.workspaces DROP COLUMN IF EXISTS allow_orders;\nALTER TABLE public.workspaces DROP COLUMN IF EXISTS allow_suppliers;\n\n-- 3. Add new module boolean columns (all default true)\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS instant_pos boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS sales_history boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS travel_agency boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS loans boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS net_revenue boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS budget boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS monthly_comparison boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS team_performance boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS products boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS storages boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS inventory_transfer boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS hr boolean NOT NULL DEFAULT true;\nALTER TABLE public.workspaces ADD COLUMN IF NOT EXISTS members boolean NOT NULL DEFAULT true;\n"}	rename_and_add_module_columns	masteralan360@gmail.com	\N	\N
20260324174419	{"\n-- Update get_workspace_features (no param name issue here)\nCREATE OR REPLACE FUNCTION public.get_workspace_features()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_workspace_id UUID;\n    v_result JSONB;\nBEGIN\n    SELECT workspace_id INTO v_workspace_id\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RETURN jsonb_build_object(\n            'error', 'User does not belong to a workspace',\n            'pos', false,\n            'crm', true,\n            'invoices_history', false,\n            'is_configured', false,\n            'coordination', null,\n            'print_quality', 'low',\n            'kds_enabled', false\n        );\n    END IF;\n\n    SELECT jsonb_build_object(\n        'workspace_id', id,\n        'workspace_name', name,\n        'data_mode', COALESCE(data_mode, 'cloud'),\n        'pos', COALESCE(pos, false),\n        'instant_pos', COALESCE(instant_pos, true),\n        'sales_history', COALESCE(sales_history, true),\n        'crm', COALESCE(crm, true),\n        'travel_agency', COALESCE(travel_agency, true),\n        'loans', COALESCE(loans, true),\n        'net_revenue', COALESCE(net_revenue, true),\n        'budget', COALESCE(budget, true),\n        'monthly_comparison', COALESCE(monthly_comparison, true),\n        'team_performance', COALESCE(team_performance, true),\n        'products', COALESCE(products, true),\n        'storages', COALESCE(storages, true),\n        'inventory_transfer', COALESCE(inventory_transfer, true),\n        'invoices_history', COALESCE(invoices_history, false),\n        'hr', COALESCE(hr, true),\n        'members', COALESCE(members, true),\n        'is_configured', COALESCE(is_configured, false),\n        'default_currency', COALESCE(default_currency, 'usd'),\n        'iqd_display_preference', COALESCE(iqd_display_preference, 'IQD'),\n        'eur_conversion_enabled', COALESCE(eur_conversion_enabled, false),\n        'try_conversion_enabled', COALESCE(try_conversion_enabled, false),\n        'locked_workspace', COALESCE(locked_workspace, false),\n        'logo_url', logo_url,\n        'coordination', coordination,\n        'max_discount_percent', COALESCE(max_discount_percent, 100),\n        'allow_whatsapp', COALESCE(allow_whatsapp, false),\n        'kds_enabled', COALESCE(kds_enabled, false),\n        'print_lang', COALESCE(print_lang, 'auto'),\n        'print_qr', COALESCE(print_qr, false),\n        'receipt_template', COALESCE(receipt_template, 'primary'),\n        'a4_template', COALESCE(a4_template, 'primary'),\n        'print_quality', COALESCE(print_quality, 'low'),\n        'subscription_expires_at', subscription_expires_at\n    ) INTO v_result\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    RETURN v_result;\nEND;\n$function$;\n\n-- Drop old configure_workspace (param names changed)\nDROP FUNCTION IF EXISTS public.configure_workspace(text, boolean, boolean, boolean, text);\n\n-- Recreate configure_workspace with new param names\nCREATE OR REPLACE FUNCTION public.configure_workspace(\n    p_data_mode text DEFAULT 'cloud',\n    p_pos boolean DEFAULT false,\n    p_crm boolean DEFAULT true,\n    p_invoices_history boolean DEFAULT false,\n    p_logo_url text DEFAULT NULL\n)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    v_workspace_id UUID;\n    v_user_role TEXT;\n    v_is_configured BOOLEAN;\n    normalized_mode TEXT;\nBEGIN\n    SELECT workspace_id, role INTO v_workspace_id, v_user_role\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'User does not belong to a workspace';\n    END IF;\n\n    IF v_user_role != 'admin' THEN\n        RAISE EXCEPTION 'Unauthorized: Only admins can configure workspace features';\n    END IF;\n\n    SELECT COALESCE(is_configured, false)\n    INTO v_is_configured\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    IF v_is_configured THEN\n        RAISE EXCEPTION 'Workspace has already been configured. Mode changes are not allowed.';\n    END IF;\n\n    normalized_mode := lower(COALESCE(p_data_mode, 'cloud'));\n\n    IF normalized_mode NOT IN ('cloud', 'local') THEN\n        RAISE EXCEPTION 'Invalid workspace mode: %', p_data_mode;\n    END IF;\n\n    UPDATE public.workspaces\n    SET\n        data_mode = normalized_mode,\n        pos = p_pos,\n        crm = p_crm,\n        invoices_history = p_invoices_history,\n        logo_url = p_logo_url,\n        is_configured = true\n    WHERE id = v_workspace_id;\n\n    RETURN jsonb_build_object(\n        'success', true,\n        'data_mode', normalized_mode,\n        'pos', p_pos,\n        'crm', p_crm,\n        'invoices_history', p_invoices_history,\n        'logo_url', p_logo_url\n    );\nEND;\n$function$;\n"}	update_workspace_rpc_functions_v2	masteralan360@gmail.com	\N	\N
20260324222833	{"\nALTER TABLE crm.travel_agency_sales\n  ADD COLUMN IF NOT EXISTS snapshot_revenue numeric NULL,\n  ADD COLUMN IF NOT EXISTS snapshot_cost numeric NULL,\n  ADD COLUMN IF NOT EXISTS snapshot_profit numeric NULL,\n  ADD COLUMN IF NOT EXISTS exchange_rate_snapshot jsonb NULL;\n"}	add_travel_sale_snapshot_fields	masteralan360@gmail.com	\N	\N
20260325004412	{"ALTER TYPE workspace_data_mode ADD VALUE IF NOT EXISTS 'hybrid';"}	add_hybrid_to_workspace_data_mode	masteralan360@gmail.com	\N	\N
20260325005342	{"CREATE OR REPLACE FUNCTION switch_workspace_data_mode(p_new_mode workspace_data_mode)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $$\nDECLARE\n    v_workspace_id uuid;\n    v_current_mode workspace_data_mode;\nBEGIN\n    -- Get caller's workspace\n    v_workspace_id := (auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid;\n    IF v_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'No workspace found for current user';\n    END IF;\n\n    -- Get current mode\n    SELECT data_mode INTO v_current_mode\n    FROM workspaces\n    WHERE id = v_workspace_id;\n\n    IF v_current_mode IS NULL THEN\n        RAISE EXCEPTION 'Workspace not found';\n    END IF;\n\n    -- Only allow cloud <-> hybrid switching\n    IF v_current_mode = 'local' OR p_new_mode = 'local' THEN\n        RAISE EXCEPTION 'Cannot switch to or from local mode. Only cloud <-> hybrid switching is allowed.';\n    END IF;\n\n    -- No-op if same mode\n    IF v_current_mode = p_new_mode THEN\n        RETURN;\n    END IF;\n\n    -- Perform the switch\n    UPDATE workspaces\n    SET data_mode = p_new_mode\n    WHERE id = v_workspace_id;\nEND;\n$$;"}	create_switch_workspace_data_mode_rpc	masteralan360@gmail.com	\N	\N
20260325005818	{"CREATE OR REPLACE FUNCTION public.prevent_workspace_mode_switch()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF NEW.data_mode IS DISTINCT FROM OLD.data_mode AND COALESCE(OLD.is_configured, false) THEN\n    -- Allow switching between cloud and hybrid\n    IF (OLD.data_mode IN ('cloud', 'hybrid') AND NEW.data_mode IN ('cloud', 'hybrid')) THEN\n      RETURN NEW;\n    END IF;\n    RAISE EXCEPTION 'Workspace mode cannot be changed after initial configuration (only cloud <-> hybrid switching is allowed)';\n  END IF;\n  RETURN NEW;\nEND;\n$function$;"}	allow_cloud_hybrid_mode_switch	masteralan360@gmail.com	\N	\N
20260325153243	{"\n-- Drop both overloaded versions and recreate with hybrid support\n-- Overload 1: legacy (p_data_mode, p_allow_pos, p_allow_invoices, p_logo_url)\nDROP FUNCTION IF EXISTS public.configure_workspace(text, boolean, boolean, text);\n\n-- Overload 2: current (p_data_mode, p_pos, p_crm, p_invoices_history, p_logo_url)\nCREATE OR REPLACE FUNCTION public.configure_workspace(\n    p_data_mode text DEFAULT 'cloud'::text,\n    p_pos boolean DEFAULT false,\n    p_crm boolean DEFAULT true,\n    p_invoices_history boolean DEFAULT false,\n    p_logo_url text DEFAULT NULL::text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nAS $function$\nDECLARE\n    v_workspace_id UUID;\n    v_user_role TEXT;\n    v_is_configured BOOLEAN;\n    normalized_mode TEXT;\nBEGIN\n    SELECT workspace_id, role INTO v_workspace_id, v_user_role\n    FROM public.profiles\n    WHERE id = auth.uid();\n\n    IF v_workspace_id IS NULL THEN\n        RAISE EXCEPTION 'User does not belong to a workspace';\n    END IF;\n\n    IF v_user_role != 'admin' THEN\n        RAISE EXCEPTION 'Unauthorized: Only admins can configure workspace features';\n    END IF;\n\n    SELECT COALESCE(is_configured, false)\n    INTO v_is_configured\n    FROM public.workspaces\n    WHERE id = v_workspace_id;\n\n    IF v_is_configured THEN\n        RAISE EXCEPTION 'Workspace has already been configured. Mode changes are not allowed.';\n    END IF;\n\n    normalized_mode := lower(COALESCE(p_data_mode, 'cloud'));\n\n    IF normalized_mode NOT IN ('cloud', 'local', 'hybrid') THEN\n        RAISE EXCEPTION 'Invalid workspace mode: %', p_data_mode;\n    END IF;\n\n    UPDATE public.workspaces\n    SET\n        data_mode = normalized_mode::workspace_data_mode,\n        pos = p_pos,\n        crm = p_crm,\n        invoices_history = p_invoices_history,\n        logo_url = p_logo_url,\n        is_configured = true\n    WHERE id = v_workspace_id;\n\n    RETURN jsonb_build_object(\n        'success', true,\n        'data_mode', normalized_mode,\n        'pos', p_pos,\n        'crm', p_crm,\n        'invoices_history', p_invoices_history,\n        'logo_url', p_logo_url\n    );\nEND;\n$function$;\n"}	fix_configure_workspace_allow_hybrid	masteralan360@gmail.com	\N	\N
20260522224049	{"ALTER TABLE public.workspaces \nDROP COLUMN IF EXISTS pos,\nDROP COLUMN IF EXISTS instant_pos,\nDROP COLUMN IF EXISTS sales_history,\nDROP COLUMN IF EXISTS crm,\nDROP COLUMN IF EXISTS ecommerce,\nDROP COLUMN IF EXISTS travel_agency,\nDROP COLUMN IF EXISTS real_estate,\nDROP COLUMN IF EXISTS loans,\nDROP COLUMN IF EXISTS net_revenue,\nDROP COLUMN IF EXISTS budget,\nDROP COLUMN IF EXISTS monthly_comparison,\nDROP COLUMN IF EXISTS team_performance,\nDROP COLUMN IF EXISTS products,\nDROP COLUMN IF EXISTS discounts,\nDROP COLUMN IF EXISTS storages,\nDROP COLUMN IF EXISTS inventory_transfer,\nDROP COLUMN IF EXISTS stock_adjustments,\nDROP COLUMN IF EXISTS invoices_history,\nDROP COLUMN IF EXISTS hr,\nDROP COLUMN IF EXISTS members;\n"}	remove_module_feature_flags_v2	masteralan360@gmail.com	\N	\N
20260523122335	{"-- Restore missing module feature flags to public.workspaces\nALTER TABLE public.workspaces\n  ADD COLUMN IF NOT EXISTS pos boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS instant_pos boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS sales_history boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS crm boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS ecommerce boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS travel_agency boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS real_estate boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS loans boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS net_revenue boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS budget boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS monthly_comparison boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS team_performance boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS products boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS discounts boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS storages boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS inventory_transfer boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS stock_adjustments boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS invoices_history boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS hr boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS members boolean NOT NULL DEFAULT true;\n\n-- Security Fix: Enable RLS for marketplace_order_counters\nALTER TABLE public.marketplace_order_counters ENABLE ROW LEVEL SECURITY;\n\n-- Basic policies for marketplace_order_counters\nDROP POLICY IF EXISTS \\"Admin and Service Role can manage counters\\" ON public.marketplace_order_counters;\nCREATE POLICY \\"Admin and Service Role can manage counters\\"\n  ON public.marketplace_order_counters\n  FOR ALL\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM public.profiles\n      WHERE id = auth.uid() AND role = 'admin'\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM public.profiles\n      WHERE id = auth.uid() AND role = 'admin'\n    )\n  );\n\nDROP POLICY IF EXISTS \\"Authenticated can select counters\\" ON public.marketplace_order_counters;\nCREATE POLICY \\"Authenticated can select counters\\"\n  ON public.marketplace_order_counters\n  FOR SELECT\n  TO authenticated\n  USING (true);\n"}	restore_workspace_features	masteralan360@gmail.com	\N	\N
20260610223422	{"ALTER TABLE public.custom_templates \nADD COLUMN IF NOT EXISTS active BOOLEAN DEFAULT TRUE,\nADD COLUMN IF NOT EXISTS \\"primary\\" BOOLEAN DEFAULT FALSE;\n\n-- Ensure only one primary template can exist per workspace and module type\nDROP INDEX IF EXISTS idx_custom_templates_primary_unique;\nCREATE UNIQUE INDEX idx_custom_templates_primary_unique \nON public.custom_templates (workspace_id, module_type_key) \nWHERE (\\"primary\\" = TRUE);\n"}	add_active_and_primary_to_custom_templates	masteralan360@gmail.com	\N	\N
