--
-- Name: calculate_clinical_appointment_paid_amount("uuid"); Type: FUNCTION; Schema: clinics; Owner: -
--

CREATE FUNCTION "clinics"."calculate_clinical_appointment_paid_amount"("p_appointment_id" "uuid") RETURNS numeric
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'clinics'
    AS $$
  SELECT GREATEST(COALESCE(SUM(payment.amount), 0), 0)
  FROM public.payment_transactions AS payment
  WHERE payment.source_type = 'clinical_appointment'
    AND payment.source_record_id = p_appointment_id
    AND NOT payment.is_deleted;
$$;


--
-- Name: calculate_clinical_appointment_payment_status("uuid", numeric); Type: FUNCTION; Schema: clinics; Owner: -
--

CREATE FUNCTION "clinics"."calculate_clinical_appointment_payment_status"("p_appointment_id" "uuid", "p_service_fee" numeric) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'clinics'
    AS $$
DECLARE
  v_paid_amount numeric := 0;
BEGIN
  v_paid_amount := clinics.calculate_clinical_appointment_paid_amount(p_appointment_id);

  IF COALESCE(p_service_fee, 0) <= 0 THEN
    RETURN 'no_fee';
  ELSIF v_paid_amount >= p_service_fee THEN
    RETURN 'paid';
  ELSIF v_paid_amount > 0 THEN
    RETURN 'partial';
  END IF;

  RETURN 'unpaid';
END;
$$;


--
-- Name: refresh_clinical_appointment_payment_status_from_transaction(); Type: FUNCTION; Schema: clinics; Owner: -
--

CREATE FUNCTION "clinics"."refresh_clinical_appointment_payment_status_from_transaction"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'clinics'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT'
    AND OLD.source_type = 'clinical_appointment'
  THEN
    UPDATE clinics.clinical_appointments AS appointment
    SET paid_amount = clinics.calculate_clinical_appointment_paid_amount(appointment.id),
        payment_status = clinics.calculate_clinical_appointment_payment_status(
          appointment.id,
          appointment.consultation_fee
        )
    WHERE appointment.id = OLD.source_record_id;
  END IF;

  IF TG_OP <> 'DELETE'
    AND NEW.source_type = 'clinical_appointment'
  THEN
    UPDATE clinics.clinical_appointments AS appointment
    SET paid_amount = clinics.calculate_clinical_appointment_paid_amount(appointment.id),
        payment_status = clinics.calculate_clinical_appointment_payment_status(
          appointment.id,
          appointment.consultation_fee
        )
    WHERE appointment.id = NEW.source_record_id;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_clinical_appointment_payment_status(); Type: FUNCTION; Schema: clinics; Owner: -
--

CREATE FUNCTION "clinics"."set_clinical_appointment_payment_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'clinics'
    AS $$
BEGIN
  NEW.paid_amount := clinics.calculate_clinical_appointment_paid_amount(NEW.id);
  NEW.payment_status := clinics.calculate_clinical_appointment_payment_status(
    NEW.id,
    NEW.consultation_fee
  );
  RETURN NEW;
END;
$$;


--
-- Name: assign_sales_order_number(); Type: FUNCTION; Schema: crm; Owner: -
--

CREATE FUNCTION "crm"."assign_sales_order_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'crm'
    AS $_$
DECLARE
  v_year integer := EXTRACT(YEAR FROM COALESCE(NEW.created_at, timezone('utc', now())))::integer;
  v_next_sequence bigint := 0;
BEGIN
  IF NEW.workspace_id IS NULL THEN
    RAISE EXCEPTION 'Sales orders require a workspace';
  END IF;

  IF COALESCE(NULLIF(trim(COALESCE(NEW.order_number, '')), ''), '') <> '' THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(format('crm.sales_orders:%s:%s', NEW.workspace_id, v_year), 0));

  SELECT COALESCE(
    MAX(((regexp_match(order_number, format('^SO-%s-([0-9]+)$', v_year)))[1])::bigint),
    0
  ) + 1
  INTO v_next_sequence
  FROM crm.sales_orders
  WHERE workspace_id = NEW.workspace_id
    AND order_number ~ format('^SO-%s-[0-9]+$', v_year);

  NEW.order_number := format('SO-%s-%s', v_year, lpad(v_next_sequence::text, 5, '0'));
  RETURN NEW;
END;
$_$;


--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION "extensions"."grant_pg_cron_access"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


--
-- Name: FUNCTION "grant_pg_cron_access"(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION "extensions"."grant_pg_cron_access"() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION "extensions"."grant_pg_graphql_access"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


--
-- Name: FUNCTION "grant_pg_graphql_access"(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION "extensions"."grant_pg_graphql_access"() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION "extensions"."grant_pg_net_access"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$$;


--
-- Name: FUNCTION "grant_pg_net_access"(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION "extensions"."grant_pg_net_access"() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION "extensions"."pgrst_ddl_watch"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION "extensions"."pgrst_drop_watch"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION "extensions"."set_graphql_placeholder"() RETURNS "event_trigger"
    LANGUAGE "plpgsql"
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


--
-- Name: FUNCTION "set_graphql_placeholder"(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION "extensions"."set_graphql_placeholder"() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: close_inactive_agent_operations(); Type: FUNCTION; Schema: fleet; Owner: -
--

CREATE FUNCTION "fleet"."close_inactive_agent_operations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm', 'fleet'
    AS $$
BEGIN
  IF (
    NEW.status <> 'active'
    OR COALESCE(NEW.is_deleted, false) = true
    OR NEW.linked_user_id IS DISTINCT FROM OLD.linked_user_id
  ) THEN
    UPDATE fleet.live_locations
    SET
      is_sharing = false,
      received_at = now()
    WHERE agent_id = NEW.id
      AND is_sharing = true;

    UPDATE fleet.location_sessions
    SET
      status = 'stopped',
      ended_at = COALESCE(ended_at, now()),
      last_seen_at = COALESCE(last_seen_at, now()),
      updated_at = now()
    WHERE agent_id = NEW.id
      AND status = 'active';

    UPDATE fleet.fleet_vehicle_assignments
    SET
      status = 'ended',
      ended_at = COALESCE(ended_at, now()),
      updated_at = now(),
      version = version + 1
    WHERE agent_id = NEW.id
      AND status = 'active'
      AND COALESCE(is_deleted, false) = false;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_assignment_links(); Type: FUNCTION; Schema: fleet; Owner: -
--

CREATE FUNCTION "fleet"."enforce_assignment_links"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm', 'fleet'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM fleet.fleet_vehicles vehicle
    WHERE vehicle.id = NEW.vehicle_id
      AND vehicle.workspace_id = NEW.workspace_id
      AND COALESCE(vehicle.is_deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'Fleet vehicle must belong to the assignment workspace'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM crm.agents agent
    WHERE agent.id = NEW.agent_id
      AND agent.workspace_id = NEW.workspace_id
      AND COALESCE(agent.is_deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'Agent must belong to the assignment workspace'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_location_owner(); Type: FUNCTION; Schema: fleet; Owner: -
--

CREATE FUNCTION "fleet"."enforce_location_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm', 'fleet'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'live_locations'
    AND pg_trigger_depth() > 1
    AND NEW.is_sharing = false
  THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id <> auth.uid()
    OR NOT fleet.is_linked_agent(NEW.workspace_id, NEW.agent_id)
  THEN
    RAISE EXCEPTION 'Location updates must belong to the authenticated linked agent'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM fleet.location_sessions session
    WHERE session.id = NEW.session_id
      AND session.workspace_id = NEW.workspace_id
      AND session.agent_id = NEW.agent_id
      AND session.user_id = NEW.user_id
      AND session.status = 'active'
  ) THEN
    RAISE EXCEPTION 'Location session is not active'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: is_linked_agent("uuid", "uuid"); Type: FUNCTION; Schema: fleet; Owner: -
--

CREATE FUNCTION "fleet"."is_linked_agent"("p_workspace_id" "uuid", "p_agent_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'crm'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM crm.agents agent
    WHERE agent.id = p_agent_id
      AND agent.workspace_id = p_workspace_id
      AND agent.linked_user_id = auth.uid()
      AND agent.status = 'active'
      AND COALESCE(agent.is_deleted, false) = false
      AND public.workspace_module_allowed(
        agent.workspace_id,
        (SELECT w.plan::text FROM public.workspaces w WHERE w.id = agent.workspace_id),
        'agents'
      )
  );
$$;


--
-- Name: workspace_permission_allowed("uuid", "text"); Type: FUNCTION; Schema: fleet; Owner: -
--

CREATE FUNCTION "fleet"."workspace_permission_allowed"("p_workspace_id" "uuid", "p_permission_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    public.workspace_module_allowed(
      p_workspace_id,
      (SELECT w.plan::text FROM public.workspaces w WHERE w.id = p_workspace_id),
      'agents'
    )
    AND (
      public.current_user_role() = 'admin'
      OR NOT public.workspace_capability_allowed(
        p_workspace_id,
        (SELECT w.plan::text FROM public.workspaces w WHERE w.id = p_workspace_id),
        'workspaceManagementPermissions'
      )
      OR EXISTS (
        SELECT 1
        FROM public.workspace_permissions permission
        WHERE permission.workspace_id = p_workspace_id
          AND permission.user_uuid = auth.uid()
          AND permission.key = p_permission_key
      )
    );
$$;


--
-- Name: enforce_exchange_currency_access(); Type: FUNCTION; Schema: fx; Owner: -
--

CREATE FUNCTION "fx"."enforce_exchange_currency_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'fx'
    AS $$
DECLARE
  v_workspace_id uuid;
  v_plan text;
  v_currency text;
BEGIN
  v_workspace_id := nullif(to_jsonb(NEW)->>'workspace_id', '')::uuid;

  IF v_workspace_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT plan INTO v_plan
  FROM public.workspaces
  WHERE id = v_workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NULL THEN
    RETURN NEW;
  END IF;

  FOREACH v_currency IN ARRAY ARRAY[
    lower(nullif(to_jsonb(NEW)->>'from_currency', '')),
    lower(nullif(to_jsonb(NEW)->>'to_currency', '')),
    lower(nullif(coalesce(to_jsonb(NEW)->>'fee_currency', to_jsonb(NEW)->>'currency'), ''))
  ]
  LOOP
    IF v_currency IS NOT NULL AND NOT public.workspace_currency_allowed(v_workspace_id, v_plan, v_currency) THEN
      RAISE EXCEPTION 'Currency % is not included in the current workspace plan', v_currency
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_exchange_fee_rule_lock_admin(); Type: FUNCTION; Schema: fx; Owner: -
--

CREATE FUNCTION "fx"."enforce_exchange_fee_rule_lock_admin"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'fx'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.is_locked IS TRUE AND public.current_user_role() <> 'admin' THEN
      RAISE EXCEPTION 'Only workspace admins can create locked currency exchange fee rules'
        USING ERRCODE = '42501';
    END IF;
  ELSIF OLD.is_locked IS DISTINCT FROM NEW.is_locked AND public.current_user_role() <> 'admin' THEN
    RAISE EXCEPTION 'Only workspace admins can lock or unlock currency exchange fee rules'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_safe_admin_movements(); Type: FUNCTION; Schema: fx; Owner: -
--

CREATE FUNCTION "fx"."enforce_safe_admin_movements"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'fx'
    AS $$
BEGIN
  IF NEW.movement_type IN ('opening_balance', 'adjustment')
     AND public.current_user_role() <> 'admin' THEN
    RAISE EXCEPTION 'Only workspace admins can create opening balance or adjustment safe movements'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: graphql("text", "text", "jsonb", "jsonb"); Type: FUNCTION; Schema: graphql_public; Owner: -
--

CREATE FUNCTION "graphql_public"."graphql"("operationName" "text" DEFAULT NULL::"text", "query" "text" DEFAULT NULL::"text", "variables" "jsonb" DEFAULT NULL::"jsonb", "extensions" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;


--
-- Name: compute_due_date("text", integer); Type: FUNCTION; Schema: notifications; Owner: -
--

CREATE FUNCTION "notifications"."compute_due_date"("month_key" "text", "payday" integer) RETURNS "date"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    year_part INTEGER;
    month_part INTEGER;
    day_part INTEGER;
    days_in_month INTEGER;
BEGIN
    year_part := NULLIF(split_part(month_key, '-', 1), '')::INTEGER;
    month_part := NULLIF(split_part(month_key, '-', 2), '')::INTEGER;

    IF year_part IS NULL OR month_part IS NULL OR month_part < 1 OR month_part > 12 THEN
        RETURN NULL;
    END IF;

    days_in_month := EXTRACT(DAY FROM (date_trunc('month', make_date(year_part, month_part, 1)) + INTERVAL '1 month - 1 day'));
    day_part := LEAST(GREATEST(COALESCE(payday, 30), 1), days_in_month);

    RETURN make_date(year_part, month_part, day_part);
END;
$$;


--
-- Name: get_auth("text"); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION "pgbouncer"."get_auth"("p_usename" "text") RETURNS TABLE("username" "text", "password" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


--
-- Name: acknowledge_p2p_sync("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acknowledge_p2p_sync"("p_queue_id" "uuid", "p_session_id" "uuid") RETURNS TABLE("is_complete" boolean, "storage_path" "text", "file_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_workspace_id uuid;
  v_session_count int;
  v_current_synced jsonb;
  v_storage_path text;
  v_file_name text;
begin
  -- 1. Get current item details
  select sq.workspace_id, sq.storage_path, sq.file_name, sq.synced_by
  into v_workspace_id, v_storage_path, v_file_name, v_current_synced
  from sync_queue sq
  where sq.id = p_queue_id;

  if v_workspace_id is null then
    return;
  end if;

  -- 2. Update if not present (track by session_id)
  if not (v_current_synced @> to_jsonb(p_session_id::text)) then
    update sync_queue sq
    set synced_by = coalesce(sq.synced_by, '[]'::jsonb) || to_jsonb(p_session_id::text)
    where sq.id = p_queue_id
    returning sq.synced_by into v_current_synced;
  end if;

  -- 3. Get Workspace Total Session Count
  -- Join auth.sessions with profiles table to target direct workspace
  select count(s.id) into v_session_count
  from auth.sessions s
  join public.profiles p on s.user_id = p.id
  where p.current_workspace = v_workspace_id;

  -- 4. Check completion
  if jsonb_array_length(v_current_synced) >= v_session_count then
    return query select true, v_storage_path, v_file_name;
  else
    return query select false, v_storage_path, v_file_name;
  end if;
end;
$$;


--
-- Name: activate_financed_order("text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."activate_financed_order"("p_order_type" "text", "p_order_id" "uuid", "p_target_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm', 'pg_temp'
    AS $$
DECLARE
  v_sales crm.sales_orders%ROWTYPE;
  v_purchase crm.purchase_orders%ROWTYPE;
  v_workspace_id uuid := public.current_workspace_id();
  v_loan_id uuid;
BEGIN
  IF v_workspace_id IS NULL THEN RAISE EXCEPTION 'workspace_required'; END IF;

  IF p_order_type = 'sales' THEN
    SELECT * INTO v_sales FROM crm.sales_orders
    WHERE id = p_order_id AND workspace_id = v_workspace_id AND is_deleted = false
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
    IF v_sales.status <> 'draft' OR p_target_status <> 'pending' THEN RAISE EXCEPTION 'invalid_order_transition'; END IF;

    IF v_sales.payment_method IN ('loan', 'installments') THEN
      v_loan_id := public.create_order_financing_loan(
        v_sales.workspace_id, 'sales', v_sales.id, v_sales.order_number,
        COALESCE(v_sales.business_partner_id, v_sales.customer_id), COALESCE(v_sales.customer_name, 'Customer'),
        v_sales.payment_method, v_sales.balance_amount, v_sales.currency, v_sales.exchange_rates,
        v_sales.installment_count, v_sales.installment_frequency, v_sales.first_due_date, v_sales.created_by
      );
    ELSIF NOT COALESCE(v_sales.is_paid, false) THEN
      RAISE EXCEPTION 'non_financed_order_must_be_paid';
    END IF;

    UPDATE crm.sales_orders
    SET status = 'pending', linked_loan_id = v_loan_id, updated_at = now(), version = version + 1
    WHERE id = p_order_id;
  ELSIF p_order_type = 'purchase' THEN
    SELECT * INTO v_purchase FROM crm.purchase_orders
    WHERE id = p_order_id AND workspace_id = v_workspace_id AND is_deleted = false
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
    IF v_purchase.status <> 'draft' OR p_target_status <> 'ordered' THEN RAISE EXCEPTION 'invalid_order_transition'; END IF;

    IF v_purchase.payment_method IN ('loan', 'installments') THEN
      v_loan_id := public.create_order_financing_loan(
        v_purchase.workspace_id, 'purchase', v_purchase.id, v_purchase.order_number,
        COALESCE(v_purchase.business_partner_id, v_purchase.supplier_id), COALESCE(v_purchase.supplier_name, 'Supplier'),
        v_purchase.payment_method, v_purchase.balance_amount, v_purchase.currency, v_purchase.exchange_rates,
        v_purchase.installment_count, v_purchase.installment_frequency, v_purchase.first_due_date, v_purchase.created_by
      );
    ELSIF NOT COALESCE(v_purchase.is_paid, false) THEN
      RAISE EXCEPTION 'non_financed_order_must_be_paid';
    END IF;

    UPDATE crm.purchase_orders
    SET status = 'ordered', linked_loan_id = v_loan_id, updated_at = now(), version = version + 1
    WHERE id = p_order_id;
  ELSE
    RAISE EXCEPTION 'invalid_order_type';
  END IF;

  RETURN jsonb_build_object('order_id', p_order_id, 'order_type', p_order_type, 'status', p_target_status, 'loan_id', v_loan_id);
END;
$$;


--
-- Name: admin_update_workspace_features("text", "uuid", boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_update_workspace_features"("provided_key" "text", "target_workspace_id" "uuid", "new_allow_pos" boolean, "new_allow_invoices" boolean, "new_locked_workspace" boolean DEFAULT NULL::boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Verify admin passkey
    IF NOT public.verify_admin_passkey(provided_key) THEN
        RAISE EXCEPTION 'Invalid admin passkey';
    END IF;

    UPDATE public.workspaces
    SET 
        allow_pos = new_allow_pos,
        allow_invoices = new_allow_invoices,
        locked_workspace = COALESCE(new_locked_workspace, locked_workspace)
    WHERE id = target_workspace_id;

    RETURN true;
END;
$$;


--
-- Name: apply_sale_item_batch_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_sale_item_batch_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_allocation_count integer := 0;
  v_cost_count integer := 0;
  v_allocated_quantity numeric := 0;
  v_total_cost numeric := 0;
  v_distinct_currency_count integer := 0;
  v_allocation_currency text := NULL;
  v_previous_cost numeric := 0;
  v_conversion_factor numeric := 1;
BEGIN
  IF jsonb_typeof(NEW.batch_allocations) <> 'array'
    OR jsonb_array_length(NEW.batch_allocations) = 0 THEN
    RETURN NEW;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE allocation->>'cost_price' IS NOT NULL),
    COALESCE(SUM((allocation->>'quantity')::numeric), 0),
    COALESCE(SUM(
      (allocation->>'quantity')::numeric
      * (allocation->>'cost_price')::numeric
    ) FILTER (WHERE allocation->>'cost_price' IS NOT NULL), 0),
    COUNT(DISTINCT lower(NULLIF(allocation->>'currency', ''))),
    MIN(lower(NULLIF(allocation->>'currency', '')))
  INTO
    v_allocation_count,
    v_cost_count,
    v_allocated_quantity,
    v_total_cost,
    v_distinct_currency_count,
    v_allocation_currency
  FROM jsonb_array_elements(NEW.batch_allocations) AS allocation
  WHERE COALESCE((allocation->>'quantity')::numeric, 0) > 0;

  IF v_allocation_count = 0
    OR v_cost_count <> v_allocation_count
    OR v_allocated_quantity <= 0
    OR v_allocated_quantity <> NEW.quantity
    OR v_distinct_currency_count > 1
    OR (
      v_allocation_currency IS NOT NULL
      AND v_allocation_currency <> lower(COALESCE(NEW.original_currency, v_allocation_currency))
    ) THEN
    RETURN NEW;
  END IF;

  v_previous_cost := COALESCE(NEW.cost_price, 0);
  IF v_previous_cost > 0 THEN
    v_conversion_factor := COALESCE(NEW.converted_cost_price, v_previous_cost) / v_previous_cost;
  ELSIF lower(COALESCE(NEW.original_currency, '')) = lower(COALESCE(NEW.settlement_currency, '')) THEN
    v_conversion_factor := 1;
  ELSE
    RETURN NEW;
  END IF;

  NEW.cost_price := v_total_cost / v_allocated_quantity;
  NEW.converted_cost_price := NEW.cost_price * v_conversion_factor;
  RETURN NEW;
END;
$$;


--
-- Name: apply_stock_batch_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_stock_batch_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_product_price numeric := 0;
  v_product_cost_price numeric := 0;
  v_product_currency text := 'usd';
BEGIN
  SELECT
    COALESCE(price, 0),
    COALESCE(cost_price, 0),
    lower(COALESCE(currency, 'usd'))
  INTO
    v_product_price,
    v_product_cost_price,
    v_product_currency
  FROM public.products
  WHERE id = NEW.product_id
    AND workspace_id = NEW.workspace_id
  LIMIT 1;

  NEW.price := COALESCE(NEW.price, v_product_price, 0);
  NEW.cost_price := COALESCE(NEW.cost_price, v_product_cost_price, 0);
  NEW.currency := lower(COALESCE(NULLIF(NEW.currency, ''), v_product_currency, 'usd'));

  RETURN NEW;
END;
$$;


--
-- Name: apply_workspace_plan_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_workspace_plan_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_member_count integer;
  v_branch_count integer;
  v_contact_count integer;
  v_max_contacts integer;
BEGIN
  NEW.plan := public.normalize_workspace_plan(NEW.plan);

  IF TG_OP = 'UPDATE' AND NEW.plan::text IS DISTINCT FROM OLD.plan::text THEN
    SELECT count(*) INTO v_member_count
    FROM public.profiles
    WHERE workspace_id = NEW.id;

    IF v_member_count > public.workspace_max_members(NEW.id, NEW.plan) THEN
      RAISE EXCEPTION 'Workspace member count exceeds the % plan limit', NEW.plan
        USING ERRCODE = '42501';
    END IF;

    SELECT count(*) INTO v_branch_count
    FROM public.workspace_branches
    WHERE source_workspace_id = NEW.id
      AND archived_at IS NULL;

    IF v_branch_count > public.workspace_max_branches(NEW.id, NEW.plan) THEN
      RAISE EXCEPTION 'Workspace branch count exceeds the % plan limit', NEW.plan
        USING ERRCODE = '42501';
    END IF;

    v_max_contacts := public.workspace_max_contacts(NEW.id, NEW.plan);
    IF v_max_contacts IS NOT NULL THEN
      SELECT count(*) INTO v_contact_count
      FROM public.workspace_contacts
      WHERE workspace_id = NEW.id;

      IF v_contact_count > v_max_contacts THEN
        RAISE EXCEPTION 'Workspace contact count exceeds the % plan limit', NEW.plan
          USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  NEW.instant_pos := COALESCE(NEW.instant_pos, true);

  IF TG_OP = 'INSERT' OR NEW.plan::text IS DISTINCT FROM OLD.plan::text THEN
    NEW.travel_agency := public.workspace_module_allowed(NEW.id, NEW.plan::text, 'travel_agency');
    NEW.real_estate := public.workspace_module_allowed(NEW.id, NEW.plan::text, 'real_estate');
    NEW.allow_whatsapp := public.workspace_capability_allowed(NEW.id, NEW.plan::text, 'whatsappIntegration');
    NEW.upload_limit_mb := CASE
      WHEN public.workspace_has_override(NEW.id, 'limit', 'maxUploadSizeMb')
        THEN public.workspace_get_override_value(NEW.id, 'limit', 'maxUploadSizeMb')::integer
      ELSE CASE public.normalize_workspace_plan(NEW.plan::text)
        WHEN 'enterprise' THEN 1024
        WHEN 'business' THEN 100
        ELSE NULL
      END
    END;
  END IF;

  IF NOT public.workspace_currency_allowed(NEW.id, NEW.plan::text, NEW.default_currency::text) THEN
    NEW.default_currency := 'iqd';
  END IF;

  NEW.kds_enabled := public.workspace_capability_allowed(NEW.id, NEW.plan::text, 'kds')
    AND COALESCE(NEW.instant_pos, true)
    AND COALESCE(NEW.kds_enabled, true);

  IF NOT public.workspace_capability_allowed(NEW.id, NEW.plan::text, 'marketplaceStorefronts') THEN
    NEW.visibility := 'private';
    NEW.store_slug := NULL;
    NEW.store_description := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: archive_branch("uuid", "uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."archive_branch"("p_source_workspace_id" "uuid", "p_branch_workspace_id" "uuid", "p_archived_by" "uuid" DEFAULT NULL::"uuid", "p_archive_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_branch_record public.workspace_branches%ROWTYPE;
  v_affected_profiles integer;
  v_returned_to_source integer;
  v_removed_from_workspace integer;
BEGIN
  PERFORM 1
  FROM public.workspaces
  WHERE id = p_source_workspace_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Source workspace not found';
  END IF;

  SELECT *
  INTO v_branch_record
  FROM public.workspace_branches
  WHERE source_workspace_id = p_source_workspace_id
    AND branch_workspace_id = p_branch_workspace_id
    AND archived_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active branch relationship not found for source % and branch %',
      p_source_workspace_id,
      p_branch_workspace_id;
  END IF;

  SELECT count(*)
  INTO v_affected_profiles
  FROM public.profiles
  WHERE workspace_id = p_branch_workspace_id
    OR current_workspace = p_branch_workspace_id;

  SELECT count(*)
  INTO v_returned_to_source
  FROM public.profiles
  WHERE workspace_id IS DISTINCT FROM p_branch_workspace_id
    AND current_workspace = p_branch_workspace_id;

  SELECT count(*)
  INTO v_removed_from_workspace
  FROM public.profiles
  WHERE workspace_id = p_branch_workspace_id;

  UPDATE public.profiles
  SET current_workspace = p_source_workspace_id
  WHERE workspace_id IS DISTINCT FROM p_branch_workspace_id
    AND current_workspace = p_branch_workspace_id;

  UPDATE public.profiles
  SET workspace_id = NULL,
      current_workspace = NULL
  WHERE workspace_id = p_branch_workspace_id;

  UPDATE public.workspace_branches
  SET archived_at = now(),
      archived_by = p_archived_by,
      archive_reason = NULLIF(btrim(p_archive_reason), '')
  WHERE id = v_branch_record.id;

  UPDATE public.workspaces
  SET deleted_at = COALESCE(deleted_at, now()),
      visibility = 'private',
      store_slug = NULL
  WHERE id = p_branch_workspace_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Branch workspace not found';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'source_workspace_id', p_source_workspace_id,
    'branch_workspace_id', p_branch_workspace_id,
    'moved_users', v_affected_profiles,
    'returned_to_source', v_returned_to_source,
    'removed_from_workspace', v_removed_from_workspace
  );
END;
$$;


--
-- Name: assign_marketplace_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assign_marketplace_order_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_next_sequence bigint;
BEGIN
  IF NEW.workspace_id IS NULL THEN
    RAISE EXCEPTION 'Marketplace orders require a workspace';
  END IF;

  IF NEW.order_sequence IS NULL OR NEW.order_sequence <= 0 THEN
    VALUES (NEW.workspace_id, 1, timezone('utc', now()))
    ON CONFLICT (workspace_id)
    DO UPDATE SET
      last_sequence = counters.last_sequence + 1,
      updated_at = timezone('utc', now())
    RETURNING last_sequence INTO v_next_sequence;

    NEW.order_sequence := v_next_sequence;
  END IF;

  IF COALESCE(NULLIF(trim(COALESCE(NEW.order_number, '')), ''), '') = '' THEN
    NEW.order_number := format('MKT-%s', lpad(NEW.order_sequence::text, 5, '0'));
  END IF;

  NEW.request_ip_hash := COALESCE(NEW.request_ip_hash, '');
  RETURN NEW;
END;
$$;


