--
-- Name: check_demo_expired("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_demo_expired"("p_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_demo public.demos%ROWTYPE;
BEGIN
    SELECT * INTO v_demo
    FROM public.demos
    WHERE workspace_id = p_workspace_id;

