--
-- Name: check_registration_passkey(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_registration_passkey"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    provided_key text;
    requested_role text;
    valid_key text;
    configured_key_count integer;
BEGIN
    provided_key := NULLIF(btrim(COALESCE(NEW.raw_user_meta_data->>'passkey', '')), '');
    requested_role := NULLIF(btrim(COALESCE(NEW.raw_user_meta_data->>'role', '')), '');

    IF requested_role IS NULL THEN
        RAISE EXCEPTION 'Role is required for registration. Meta: %', NEW.raw_user_meta_data;
    END IF;

    IF requested_role NOT IN ('admin', 'staff', 'viewer') THEN
        RAISE EXCEPTION 'Invalid role requested: %. Meta: %', requested_role, NEW.raw_user_meta_data;
    END IF;

    IF provided_key IS NULL THEN
        RAISE EXCEPTION 'Registration passkey is required.';
    END IF;

    PERFORM 1
    FROM public.keys
    WHERE key_name IN ('admin', 'staff', 'viewer')
    ORDER BY key_name
    FOR UPDATE;

    SELECT count(*)
    INTO configured_key_count
    FROM public.keys
    WHERE key_name IN ('admin', 'staff', 'viewer');

    IF configured_key_count <> 3 THEN
        RAISE EXCEPTION 'Registration keys are not fully configured. Expected 3 active keys, found %.', configured_key_count;
    END IF;

    SELECT key_value
    INTO valid_key
    FROM public.keys
    WHERE key_name = requested_role;

    IF valid_key IS NULL OR provided_key <> valid_key THEN
        RAISE EXCEPTION 'Invalid passkey provided for role: %.', requested_role;
    END IF;

    PERFORM public.rotate_registration_keys();

    NEW.raw_user_meta_data = COALESCE(NEW.raw_user_meta_data, '{}'::jsonb) - 'passkey';

    RETURN NEW;
END;
$$;


--
-- Name: check_return_permissions("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_return_permissions"("p_sale_id" "uuid", "p_user_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        s.workspace_id,
        pr.role
    FROM public.sales s
    JOIN public.profiles pr ON pr.id = p_user_id AND pr.current_workspace = s.workspace_id
    WHERE s.id = p_sale_id;
END;
$$;


--
-- Name: check_store_slug_available("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_store_slug_available"("p_slug" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_slug text := NULLIF(lower(trim(COALESCE(p_slug, ''))), '');
BEGIN
  IF v_slug IS NULL THEN
    RETURN false;
  END IF;

  IF v_slug !~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$' THEN
    RETURN false;
  END IF;

  RETURN NOT EXISTS (
    SELECT 1
    FROM public.workspaces
    WHERE deleted_at IS NULL
      AND lower(store_slug) = v_slug
      AND id IS DISTINCT FROM public.current_workspace_id()
  );
END;
$_$;


--
-- Name: cleanup_expired_demos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_expired_demos"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_workspace record;
  v_user_ids uuid[];
  v_user_id uuid;
  v_cleaned int := 0;
BEGIN
  FOR v_workspace IN
    SELECT id FROM public.workspaces
    WHERE code LIKE 'demo.%'
      AND subscription_expires_at < now()
      AND deleted_at IS NULL
  LOOP
    SELECT array_agg(id) INTO v_user_ids
    FROM public.profiles
    WHERE workspace_id = v_workspace.id;

    PERFORM public.delete_demo_cascade(v_workspace.id);

    IF v_user_ids IS NOT NULL THEN
      FOREACH v_user_id IN ARRAY v_user_ids LOOP
        DELETE FROM auth.users WHERE id = v_user_id;
      END LOOP;
    END IF;

    v_cleaned := v_cleaned + 1;
  END LOOP;

  RETURN v_cleaned;
END;
$$;


--
-- Name: cleanup_workspace_permissions_on_profile_workspace_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_workspace_permissions_on_profile_workspace_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.workspace_id IS DISTINCT FROM NEW.workspace_id THEN
    DELETE FROM public.workspace_permissions
    WHERE user_uuid = NEW.id
      AND workspace_id IS DISTINCT FROM NEW.workspace_id;
  END IF;

  IF OLD.role IS DISTINCT FROM NEW.role AND NEW.role = 'admin' THEN
    DELETE FROM public.workspace_permissions
    WHERE user_uuid = NEW.id
      AND workspace_id = NEW.workspace_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: complete_sale("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."complete_sale"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    new_sale_id UUID;
    v_sequence_id BIGINT;
    item JSONB;
    snapshot JSONB;
    v_batch_record RECORD;
    p_workspace_id UUID;
    total_sale_amount NUMERIC := 0;
    v_pos BOOLEAN;
    v_max_discount_percent INTEGER := 100;
    v_product_id UUID;
    v_storage_id UUID;
    v_quantity INTEGER;
    v_item_index INTEGER := 0;
    v_sales_exchange JSONB;
    v_original_currency TEXT;
    v_item_settlement_currency TEXT;
    v_original_unit_price NUMERIC;
    v_negotiated_price NUMERIC;
    v_discount_percent NUMERIC;
    v_converted_unit_price NUMERIC;
    v_inventory_snapshot INTEGER;
    v_items_total NUMERIC := 0;
    v_flags TEXT[] := ARRAY[]::TEXT[];
    v_has_mixed_currency BOOLEAN := false;
    v_has_exchange_snapshot BOOLEAN := false;
    v_system_verified BOOLEAN := true;
    v_system_review_status TEXT := 'approved';
    v_system_review_reason TEXT := NULL;
    v_has_active_batches BOOLEAN := false;
    v_batch_remaining INTEGER := 0;
    v_allocated_quantity INTEGER := 0;
    v_batch_allocations JSONB := '[]'::jsonb;
    v_plan TEXT;
BEGIN
    SELECT current_workspace INTO p_workspace_id
    FROM public.profiles
    WHERE id = auth.uid();

    IF p_workspace_id IS NULL THEN
        RAISE EXCEPTION 'User does not belong to a workspace';
    END IF;

    SELECT plan, COALESCE(max_discount_percent, 100)
    INTO v_plan, v_max_discount_percent
    FROM public.workspaces
    WHERE id = p_workspace_id;

    v_pos := public.workspace_module_allowed(p_workspace_id, v_plan, 'pos');

    IF NOT COALESCE(v_pos, false) THEN
        RAISE EXCEPTION 'POS feature is not enabled for this workspace';
    END IF;

    total_sale_amount := COALESCE((payload->>'total_amount')::NUMERIC, 0);
    v_sales_exchange := CASE
        WHEN jsonb_typeof(payload->'sales_exchange') = 'array'
            THEN payload->'sales_exchange'
        ELSE '[]'::jsonb
    END;

    FOR snapshot IN SELECT * FROM jsonb_array_elements(v_sales_exchange)
    LOOP
        IF lower(COALESCE(snapshot->>'base_currency', '')) IN ('usd', 'eur', 'iqd', 'try')
            AND lower(COALESCE(snapshot->>'quote_currency', '')) IN ('usd', 'eur', 'iqd', 'try')
            AND lower(snapshot->>'base_currency') <> lower(snapshot->>'quote_currency')
            AND COALESCE((snapshot->>'base_amount')::NUMERIC, 0) > 0
            AND COALESCE((snapshot->>'quote_amount')::NUMERIC, 0) > 0
            AND NULLIF(snapshot->>'source', '') IS NOT NULL
            AND NULLIF(snapshot->>'captured_at', '') IS NOT NULL
            AND COALESCE(NULLIF(snapshot->>'rate_side', ''), 'mid')
                IN ('buy', 'sell', 'mid')
        THEN
            v_has_exchange_snapshot := true;
        ELSE
            RAISE EXCEPTION 'Invalid sales exchange snapshot';
        END IF;
    END LOOP;

    FOR item IN SELECT * FROM jsonb_array_elements(COALESCE(payload->'items', '[]'::jsonb))
    LOOP
        v_item_index := v_item_index + 1;
        v_quantity := COALESCE((item->>'quantity')::INTEGER, 0);
        v_converted_unit_price := COALESCE(
            (item->>'converted_unit_price')::NUMERIC,
            (item->>'unit_price')::NUMERIC,
            0
        );
        v_items_total := v_items_total + (v_converted_unit_price * v_quantity);

        IF v_quantity <= 0 THEN
            v_flags := array_append(
                v_flags,
                format('Item %s: Invalid quantity (%s)', v_item_index, v_quantity)
            );
        END IF;

        IF item->>'negotiated_price' IS NOT NULL THEN
            v_negotiated_price := (item->>'negotiated_price')::NUMERIC;

            IF v_negotiated_price < 0 THEN
                v_flags := array_append(
                    v_flags,
                    format('Item %s: Negative negotiated price', v_item_index)
                );
            ELSE
                v_original_unit_price := COALESCE(
                    (item->>'original_unit_price')::NUMERIC,
                    (item->>'unit_price')::NUMERIC,
                    0
                );

                IF v_original_unit_price > 0 THEN
                    v_discount_percent :=
                        ((v_original_unit_price - v_negotiated_price)
                        / v_original_unit_price) * 100;
                    IF v_discount_percent > v_max_discount_percent THEN
                        v_flags := array_append(
                            v_flags,
                            format(
                                'Item %s: Discount %s%% exceeds limit of %s%%',
                                v_item_index,
                                trim(to_char(v_discount_percent, 'FM999999990.0')),
                                v_max_discount_percent
                            )
                        );
                    END IF;
                END IF;
            END IF;
        END IF;

        v_original_currency := COALESCE(item->>'original_currency', 'usd');
        v_item_settlement_currency := COALESCE(
            item->>'settlement_currency',
            COALESCE(payload->>'settlement_currency', 'usd')
        );
        IF v_original_currency IS DISTINCT FROM v_item_settlement_currency THEN
            v_has_mixed_currency := true;
        END IF;

        v_inventory_snapshot := COALESCE(
            (item->>'inventory_snapshot')::INTEGER,
            0
        );
        IF v_quantity > v_inventory_snapshot THEN
            v_flags := array_append(
                v_flags,
                format(
                    'Item %s: Quantity %s exceeds inventory snapshot %s',
                    v_item_index,
                    v_quantity,
                    v_inventory_snapshot
                )
            );
        END IF;
    END LOOP;

    IF ABS(v_items_total - total_sale_amount) > 0.01 THEN
        v_flags := array_append(
            v_flags,
            format(
                'Total mismatch: items sum to %s, sale total is %s',
                trim(to_char(v_items_total, 'FM999999990.00')),
                trim(to_char(total_sale_amount, 'FM999999990.00'))
            )
        );
    END IF;

    IF v_has_mixed_currency AND NOT v_has_exchange_snapshot THEN
        v_flags := array_append(
            v_flags,
            'Missing exchange rate for multi-currency sale'
        );
    END IF;

    IF COALESCE(array_length(v_flags, 1), 0) > 0 THEN
        v_system_verified := false;
        v_system_review_status := 'flagged';
        v_system_review_reason := array_to_string(v_flags, '; ');
    END IF;

        id,
        workspace_id,
        cashier_id,
        total_amount,
        original_total_amount,
        currency,
        settlement_currency,
        origin,
        payment_method,
        system_verified,
        system_review_status,
        system_review_reason,
        notes
    )
    VALUES (
        COALESCE((payload->>'id')::UUID, gen_random_uuid()),
        p_workspace_id,
        auth.uid(),
        total_sale_amount,
        total_sale_amount,
        lower(COALESCE(
            payload->>'settlement_currency',
            payload->>'currency',
            'usd'
        )),
        lower(COALESCE(
            payload->>'settlement_currency',
            payload->>'currency',
            'usd'
        )),
        COALESCE(payload->>'origin', 'pos'),
        COALESCE(payload->>'payment_method', 'cash'),
        v_system_verified,
        v_system_review_status,
        v_system_review_reason,
        payload->>'notes'
    )
    RETURNING id, sequence_id INTO new_sale_id, v_sequence_id;

    FOR snapshot IN SELECT * FROM jsonb_array_elements(v_sales_exchange)
    LOOP
            sale_id,
            workspace_id,
            base_currency,
            quote_currency,
            base_amount,
            quote_amount,
            source,
            captured_at,
            rate_side,
            source_price_id,
            source_price_updated_at
        )
        VALUES (
            new_sale_id,
            p_workspace_id,
            lower(snapshot->>'base_currency'),
            lower(snapshot->>'quote_currency'),
            (snapshot->>'base_amount')::NUMERIC,
            (snapshot->>'quote_amount')::NUMERIC,
            snapshot->>'source',
            (snapshot->>'captured_at')::TIMESTAMPTZ,
            COALESCE(NULLIF(snapshot->>'rate_side', ''), 'mid'),
            NULLIF(snapshot->>'source_price_id', '')::UUID,
            NULLIF(snapshot->>'source_price_updated_at', '')::TIMESTAMPTZ
        );
    END LOOP;

    FOR item IN SELECT * FROM jsonb_array_elements(COALESCE(payload->'items', '[]'::jsonb))
    LOOP
        v_product_id := (item->>'product_id')::UUID;
        v_quantity := COALESCE((item->>'quantity')::INTEGER, 0);
        v_storage_id := NULLIF(item->>'storage_id', '')::UUID;
        v_has_active_batches := false;
        v_batch_remaining := v_quantity;
        v_batch_allocations := '[]'::jsonb;

        IF v_product_id IS NULL OR v_quantity <= 0 THEN
            RAISE EXCEPTION 'Invalid sale item payload';
        END IF;

        IF v_storage_id IS NULL THEN
            SELECT CASE
                WHEN COUNT(*) = 1 THEN MIN(storage_id::text)::uuid
                ELSE NULL
            END
            INTO v_storage_id
            FROM public.inventory
            WHERE workspace_id = p_workspace_id
              AND product_id = v_product_id
              AND COALESCE(is_deleted, false) = false;
        END IF;

        IF v_storage_id IS NULL THEN
            SELECT storage_id
            INTO v_storage_id
            FROM public.products
            WHERE id = v_product_id
              AND workspace_id = p_workspace_id;
        END IF;

        IF v_storage_id IS NULL THEN
            RAISE EXCEPTION 'Storage not found for product %', v_product_id;
        END IF;

        SELECT EXISTS (
            SELECT 1
            FROM public.stock_batches
            WHERE workspace_id = p_workspace_id
              AND product_id = v_product_id
              AND storage_id = v_storage_id
              AND COALESCE(is_deleted, false) = false
        )
        INTO v_has_active_batches;

        IF v_has_active_batches THEN
            FOR v_batch_record IN
                SELECT *
                FROM public.stock_batches
                WHERE workspace_id = p_workspace_id
                  AND product_id = v_product_id
                  AND storage_id = v_storage_id
                  AND COALESCE(is_deleted, false) = false
                ORDER BY
                    expiry_date ASC NULLS LAST,
                    manufacturing_date ASC NULLS LAST,
                    created_at ASC,
                    batch_number ASC
                FOR UPDATE
            LOOP
                EXIT WHEN v_batch_remaining <= 0;

                v_allocated_quantity := LEAST(
                    v_batch_remaining,
                    COALESCE(v_batch_record.quantity, 0)
                );
                IF v_allocated_quantity <= 0 THEN
                    CONTINUE;
                END IF;

                UPDATE public.stock_batches
                SET
                    quantity = v_batch_record.quantity - v_allocated_quantity,
                    updated_at = NOW(),
                    version = COALESCE(version, 0) + 1,
                    is_deleted =
                        (v_batch_record.quantity - v_allocated_quantity) <= 0
                WHERE id = v_batch_record.id;

                v_batch_allocations := v_batch_allocations || jsonb_build_array(
                    jsonb_build_object(
                        'batch_id', v_batch_record.id,
                        'batch_number', v_batch_record.batch_number,
                        'quantity', v_allocated_quantity,
                        'price', v_batch_record.price,
                        'cost_price', v_batch_record.cost_price,
                        'currency', lower(v_batch_record.currency),
                        'expiry_date', v_batch_record.expiry_date,
                        'manufacturing_date', v_batch_record.manufacturing_date
                    )
                );
                v_batch_remaining := v_batch_remaining - v_allocated_quantity;
            END LOOP;
        END IF;

            sale_id,
            product_id,
            storage_id,
            quantity,
            unit_price,
            total_price,
            cost_price,
            converted_cost_price,
            original_currency,
            original_unit_price,
            converted_unit_price,
            settlement_currency,
            negotiated_price,
            inventory_snapshot,
            batch_allocations,
            original_batch_allocations
        )
        VALUES (
            new_sale_id,
            v_product_id,
            v_storage_id,
            v_quantity,
            (item->>'unit_price')::NUMERIC,
            (item->>'total_price')::NUMERIC,
            COALESCE((item->>'cost_price')::NUMERIC, 0),
            COALESCE((item->>'converted_cost_price')::NUMERIC, 0),
            COALESCE(item->>'original_currency', 'usd'),
            COALESCE(
                (item->>'original_unit_price')::NUMERIC,
                (item->>'unit_price')::NUMERIC
            ),
            COALESCE(
                (item->>'converted_unit_price')::NUMERIC,
                (item->>'unit_price')::NUMERIC
            ),
            COALESCE(item->>'settlement_currency', 'usd'),
            (item->>'negotiated_price')::NUMERIC,
            COALESCE((item->>'inventory_snapshot')::INTEGER, 0),
            CASE
                WHEN v_has_active_batches
                    AND jsonb_array_length(v_batch_allocations) > 0
                    THEN v_batch_allocations
                ELSE NULL
            END,
            CASE
                WHEN v_has_active_batches
                    AND jsonb_array_length(v_batch_allocations) > 0
                    THEN v_batch_allocations
                ELSE NULL
            END
        );

        UPDATE public.inventory
        SET
            quantity = quantity - v_quantity,
            updated_at = NOW(),
            version = COALESCE(version, 0) + 1,
            is_deleted = (quantity - v_quantity) <= 0
        WHERE workspace_id = p_workspace_id
          AND product_id = v_product_id
          AND storage_id = v_storage_id
          AND COALESCE(is_deleted, false) = false
          AND quantity >= v_quantity;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Insufficient inventory for product % in storage %',
                v_product_id,
                v_storage_id;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'sale_id', new_sale_id,
        'sequence_id', v_sequence_id,
        'system_verified', v_system_verified,
        'system_review_status', v_system_review_status,
        'system_review_reason', v_system_review_reason
    );
END;
$$;


--
-- Name: convert_financed_amount(numeric, "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."convert_financed_amount"("p_amount" numeric, "p_from" "text", "p_to" "text", "p_snapshot" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_usd_iqd numeric;
  v_usd_eur numeric;
  v_eur_iqd numeric;
  v_usd_try numeric;
  v_try_iqd numeric;
BEGIN
  IF lower(p_from) = lower(p_to) THEN RETURN p_amount; END IF;

  SELECT max((entry->>'rate')::numeric / COALESCE(NULLIF((entry->>'priceBasisAmount')::numeric, 0), 100))
  INTO v_usd_iqd
  FROM jsonb_array_elements(COALESCE(p_snapshot, '[]'::jsonb)) entry
  WHERE upper(entry->>'pair') = 'USD/IQD';
  SELECT max((entry->>'rate')::numeric / COALESCE(NULLIF((entry->>'priceBasisAmount')::numeric, 0), 100))
  INTO v_usd_eur
  FROM jsonb_array_elements(COALESCE(p_snapshot, '[]'::jsonb)) entry
  WHERE upper(entry->>'pair') = 'USD/EUR';
  SELECT max((entry->>'rate')::numeric / COALESCE(NULLIF((entry->>'priceBasisAmount')::numeric, 0), 100))
  INTO v_eur_iqd
  FROM jsonb_array_elements(COALESCE(p_snapshot, '[]'::jsonb)) entry
  WHERE upper(entry->>'pair') = 'EUR/IQD';
  SELECT max((entry->>'rate')::numeric / COALESCE(NULLIF((entry->>'priceBasisAmount')::numeric, 0), 100))
  INTO v_usd_try
  FROM jsonb_array_elements(COALESCE(p_snapshot, '[]'::jsonb)) entry
  WHERE upper(entry->>'pair') = 'USD/TRY';
  SELECT max((entry->>'rate')::numeric / COALESCE(NULLIF((entry->>'priceBasisAmount')::numeric, 0), 100))
  INTO v_try_iqd
  FROM jsonb_array_elements(COALESCE(p_snapshot, '[]'::jsonb)) entry
  WHERE upper(entry->>'pair') = 'TRY/IQD';

  IF lower(p_from) = 'usd' AND lower(p_to) = 'iqd' THEN RETURN p_amount * v_usd_iqd;
  ELSIF lower(p_from) = 'iqd' AND lower(p_to) = 'usd' THEN RETURN p_amount / NULLIF(v_usd_iqd, 0);
  ELSIF lower(p_from) = 'usd' AND lower(p_to) = 'eur' THEN RETURN p_amount * v_usd_eur;
  ELSIF lower(p_from) = 'eur' AND lower(p_to) = 'usd' THEN RETURN p_amount / NULLIF(v_usd_eur, 0);
  ELSIF lower(p_from) = 'eur' AND lower(p_to) = 'iqd' THEN RETURN p_amount * v_eur_iqd;
  ELSIF lower(p_from) = 'iqd' AND lower(p_to) = 'eur' THEN RETURN p_amount / NULLIF(v_eur_iqd, 0);
  ELSIF lower(p_from) = 'usd' AND lower(p_to) = 'try' THEN RETURN p_amount * v_usd_try;
  ELSIF lower(p_from) = 'try' AND lower(p_to) = 'usd' THEN RETURN p_amount / NULLIF(v_usd_try, 0);
  ELSIF lower(p_from) = 'try' AND lower(p_to) = 'iqd' THEN RETURN p_amount * v_try_iqd;
  ELSIF lower(p_from) = 'iqd' AND lower(p_to) = 'try' THEN RETURN p_amount / NULLIF(v_try_iqd, 0);
  ELSIF lower(p_from) = 'try' AND lower(p_to) = 'eur' THEN RETURN (p_amount * v_try_iqd) / NULLIF(v_eur_iqd, 0);
  ELSIF lower(p_from) = 'eur' AND lower(p_to) = 'try' THEN RETURN (p_amount * v_eur_iqd) / NULLIF(v_try_iqd, 0);
  END IF;

  RETURN NULL;
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = "heap";

--
-- Name: invoice_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."invoice_versions" (
    "id" "uuid" NOT NULL,
    "invoice_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "origin" "text" NOT NULL,
    "version_number" integer NOT NULL,
    "format" "text" NOT NULL,
    "r2_path" "text",
    "file_size" bigint DEFAULT 0 NOT NULL,
    "created_by" "uuid",
    "created_by_name" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "invoice_versions_file_size_check" CHECK (("file_size" >= 0)),
    CONSTRAINT "invoice_versions_format_check" CHECK (("format" = ANY (ARRAY['a4'::"text", 'receipt'::"text"]))),
    CONSTRAINT "invoice_versions_version_number_check" CHECK (("version_number" > 0))
);


--
-- Name: create_invoice_version("uuid", "uuid", "uuid", "uuid", "text", "text", "text", bigint, "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_invoice_version"("p_id" "uuid", "p_invoice_id" "uuid", "p_workspace_id" "uuid", "p_source_id" "uuid", "p_origin" "text", "p_format" "text", "p_r2_path" "text", "p_file_size" bigint DEFAULT 0, "p_created_by_name" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."invoice_versions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_version public.invoice_versions%ROWTYPE;
  v_next_version integer;
BEGIN
  IF p_format NOT IN ('a4', 'receipt') THEN
    RAISE EXCEPTION 'Unsupported invoice format: %', p_format;
  END IF;

  SELECT *
  INTO v_version
  FROM public.invoice_versions
  WHERE id = p_id;

  IF FOUND THEN
    IF v_version.invoice_id IS DISTINCT FROM p_invoice_id
       OR v_version.workspace_id IS DISTINCT FROM p_workspace_id
       OR v_version.r2_path IS DISTINCT FROM p_r2_path THEN
      RAISE EXCEPTION 'Invoice version id % is already used by another snapshot', p_id;
    END IF;
    RETURN v_version;
  END IF;

  SELECT *
  INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND workspace_id = p_workspace_id
    AND is_deleted = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % was not found in workspace %', p_invoice_id, p_workspace_id;
  END IF;

  IF v_invoice.source_id IS DISTINCT FROM p_source_id
     OR v_invoice.origin IS DISTINCT FROM p_origin THEN
    RAISE EXCEPTION 'Invoice origin identity does not match %:%', p_origin, p_source_id;
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1
  INTO v_next_version
  FROM public.invoice_versions
  WHERE invoice_id = p_invoice_id;

    id,
    invoice_id,
    workspace_id,
    source_id,
    origin,
    version_number,
    format,
    r2_path,
    file_size,
    created_by,
    created_by_name,
    metadata
  ) VALUES (
    p_id,
    p_invoice_id,
    p_workspace_id,
    p_source_id,
    p_origin,
    v_next_version,
    p_format,
    p_r2_path,
    GREATEST(COALESCE(p_file_size, 0), 0),
    auth.uid(),
    p_created_by_name,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING * INTO v_version;

  UPDATE public.invoices
  SET latest_version_id = v_version.id,
      latest_version_number = v_version.version_number,
      print_format = p_format,
      r2_path_a4 = CASE WHEN p_format = 'a4' THEN p_r2_path ELSE r2_path_a4 END,
      r2_path_receipt = CASE WHEN p_format = 'receipt' THEN p_r2_path ELSE r2_path_receipt END,
      updated_at = now()
  WHERE id = p_invoice_id;

  RETURN v_version;
END;
$$;


--
-- Name: create_order_financing_loan("uuid", "text", "uuid", "text", "uuid", "text", "text", numeric, "text", "jsonb", integer, "text", "date", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_order_financing_loan"("p_workspace_id" "uuid", "p_order_type" "text", "p_order_id" "uuid", "p_order_number" "text", "p_partner_id" "uuid", "p_partner_name" "text", "p_payment_method" "text", "p_principal" numeric, "p_currency" "text", "p_exchange_rates" "jsonb", "p_installment_count" integer, "p_installment_frequency" "text", "p_first_due_date" "date", "p_created_by" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm', 'pg_temp'
    AS $$
DECLARE
  v_existing uuid;
  v_loan_id uuid := gen_random_uuid();
  v_partner crm.business_partners%ROWTYPE;
  v_direction text;
  v_limit numeric;
  v_usage numeric := 0;
  v_converted numeric;
  v_category text;
  v_count integer;
  v_base numeric;
  v_planned numeric;
  v_due date;
  v_index integer;
  v_plan text;
BEGIN
  IF p_order_type NOT IN ('sales', 'purchase') THEN RAISE EXCEPTION 'invalid_order_type'; END IF;
  IF p_payment_method NOT IN ('loan', 'installments') THEN RAISE EXCEPTION 'invalid_financing_method'; END IF;
  IF p_principal <= 0 THEN RAISE EXCEPTION 'invalid_financed_balance'; END IF;

  SELECT plan::text INTO v_plan FROM public.workspaces WHERE id = p_workspace_id;
  IF NOT public.workspace_module_allowed(
    p_workspace_id,
    v_plan,
    CASE WHEN p_payment_method = 'loan' THEN 'loans' ELSE 'installments' END
  ) THEN
    RAISE EXCEPTION 'financing_module_not_available';
  END IF;

  SELECT id INTO v_existing
  FROM public.loans
  WHERE order_type = p_order_type AND order_id = p_order_id AND is_deleted = false
  LIMIT 1;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  SELECT * INTO v_partner
  FROM crm.business_partners
  WHERE id = p_partner_id AND workspace_id = p_workspace_id AND is_deleted = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'business_partner_not_found'; END IF;

  v_direction := CASE WHEN p_order_type = 'sales' THEN 'lent' ELSE 'borrowed' END;
  v_limit := CASE WHEN v_direction = 'lent' THEN v_partner.receivable_credit_limit ELSE v_partner.payable_credit_limit END;

  IF v_limit IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.loans l
      WHERE l.workspace_id = p_workspace_id
        AND l.linked_party_id = p_partner_id
        AND l.direction = v_direction
        AND l.status <> 'completed'
        AND l.balance_amount > 0
        AND l.is_deleted = false
        AND public.convert_financed_amount(l.balance_amount, l.settlement_currency, v_partner.default_currency, l.exchange_rate_snapshot) IS NULL
    ) THEN
      RAISE EXCEPTION 'missing_credit_limit_exchange_rate';
    END IF;

    SELECT COALESCE(sum(public.convert_financed_amount(
      l.balance_amount, l.settlement_currency, v_partner.default_currency, l.exchange_rate_snapshot
    )), 0)
    INTO v_usage
    FROM public.loans l
    WHERE l.workspace_id = p_workspace_id
      AND l.linked_party_id = p_partner_id
      AND l.direction = v_direction
      AND l.status <> 'completed'
      AND l.balance_amount > 0
      AND l.is_deleted = false;

    v_converted := public.convert_financed_amount(p_principal, p_currency, v_partner.default_currency, p_exchange_rates);
    IF v_converted IS NULL THEN RAISE EXCEPTION 'missing_credit_limit_exchange_rate'; END IF;
    IF v_usage + v_converted > v_limit THEN RAISE EXCEPTION 'credit_limit_exceeded'; END IF;
  END IF;

  v_category := CASE WHEN p_payment_method = 'loan' THEN 'simple' ELSE 'standard' END;
  v_count := CASE
    WHEN p_payment_method = 'installments' THEN GREATEST(COALESCE(p_installment_count, 0), 1)
    WHEN p_first_due_date IS NOT NULL THEN 1
    ELSE 0
  END;
  IF p_payment_method = 'installments' AND (p_first_due_date IS NULL OR p_installment_frequency IS NULL) THEN
    RAISE EXCEPTION 'installment_schedule_required';
  END IF;

    id, workspace_id, sale_id, order_id, order_type, loan_no, source, loan_category,
    direction, linked_party_type, linked_party_id, linked_party_name,
    borrower_name, borrower_phone, borrower_address, borrower_national_id,
    principal_amount, total_paid_amount, balance_amount, settlement_currency,
    exchange_rate_snapshot, installment_count, installment_frequency,
    first_due_date, next_due_date, status, notes, created_by, version, is_deleted
  ) VALUES (
    v_loan_id, p_workspace_id, NULL, p_order_id, p_order_type,
    (CASE WHEN v_category = 'simple' THEN 'SL-' ELSE 'LN-' END)
      || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(v_loan_id::text, '-', ''), 1, 6)),
    'order', v_category, v_direction, 'business_partner', p_partner_id, p_partner_name,
    p_partner_name, '', '', '', p_principal, 0, p_principal, lower(p_currency),
    p_exchange_rates, v_count, COALESCE(p_installment_frequency, 'monthly'),
    p_first_due_date, p_first_due_date,
    CASE WHEN p_first_due_date < CURRENT_DATE THEN 'overdue' ELSE 'active' END,
    'Financing for ' || p_order_type || ' order ' || p_order_number,
    p_created_by, 1, false
  );

  IF v_count > 0 THEN
    v_base := CASE WHEN lower(p_currency) = 'iqd' THEN round(p_principal / v_count) ELSE round(p_principal / v_count, 2) END;
    FOR v_index IN 1..v_count LOOP
      v_planned := CASE
        WHEN v_index = v_count THEN p_principal - (v_base * (v_count - 1))
        ELSE v_base
      END;
      v_due := CASE COALESCE(p_installment_frequency, 'monthly')
        WHEN 'weekly' THEN p_first_due_date + ((v_index - 1) * 7)
        WHEN 'biweekly' THEN p_first_due_date + ((v_index - 1) * 14)
        ELSE (p_first_due_date + make_interval(months => v_index - 1))::date
      END;
        id, loan_id, workspace_id, installment_no, due_date, planned_amount,
        paid_amount, balance_amount, status, paid_at, version, is_deleted
      ) VALUES (
        gen_random_uuid(), v_loan_id, p_workspace_id, v_index, v_due, v_planned,
        0, v_planned, CASE WHEN v_due < CURRENT_DATE THEN 'overdue' ELSE 'unpaid' END,
        NULL, 1, false
      );
    END LOOP;
  END IF;

  RETURN v_loan_id;
END;
$$;


