--
-- Name: delete_demo_cascade("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_demo_cascade"("p_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm', 'budget', 'notifications'
    AS $_$
DECLARE
  v_workspace_record public.workspaces%ROWTYPE;
  v_table record;
  v_managed_tables text[] := ARRAY[
    'public.payment_transactions',
    'public.loan_payments',
    'public.loan_installments',
    'notifications.events',
    'notifications.device_tokens',
    'budget.payroll_statuses',
    'budget.dividend_statuses',
    'budget.expense_items',
    'budget.expense_series',
    'budget.budget_allocations',
    'budget.budget_settings',
    'public.marketplace_orders',
    'public.marketplace_order_counters',
    'public.invoices',
    'public.inventory_transfer_transactions',
    'public.reorder_transfer_rules',
    'public.inventory',
    'public.product_discounts',
    'public.category_discounts',
    'crm.sales_orders',
    'crm.purchase_orders',
    'crm.travel_agency_sales',
    'crm.business_partner_merge_candidates',
    'crm.customers',
    'crm.suppliers',
    'crm.business_partners',
    'public.employees',
    'public.workspace_contacts',
    'public.loans',
    'public.sales',
    'public.products',
    'public.categories',
    'public.storages',
    'public.clinical_presets',
    'public.clinical_appointments',
    'public.clinical_patients',
    'public.fx_transactions',
    'public.fx_safes',
    'public.fx_profit_snapshots',
    'public.fx_fee_rules',
    'public.fx_exchange_pair_prices',
    'public.real_estate_deals',
    'public.real_estate_parties',
    'public.real_estate_installment_schedules',
    'public.real_estate_witnesses',
    'public.real_estate_mediator_cashflows',
    'public.custom_templates',
    'public.custom_template_labels',
    'public.workspace_permissions',
    'public.workspace_access_overrides',
    'public.product_barcodes'
  ];
  v_table_name text;
BEGIN
  SELECT *
  INTO v_workspace_record
  FROM public.workspaces
  WHERE id = p_workspace_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Workspace not found: %', p_workspace_id;
  END IF;

  -- sale_items is special: it uses sale_id instead of workspace_id
  BEGIN
    DELETE FROM public.sale_items si
    USING public.sales s
    WHERE si.sale_id = s.id
      AND s.workspace_id = p_workspace_id;
  EXCEPTION WHEN undefined_table THEN
    -- skip if table doesn't exist
  END;

  -- Delete from all managed tables (those that need special handling like sale_items, or have workspace_id column)
  FOREACH v_table_name IN ARRAY v_managed_tables LOOP
    BEGIN
      EXECUTE format('DELETE FROM %s WHERE workspace_id = $1', v_table_name) USING p_workspace_id;
    EXCEPTION WHEN undefined_table THEN
      -- skip if the table doesn't exist in this project
    END;
  END LOOP;

  -- workspace_branches is special: uses source_workspace_id OR branch_workspace_id
  BEGIN
    DELETE FROM public.workspace_branches
    WHERE source_workspace_id = p_workspace_id OR branch_workspace_id = p_workspace_id;
  EXCEPTION WHEN undefined_table THEN
    -- skip if table doesn't exist
  END;

  -- Dynamically delete from any other table with a workspace_id column not yet covered
  FOR v_table IN
    SELECT DISTINCT
      c.table_schema,
      c.table_name
    FROM information_schema.columns c
    WHERE c.column_name = 'workspace_id'
      AND c.table_schema IN ('public', 'crm', 'budget', 'notifications')
      AND (c.table_schema || '.' || c.table_name) <> ALL (
        ARRAY['public.workspaces', 'public.profiles'] || v_managed_tables
      )
  LOOP
    BEGIN
      EXECUTE format(
        'DELETE FROM %I.%I WHERE workspace_id = $1',
        v_table.table_schema,
        v_table.table_name
      )
      USING p_workspace_id;
    EXCEPTION WHEN undefined_table THEN
      -- skip if table doesn't exist
    END;
  END LOOP;

  DELETE FROM public.profiles
  WHERE workspace_id = p_workspace_id;

  DELETE FROM public.workspaces
  WHERE id = p_workspace_id;

  RETURN jsonb_build_object(
    'success', true,
    'workspace_id', p_workspace_id
  );
END;
$_$;


--
-- Name: delete_device_token("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_device_token"("p_token_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
DECLARE
  v_deleted integer := 0;
BEGIN
  DELETE FROM notifications.device_tokens
  WHERE id = p_token_id;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted > 0;
END;
$$;


--
-- Name: detect_and_dispatch_notification_events("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."detect_and_dispatch_notification_events"("p_target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications', 'budget'
    AS $$
DECLARE
  v_dispatched_count integer;
BEGIN
  PERFORM public.queue_marketplace_pending_order_notifications(o.id)
  FROM public.marketplace_orders o
  WHERE o.status = 'pending'
    AND COALESCE(o.is_deleted, false) = false
    AND (p_target_workspace_id IS NULL OR o.workspace_id = p_target_workspace_id);

  PERFORM public.upsert_notification_event(
    c.workspace_id,
    r.user_id,
    'loan_installment_overdue',
    c.loan_id::text,
    c.due_date,
    jsonb_build_object(
      'entity_type', 'loan_installment_overdue',
      'title', format('Loan %s has overdue installments', c.loan_no),
      'body', concat_ws(' | ',
        COALESCE(NULLIF(c.borrower_name, ''), 'Unknown borrower'),
        format('%s overdue installment%s', c.overdue_installment_count, CASE WHEN c.overdue_installment_count = 1 THEN '' ELSE 's' END),
        c.overdue_amount::text || ' ' || upper(c.currency)
      ),
      'route', format('/installments/%s', c.loan_id),
      'action_label', 'Open installments',
      'scope', 'workspace',
      'priority', 'high',
      'loan_id', c.loan_id,
      'loan_no', c.loan_no,
      'borrower_name', c.borrower_name,
      'linked_party_name', c.linked_party_name,
      'currency', c.currency,
      'amount', c.overdue_amount,
      'due_date', c.due_date,
      'overdue_installment_count', c.overdue_installment_count
    )
  )
  FROM (
    SELECT p.id AS user_id, p.workspace_id
    FROM public.profiles p
    WHERE p.workspace_id IS NOT NULL
      AND LOWER(BTRIM(COALESCE(p.role, ''))) = 'admin'
      AND (p_target_workspace_id IS NULL OR p.workspace_id = p_target_workspace_id)
  ) r
  JOIN (
    SELECT *
    FROM (
      SELECT
        l.workspace_id,
        l.id AS loan_id,
        l.loan_no,
        l.borrower_name,
        l.linked_party_name,
        COALESCE(NULLIF(l.settlement_currency, ''), 'usd') AS currency,
        MIN(li.due_date) AS due_date,
        SUM(li.balance_amount) AS overdue_amount,
        COUNT(*)::integer AS overdue_installment_count,
        l.overdue_reminder_snoozed_at,
        l.overdue_reminder_snoozed_for_due_date
      FROM public.loans l
      JOIN public.loan_installments li
        ON li.loan_id = l.id
       AND li.workspace_id = l.workspace_id
      WHERE (p_target_workspace_id IS NULL OR l.workspace_id = p_target_workspace_id)
        AND COALESCE(l.is_deleted, false) = false
        AND COALESCE(li.is_deleted, false) = false
        AND COALESCE(l.balance_amount, 0) > 0
        AND COALESCE(li.balance_amount, 0) > 0
        AND COALESCE(li.status, 'pending') <> 'paid'
        AND li.due_date < current_date
      GROUP BY
        l.workspace_id,
        l.id,
        l.loan_no,
        l.borrower_name,
        l.linked_party_name,
        l.settlement_currency,
        l.overdue_reminder_snoozed_at,
        l.overdue_reminder_snoozed_for_due_date
    ) loan_overdue
    WHERE NOT (
      overdue_reminder_snoozed_at IS NOT NULL
      AND overdue_reminder_snoozed_for_due_date = due_date
    )
  ) c
    ON r.workspace_id = c.workspace_id;

  PERFORM public.upsert_notification_event(
    c.workspace_id,
    r.user_id,
    'expense_item_overdue',
    c.expense_item_id::text,
    c.due_date,
    jsonb_build_object(
      'entity_type', 'expense_item_overdue',
      'title', format('Overdue expense: %s', c.series_name),
      'body', concat_ws(' | ',
        COALESCE(NULLIF(c.subcategory, ''), NULLIF(c.category, ''), 'Expense'),
        c.amount::text || ' ' || upper(c.currency),
        'Due ' || c.due_date::text
      ),
      'route', '/budget',
      'action_label', 'Open budget',
      'scope', 'workspace',
      'priority', 'high',
      'expense_item_id', c.expense_item_id,
      'series_id', c.series_id,
      'series_name', c.series_name,
      'category', c.category,
      'subcategory', c.subcategory,
      'month', c.month,
      'currency', c.currency,
      'amount', c.amount,
      'due_date', c.due_date
    )
  )
  FROM (
    SELECT p.id AS user_id, p.workspace_id
    FROM public.profiles p
    WHERE p.workspace_id IS NOT NULL
      AND LOWER(BTRIM(COALESCE(p.role, ''))) = 'admin'
      AND (p_target_workspace_id IS NULL OR p.workspace_id = p_target_workspace_id)
  ) r
  JOIN (
    SELECT *
    FROM (
      SELECT
        ei.workspace_id,
        ei.id AS expense_item_id,
        ei.series_id,
        ei.month,
        ei.due_date,
        ei.amount,
        COALESCE(NULLIF(ei.currency, ''), 'usd') AS currency,
        COALESCE(NULLIF(es.name, ''), 'Expense') AS series_name,
        es.category,
        es.subcategory,
        COALESCE(ei.status, 'pending') AS status,
        ei.snoozed_until,
        COALESCE(ei.snoozed_indefinite, false) AS snoozed_indefinite
      FROM budget.expense_items ei
      JOIN budget.expense_series es
        ON es.id = ei.series_id
       AND es.workspace_id = ei.workspace_id
      WHERE (p_target_workspace_id IS NULL OR ei.workspace_id = p_target_workspace_id)
        AND COALESCE(ei.is_deleted, false) = false
        AND COALESCE(es.is_deleted, false) = false
        AND ei.due_date <= current_date
        AND COALESCE(ei.status, 'pending') <> 'paid'
    ) expense_candidates
    WHERE NOT (
      status = 'snoozed'
      AND (
        snoozed_indefinite = true
        OR (snoozed_until IS NOT NULL AND snoozed_until > now())
      )
    )
  ) c
    ON r.workspace_id = c.workspace_id;

  PERFORM public.upsert_notification_event(
    c.workspace_id,
    r.user_id,
    'payroll_overdue',
    (c.employee_id::text || ':' || c.month),
    c.due_date,
    jsonb_build_object(
      'entity_type', 'payroll_overdue',
      'title', format('Payroll overdue for %s', c.employee_name),
      'body', concat_ws(' | ',
        COALESCE(NULLIF(c.employee_role, ''), 'Employee'),
        c.amount::text || ' ' || upper(c.currency),
        c.month
      ),
      'route', '/budget',
      'action_label', 'Open budget',
      'scope', 'workspace',
      'priority', 'high',
      'employee_id', c.employee_id,
      'employee_name', c.employee_name,
      'employee_role', c.employee_role,
      'month', c.month,
      'currency', c.currency,
      'amount', c.amount,
      'due_date', c.due_date
    )
  )
  FROM (
    SELECT p.id AS user_id, p.workspace_id
    FROM public.profiles p
    WHERE p.workspace_id IS NOT NULL
      AND LOWER(BTRIM(COALESCE(p.role, ''))) = 'admin'
      AND (p_target_workspace_id IS NULL OR p.workspace_id = p_target_workspace_id)
  ) r
  JOIN (
    SELECT *
    FROM (
      SELECT
        e.workspace_id,
        e.id AS employee_id,
        e.name AS employee_name,
        e.role AS employee_role,
        pm.month,
        COALESCE(e.salary, 0) AS amount,
        COALESCE(NULLIF(e.salary_currency, ''), 'usd') AS currency,
        make_date(
          split_part(pm.month, '-', 1)::integer,
          split_part(pm.month, '-', 2)::integer,
          LEAST(
            GREATEST(COALESCE(e.salary_payday, 30), 1),
            EXTRACT(
              DAY FROM (
                date_trunc('month', make_date(split_part(pm.month, '-', 1)::integer, split_part(pm.month, '-', 2)::integer, 1))
                + interval '1 month - 1 day'
              )
            )::integer
          )
        ) AS due_date,
        COALESCE(ps.status, 'pending') AS status,
        ps.snoozed_until,
        COALESCE(ps.snoozed_indefinite, false) AS snoozed_indefinite
      FROM public.employees e
      JOIN (
        SELECT to_char(current_date, 'YYYY-MM') AS month
        UNION
        SELECT ps.month
        FROM budget.payroll_statuses ps
        WHERE COALESCE(ps.is_deleted, false) = false
          AND (p_target_workspace_id IS NULL OR ps.workspace_id = p_target_workspace_id)
      ) pm ON true
      LEFT JOIN budget.payroll_statuses ps
        ON ps.workspace_id = e.workspace_id
       AND ps.employee_id = e.id
       AND ps.month = pm.month
       AND COALESCE(ps.is_deleted, false) = false
      WHERE (p_target_workspace_id IS NULL OR e.workspace_id = p_target_workspace_id)
        AND COALESCE(e.is_deleted, false) = false
        AND COALESCE(e.is_fired, false) = false
        AND COALESCE(e.salary, 0) > 0
    ) payroll_base
    WHERE due_date <= current_date
      AND status <> 'paid'
      AND NOT (
        status = 'snoozed'
        AND (
          snoozed_indefinite = true
          OR (snoozed_until IS NOT NULL AND snoozed_until > now())
        )
      )
  ) c
    ON r.workspace_id = c.workspace_id;

  PERFORM public.upsert_notification_event(
    c.workspace_id,
    r.user_id,
    'inventory_low_stock',
    (c.product_id::text || ':' || c.storage_id::text),
    current_date,
    jsonb_build_object(
      'entity_type', 'inventory_low_stock',
      'title', format('Low stock: %s', c.product_name),
      'body', concat_ws(' | ',
        c.storage_name,
        format('%s %s remaining', c.quantity, upper(c.unit)),
        format('Min %s', c.min_stock_level)
      ),
      'route', '/storages',
      'action_label', 'Open storages',
      'scope', 'workspace',
      'priority', 'high',
      'product_id', c.product_id,
      'storage_id', c.storage_id,
      'product_name', c.product_name,
      'sku', c.sku,
      'storage_name', c.storage_name,
      'quantity', c.quantity,
      'min_stock_level', c.min_stock_level,
      'unit', c.unit
    )
  )
  FROM (
    SELECT p.id AS user_id, p.workspace_id
    FROM public.profiles p
    WHERE p.workspace_id IS NOT NULL
      AND LOWER(BTRIM(COALESCE(p.role, ''))) = 'admin'
      AND (p_target_workspace_id IS NULL OR p.workspace_id = p_target_workspace_id)
  ) r
  JOIN (
    SELECT
      i.workspace_id,
      i.product_id,
      i.storage_id,
      COALESCE(NULLIF(BTRIM(p.name), ''), 'Unnamed product') AS product_name,
      COALESCE(NULLIF(BTRIM(p.sku), ''), 'NO-SKU') AS sku,
      COALESCE(NULLIF(BTRIM(s.name), ''), 'Unknown storage') AS storage_name,
      GREATEST(COALESCE(i.quantity, 0), 0) AS quantity,
      GREATEST(COALESCE(p.min_stock_level, 0), 0) AS min_stock_level,
      COALESCE(NULLIF(BTRIM(p.unit), ''), 'pcs') AS unit
    FROM public.inventory i
    JOIN public.products p
      ON p.id = i.product_id
     AND p.workspace_id = i.workspace_id
    JOIN public.storages s
      ON s.id = i.storage_id
     AND s.workspace_id = i.workspace_id
    WHERE (p_target_workspace_id IS NULL OR i.workspace_id = p_target_workspace_id)
      AND COALESCE(i.is_deleted, false) = false
      AND COALESCE(p.is_deleted, false) = false
      AND COALESCE(s.is_deleted, false) = false
      AND GREATEST(COALESCE(p.min_stock_level, 0), 0) > 0
      AND GREATEST(COALESCE(i.quantity, 0), 0) < GREATEST(COALESCE(p.min_stock_level, 0), 0)
  ) c
    ON r.workspace_id = c.workspace_id;

  v_dispatched_count := public.dispatch_notification_events();
  RETURN COALESCE(v_dispatched_count, 0);
END;
$$;


--
-- Name: detect_workspace_upload_mime("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."detect_workspace_upload_mime"("p_path" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN lower(coalesce(p_path, '')) LIKE '%.pdf' THEN 'application/pdf'
    WHEN lower(coalesce(p_path, '')) LIKE '%.png' THEN 'image/png'
    WHEN lower(coalesce(p_path, '')) LIKE '%.jpg' THEN 'image/jpeg'
    WHEN lower(coalesce(p_path, '')) LIKE '%.jpeg' THEN 'image/jpeg'
    WHEN lower(coalesce(p_path, '')) LIKE '%.mp3' THEN 'audio/mpeg'
    ELSE NULL
  END;
$$;


--
-- Name: dispatch_notification_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."dispatch_notification_events"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $_$
DECLARE
  v_event record;
  v_payload jsonb;
  v_processed integer := 0;
  v_batch_processed integer;
  v_title text;
  v_body text;
  v_action_url text;
  v_action_label text;
  v_scope text;
  v_priority text;
  v_notification_type text;
  v_dedupe_key text;
  v_due_date text;
  v_order_id text;
  v_order_number text;
  v_customer_name text;
  v_item_count integer;
  v_amount numeric;
  v_currency text;
BEGIN
  LOOP
    v_batch_processed := 0;

    FOR v_event IN
      SELECT *
      FROM public.get_pending_notification_events()
    LOOP
      BEGIN
        v_payload := COALESCE(v_event.payload, '{}'::jsonb);

        IF v_event.entity_type = 'budget_payroll'
          OR (
            v_event.entity_type = 'payroll_overdue'
            AND v_payload ? 'status_id'
          ) THEN
          DELETE FROM notifications.inbox
          WHERE event_id = v_event.id;

          PERFORM public.update_notification_event_status(
            v_event.id,
            'sent'::text,
            NULL::text,
            NULL::integer
          );

          v_processed := v_processed + 1;
          v_batch_processed := v_batch_processed + 1;
          CONTINUE;
        END IF;

        v_due_date := NULLIF(BTRIM(COALESCE(v_payload ->> 'due_date', '')), '');
        v_title := NULLIF(BTRIM(COALESCE(v_payload ->> 'title', '')), '');
        v_body := COALESCE(
          NULLIF(BTRIM(COALESCE(v_payload ->> 'body', '')), ''),
          NULLIF(BTRIM(COALESCE(v_payload ->> 'preview', '')), ''),
          NULLIF(BTRIM(COALESCE(v_payload ->> 'summary', '')), '')
        );
        v_action_url := NULLIF(BTRIM(COALESCE(v_payload ->> 'route', '')), '');
        v_action_label := NULLIF(BTRIM(COALESCE(v_payload ->> 'action_label', '')), '');
        v_scope := NULLIF(BTRIM(COALESCE(v_payload ->> 'scope', '')), '');
        v_notification_type := CASE
          WHEN v_event.entity_type = 'budget_payroll' THEN 'payroll_overdue'
          ELSE v_event.entity_type
        END;
        v_priority := NULLIF(BTRIM(COALESCE(v_payload ->> 'priority', '')), '');

        v_scope := CASE
          WHEN v_scope IN ('user', 'workspace', 'system') THEN v_scope
          WHEN v_notification_type = 'marketplace_order_pending' THEN 'workspace'
          ELSE 'user'
        END;

        v_priority := CASE
          WHEN v_priority IN ('low', 'normal', 'high', 'urgent') THEN v_priority
          ELSE 'normal'
        END;

        v_dedupe_key := concat_ws(
          ':',
          v_event.user_id::text,
          v_notification_type,
          v_event.entity_id,
          COALESCE(v_due_date, to_char(v_event.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD'))
        );

        IF v_notification_type = 'marketplace_order_pending' THEN
          v_order_id := COALESCE(NULLIF(BTRIM(COALESCE(v_payload ->> 'order_id', '')), ''), v_event.entity_id);
          v_order_number := NULLIF(BTRIM(COALESCE(v_payload ->> 'order_number', '')), '');
          v_customer_name := NULLIF(BTRIM(COALESCE(v_payload ->> 'customer_name', '')), '');

          v_item_count := CASE
            WHEN COALESCE(v_payload ->> 'item_count', '') ~ '^-?\d+$' THEN (v_payload ->> 'item_count')::integer
            ELSE NULL
          END;

          v_amount := CASE
            WHEN COALESCE(v_payload ->> 'amount', '') ~ '^-?\d+(\.\d+)?$' THEN (v_payload ->> 'amount')::numeric
            ELSE NULL
          END;

          v_currency := UPPER(NULLIF(BTRIM(COALESCE(v_payload ->> 'currency', '')), ''));
          v_title := COALESCE(
            v_title,
            CASE
              WHEN v_order_number IS NOT NULL THEN format('Pending marketplace order %s', v_order_number)
              ELSE 'Pending marketplace order'
            END
          );

          IF v_body IS NULL THEN
            v_body := concat_ws(
              ' | ',
              v_customer_name,
              CASE
                WHEN v_item_count IS NOT NULL AND v_item_count > 0
                  THEN format('%s item%s', v_item_count, CASE WHEN v_item_count = 1 THEN '' ELSE 's' END)
                ELSE NULL
              END,
              CASE
                WHEN v_amount IS NOT NULL
                  THEN concat_ws(' ', trim(to_char(v_amount, 'FM999999999990.##')), NULLIF(v_currency, ''))
                ELSE NULL
              END
            );
          END IF;

          v_action_url := COALESCE(v_action_url, CASE WHEN v_order_id IS NOT NULL THEN format('/ecommerce/%s', v_order_id) ELSE '/ecommerce' END);
          v_action_label := COALESCE(v_action_label, 'Open order');
        ELSIF v_notification_type = 'payroll_overdue' THEN
          v_amount := CASE
            WHEN COALESCE(v_payload ->> 'amount', '') ~ '^-?\d+(\.\d+)?$' THEN (v_payload ->> 'amount')::numeric
            ELSE NULL
          END;

          v_currency := UPPER(NULLIF(BTRIM(COALESCE(v_payload ->> 'currency', '')), ''));
          v_customer_name := COALESCE(
            NULLIF(BTRIM(COALESCE(v_payload ->> 'employee_name', '')), ''),
            CASE
              WHEN v_event.entity_type = 'budget_payroll' THEN NULLIF(BTRIM(COALESCE(v_payload ->> 'title', '')), '')
              ELSE NULL
            END
          );

          v_title := COALESCE(
            CASE
              WHEN v_customer_name IS NOT NULL THEN format('Payroll overdue for %s', v_customer_name)
              ELSE NULL
            END,
            v_title,
            'Payroll overdue'
          );

          IF v_body IS NULL THEN
            v_body := concat_ws(
              ' | ',
              COALESCE(NULLIF(BTRIM(COALESCE(v_payload ->> 'employee_role', '')), ''), 'Employee'),
              CASE
                WHEN v_amount IS NOT NULL
                  THEN concat_ws(' ', trim(to_char(v_amount, 'FM999999999990.##')), NULLIF(v_currency, ''))
                ELSE NULL
              END,
              NULLIF(BTRIM(COALESCE(v_payload ->> 'month', '')), '')
            );
          END IF;

          v_scope := 'workspace';
          IF NULLIF(BTRIM(COALESCE(v_payload ->> 'priority', '')), '') IS NULL THEN
            v_priority := 'high';
          END IF;
          v_action_url := COALESCE(v_action_url, '/budget');
          v_action_label := COALESCE(v_action_label, 'Open budget');
          v_payload := jsonb_strip_nulls(
            v_payload || jsonb_build_object(
              'entity_type', 'payroll_overdue',
              'employee_name', v_customer_name,
              'employee_role', COALESCE(NULLIF(BTRIM(COALESCE(v_payload ->> 'employee_role', '')), ''), 'Employee'),
              'route', v_action_url,
              'action_label', v_action_label,
              'scope', v_scope,
              'priority', v_priority,
              'title', v_title,
              'body', v_body
            )
          );
        ELSE
          v_title := COALESCE(
            v_title,
            INITCAP(REPLACE(REPLACE(v_notification_type, '_', ' '), '-', ' '))
          );
          v_body := COALESCE(
            v_body,
            NULLIF(BTRIM(COALESCE(v_payload ->> 'content', '')), ''),
            NULLIF(BTRIM(COALESCE(v_payload ->> 'message', '')), '')
          );
        END IF;

        PERFORM public.upsert_notification_inbox(
          p_event_id => v_event.id,
          p_workspace_id => v_event.workspace_id,
          p_user_id => v_event.user_id,
          p_notification_type => v_notification_type,
          p_scope => v_scope,
          p_priority => v_priority,
          p_dedupe_key => v_dedupe_key,
          p_title => v_title,
          p_body => v_body,
          p_action_url => v_action_url,
          p_action_label => v_action_label,
          p_payload => v_payload,
          p_created_at => v_event.created_at
        );

        PERFORM public.update_notification_event_status(
          v_event.id,
          'sent'::text,
          NULL::text,
          NULL::integer
        );
      EXCEPTION
        WHEN OTHERS THEN
          PERFORM public.update_notification_event_status(
            v_event.id,
            'failed'::text,
            SQLERRM::text,
            NULL::integer
          );
      END;

      v_processed := v_processed + 1;
      v_batch_processed := v_batch_processed + 1;
    END LOOP;

    EXIT WHEN v_batch_processed = 0;
  END LOOP;

  RETURN v_processed;
END;
$_$;


--
-- Name: enforce_agents_override_admin_console(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_agents_override_admin_console"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
BEGIN
  IF (
      (TG_OP <> 'INSERT' AND OLD.type = 'module' AND OLD.key = 'agents')
      OR (TG_OP <> 'DELETE' AND NEW.type = 'module' AND NEW.key = 'agents')
    )
    AND auth.role() IS DISTINCT FROM 'service_role'
  THEN
    RAISE EXCEPTION 'Agents module access can only be changed from the platform admin dashboard'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_crm_agent_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_crm_agent_links"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM crm.business_partners bp
    WHERE bp.id = NEW.business_partner_id
      AND bp.workspace_id = NEW.workspace_id
      AND COALESCE(bp.is_deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'Agent business partner must belong to the same workspace'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.linked_user_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = NEW.linked_user_id
      AND p.workspace_id = NEW.workspace_id
  ) THEN
    RAISE EXCEPTION 'Linked workspace user must belong to the agent workspace'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.linked_user_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM crm.agents a
    WHERE a.workspace_id = NEW.workspace_id
      AND a.linked_user_id = NEW.linked_user_id
      AND a.id <> NEW.id
      AND COALESCE(a.is_deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'Workspace user is already linked to another agent'
      USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_crm_business_partner_agent_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_crm_business_partner_agent_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm'
    AS $$
DECLARE
  v_plan text;
BEGIN
  IF NEW.role <> 'agent' THEN
    RETURN NEW;
  END IF;

  SELECT w.plan::text
  INTO v_plan
  FROM public.workspaces w
  WHERE w.id = NEW.workspace_id
    AND w.deleted_at IS NULL;

  IF v_plan IS NULL OR NOT public.workspace_module_allowed(NEW.workspace_id, v_plan, 'agents') THEN
    RAISE EXCEPTION 'Agents module is not enabled for this workspace'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_crm_business_partner_real_estate_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_crm_business_partner_real_estate_roles"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
BEGIN
  IF NEW.role NOT IN ('buyer', 'seller') THEN
    RETURN NEW;
  END IF;

  SELECT plan::text INTO v_plan
  FROM public.workspaces
  WHERE id = NEW.workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NULL OR NOT public.workspace_module_allowed(NEW.workspace_id, v_plan, 'real_estate') THEN
    RAISE EXCEPTION 'Real Estate partner role % requires workspace Real Estate access', NEW.role
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_crm_business_partners_module_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_crm_business_partners_module_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_required_module text;
BEGIN
  SELECT plan::text INTO v_plan
  FROM public.workspaces
  WHERE id = NEW.workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NULL THEN
    RETURN NEW;
  END IF;

  v_required_module := CASE
    WHEN NEW.role IN ('buyer', 'seller') THEN 'real_estate'
    ELSE 'business_partners'
  END;

  IF NOT public.workspace_module_allowed(NEW.workspace_id, v_plan, v_required_module) THEN
    RAISE EXCEPTION 'Module % is not included in the current workspace access', v_required_module
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_fx_workspace_currency_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_fx_workspace_currency_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'fx'
    AS $$
BEGIN
  IF OLD.default_currency IS DISTINCT FROM NEW.default_currency
     AND public.workspace_has_fx_accounting_data(NEW.id) THEN
    RAISE EXCEPTION 'Workspace currency is locked because Currency Exchange has safes or transactions. This protects historical balances and profit reports.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_workspace_branch_plan_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_workspace_branch_plan_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_branch_count integer;
BEGIN
  IF NEW.archived_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT plan::text INTO v_plan
  FROM public.workspaces
  WHERE id = NEW.source_workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.workspace_max_branches(NEW.source_workspace_id, v_plan) <= 0 THEN
    RAISE EXCEPTION 'Branches are not included in the current workspace plan'
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*) INTO v_branch_count
  FROM public.workspace_branches
  WHERE source_workspace_id = NEW.source_workspace_id
    AND archived_at IS NULL
    AND (TG_OP <> 'UPDATE' OR id IS DISTINCT FROM OLD.id);

  IF v_branch_count >= public.workspace_max_branches(NEW.source_workspace_id, v_plan) THEN
    RAISE EXCEPTION 'Workspace branch limit reached for current plan'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_workspace_contact_plan_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_workspace_contact_plan_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_contact_count integer;
  v_max_contacts integer;
BEGIN
  SELECT plan INTO v_plan
  FROM public.workspaces
  WHERE id = NEW.workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NULL THEN
    RETURN NEW;
  END IF;

  v_max_contacts := public.workspace_max_contacts(NEW.workspace_id, v_plan);
  IF v_max_contacts IS NULL THEN
    RETURN NEW;
  END IF;

  NEW.is_primary := true;

  SELECT count(*) INTO v_contact_count
  FROM public.workspace_contacts
  WHERE workspace_id = NEW.workspace_id
    AND (TG_OP <> 'UPDATE' OR id IS DISTINCT FROM OLD.id);

  IF v_contact_count >= v_max_contacts THEN
    RAISE EXCEPTION 'Workspace contact limit reached for current plan'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_workspace_currency_plan_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_workspace_currency_plan_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_workspace_id uuid;
  v_plan text;
  v_currency text;
BEGIN
  v_workspace_id := nullif(to_jsonb(NEW)->>'workspace_id', '')::uuid;
  v_currency := lower(coalesce(
    nullif(to_jsonb(NEW)->>'settlement_currency', ''),
    nullif(to_jsonb(NEW)->>'currency', '')
  ));

  IF v_workspace_id IS NULL OR v_currency IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT plan INTO v_plan
  FROM public.workspaces
  WHERE id = v_workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NOT NULL AND NOT public.workspace_currency_allowed(v_workspace_id, v_plan, v_currency) THEN
    RAISE EXCEPTION 'Currency % is not included in the current workspace plan', v_currency
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_workspace_invoice_plan_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_workspace_invoice_plan_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_is_upload boolean;
  v_upload_mime text;
  v_upload_limit bigint;
  v_workspace_id uuid;
BEGIN
  v_workspace_id := NEW.workspace_id;

  IF v_workspace_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT plan INTO v_plan
  FROM public.workspaces
  WHERE id = v_workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.settlement_currency IS NOT NULL
    AND NOT public.workspace_currency_allowed(v_workspace_id, v_plan, NEW.settlement_currency::text) THEN
    RAISE EXCEPTION 'Currency % is not included in the current workspace plan', NEW.settlement_currency
      USING ERRCODE = '42501';
  END IF;

  v_is_upload :=
    lower(coalesce(NEW.origin, '')) = 'upload'
    OR coalesce(NEW.r2_path_a4, '') LIKE '%/uploads/%'
    OR coalesce(NEW.r2_path_receipt, '') LIKE '%/uploads/%';

  IF v_is_upload THEN
    v_upload_limit := public.workspace_max_upload_bytes(v_workspace_id, v_plan);
    v_upload_mime := coalesce(
      nullif(lower(NEW.file_mime_type), ''),
      public.detect_workspace_upload_mime(NEW.r2_path_a4),
      public.detect_workspace_upload_mime(NEW.r2_path_receipt)
    );

    IF v_upload_limit <= 0 THEN
      RAISE EXCEPTION 'Workspace uploads are not included in the current plan'
        USING ERRCODE = '42501';
    END IF;

    IF NEW.file_size IS NULL OR NEW.file_size <= 0 OR NEW.file_size > v_upload_limit THEN
      RAISE EXCEPTION 'Upload size exceeds the current workspace plan limit'
        USING ERRCODE = '42501';
    END IF;

    IF NOT public.workspace_upload_mime_allowed(v_workspace_id, v_plan, v_upload_mime) THEN
      RAISE EXCEPTION 'Upload file type is not included in the current workspace plan'
        USING ERRCODE = '42501';
    END IF;

    NEW.file_mime_type := v_upload_mime;
  END IF;

  IF NOT v_is_upload
    AND lower(coalesce(NEW.print_format, '')) = 'a4'
    AND NOT public.workspace_capability_allowed(v_workspace_id, v_plan, 'a4PdfInvoices') THEN
    RAISE EXCEPTION 'A4 invoice generation is not included in the current workspace plan'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_workspace_member_plan_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_workspace_member_plan_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_member_count integer;
BEGIN
  IF NEW.workspace_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.workspace_id IS NOT DISTINCT FROM OLD.workspace_id THEN
    RETURN NEW;
  END IF;

  SELECT plan::text INTO v_plan
  FROM public.workspaces
  WHERE id = NEW.workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO v_member_count
  FROM public.profiles
  WHERE workspace_id = NEW.workspace_id
    AND id IS DISTINCT FROM NEW.id;

  IF v_member_count >= public.workspace_max_members(NEW.workspace_id, v_plan) THEN
    RAISE EXCEPTION 'Workspace member limit reached for current plan'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_workspace_module_plan_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_workspace_module_plan_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_workspace_id uuid;
  v_plan text;
  v_module text;
BEGIN
  v_workspace_id := nullif(to_jsonb(NEW)->>'workspace_id', '')::uuid;
  v_module := TG_ARGV[0];

  IF v_workspace_id IS NULL OR v_module IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT plan INTO v_plan
  FROM public.workspaces
  WHERE id = v_workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NOT NULL AND NOT public.workspace_module_allowed(v_workspace_id, v_plan, v_module) THEN
    RAISE EXCEPTION 'Module % is not included in the current workspace plan', v_module
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_workspace_permissions_plan_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_workspace_permissions_plan_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
BEGIN
  SELECT plan INTO v_plan
  FROM public.workspaces
  WHERE id = NEW.workspace_id
    AND deleted_at IS NULL;

  IF v_plan IS NULL OR NOT public.workspace_capability_allowed(NEW.workspace_id, v_plan, 'workspaceManagementPermissions') THEN
    RAISE EXCEPTION 'Workspace management permissions are not included in the current workspace plan'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.module IN ('currencyExchange', 'currencyExchangeFeeRules')
    AND NOT public.workspace_module_allowed(NEW.workspace_id, v_plan, 'currency_exchange')
  THEN
    RAISE EXCEPTION 'Currency Exchange Service is not enabled for this workspace'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.module IN ('agents', 'fleet')
    AND NOT public.workspace_module_allowed(NEW.workspace_id, v_plan, 'agents')
  THEN
    RAISE EXCEPTION 'Agents module is not enabled for this workspace'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: ensure_marketplace_storage("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."ensure_marketplace_storage"("p_workspace_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_marketplace_storage_id uuid;
BEGIN
  IF p_workspace_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT id
  INTO v_marketplace_storage_id
  FROM public.storages
  WHERE workspace_id = p_workspace_id
    AND COALESCE(is_deleted, false) = false
    AND COALESCE(is_marketplace, false) = true
  ORDER BY is_primary DESC, is_system DESC, is_protected DESC, created_at NULLS LAST, id
  LIMIT 1;

  IF v_marketplace_storage_id IS NULL THEN
    SELECT id
    INTO v_marketplace_storage_id
    FROM public.storages
    WHERE workspace_id = p_workspace_id
      AND COALESCE(is_deleted, false) = false
      AND COALESCE(is_primary, false) = true
    ORDER BY is_system DESC, is_protected DESC, created_at NULLS LAST, id
    LIMIT 1;
  END IF;

  IF v_marketplace_storage_id IS NULL THEN
    SELECT id
    INTO v_marketplace_storage_id
    FROM public.storages
    WHERE workspace_id = p_workspace_id
      AND COALESCE(is_deleted, false) = false
    ORDER BY is_system DESC, is_protected DESC, created_at NULLS LAST, id
    LIMIT 1;
  END IF;

  IF v_marketplace_storage_id IS NULL THEN
    RETURN NULL;
  END IF;

  UPDATE public.storages
  SET
    is_marketplace = (id = v_marketplace_storage_id),
    updated_at = CASE
      WHEN COALESCE(is_marketplace, false) IS DISTINCT FROM (id = v_marketplace_storage_id)
        THEN timezone('utc', now())
      ELSE updated_at
    END
  WHERE workspace_id = p_workspace_id
    AND COALESCE(is_deleted, false) = false
    AND COALESCE(is_marketplace, false) IS DISTINCT FROM (id = v_marketplace_storage_id);

  RETURN v_marketplace_storage_id;
END;
$$;


--
-- Name: ensure_primary_storage("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."ensure_primary_storage"("p_workspace_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_primary_storage_id uuid;
BEGIN
    SELECT id
    INTO v_primary_storage_id
    FROM public.storages
    WHERE workspace_id = p_workspace_id
      AND COALESCE(is_deleted, false) = false
      AND COALESCE(is_primary, false) = true
    ORDER BY is_system DESC, is_protected DESC, created_at NULLS LAST, id
    LIMIT 1;

    IF v_primary_storage_id IS NULL THEN
        SELECT id
        INTO v_primary_storage_id
        FROM public.storages
        WHERE workspace_id = p_workspace_id
          AND COALESCE(is_deleted, false) = false
          AND LOWER(name) = 'main'
        ORDER BY is_system DESC, is_protected DESC, created_at NULLS LAST, id
        LIMIT 1;
    END IF;

    IF v_primary_storage_id IS NULL THEN
        SELECT id
        INTO v_primary_storage_id
        FROM public.storages
        WHERE workspace_id = p_workspace_id
          AND COALESCE(is_deleted, false) = false
        ORDER BY is_system DESC, is_protected DESC, created_at NULLS LAST, id
        LIMIT 1;
    END IF;

    IF v_primary_storage_id IS NULL THEN
            workspace_id,
            name,
            is_system,
            is_protected,
            is_primary,
            created_at,
            updated_at,
            is_deleted
        )
        VALUES (
            p_workspace_id,
            'Main',
            true,
            true,
            true,
            timezone('utc', now()),
            timezone('utc', now()),
            false
        )
        RETURNING id INTO v_primary_storage_id;

        RETURN v_primary_storage_id;
    END IF;

    UPDATE public.storages
    SET
        is_primary = (id = v_primary_storage_id),
        updated_at = CASE
            WHEN id = v_primary_storage_id AND COALESCE(is_primary, false) = false THEN timezone('utc', now())
            ELSE updated_at
        END
    WHERE workspace_id = p_workspace_id
      AND COALESCE(is_deleted, false) = false
      AND COALESCE(is_primary, false) IS DISTINCT FROM (id = v_primary_storage_id);

    RETURN v_primary_storage_id;
END;
$$;


--
-- Name: ensure_workspace_marketplace_storage_selection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."ensure_workspace_marketplace_storage_selection"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_workspace_id uuid := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.workspace_id END;
  v_new_workspace_id uuid := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE NEW.workspace_id END;
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF v_old_workspace_id IS NOT NULL THEN
    PERFORM public.ensure_marketplace_storage(v_old_workspace_id);
  END IF;

  IF v_new_workspace_id IS NOT NULL AND v_new_workspace_id IS DISTINCT FROM v_old_workspace_id THEN
    PERFORM public.ensure_marketplace_storage(v_new_workspace_id);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: generate_random_alphanumeric_key(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_random_alphanumeric_key"("length" integer DEFAULT 32) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
    chars TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    result TEXT := '';
    i INT;
BEGIN
    FOR i IN 1..length LOOP
        result := result || pg_catalog.substr(chars, pg_catalog.floor(pg_catalog.random() * pg_catalog.length(chars) + 1)::INT, 1);
    END LOOP;
    RETURN result;
END;
$$;


--
-- Name: generate_random_base64_key(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_random_base64_key"("length" integer DEFAULT 32) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
    generated_key text;
BEGIN
    IF length IS NULL OR length <= 0 OR length % 4 <> 0 THEN
        RAISE EXCEPTION 'Base64 key length must be a positive multiple of 4. Received: %', length;
    END IF;

    generated_key := pg_catalog.translate(
        pg_catalog.encode(extensions.gen_random_bytes((length / 4) * 3), 'base64'),
        E'\n\r',
        ''
    );

    IF pg_catalog.char_length(generated_key) <> length THEN
        RAISE EXCEPTION 'Generated key length mismatch. Expected %, got %', length, pg_catalog.char_length(generated_key);
    END IF;

    RETURN generated_key;
END;
$$;


--
-- Name: generate_workspace_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_workspace_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    new_code TEXT;
    is_unique BOOLEAN DEFAULT FALSE;
BEGIN
    WHILE NOT is_unique LOOP
        new_code := '';
        FOR i IN 1..4 LOOP
            new_code := new_code || substr(chars, floor(random() * length(chars) + 1)::int, 1);
        END LOOP;
        new_code := new_code || '-';
        FOR i IN 1..4 LOOP
            new_code := new_code || substr(chars, floor(random() * length(chars) + 1)::int, 1);
        END LOOP;
        
        SELECT NOT EXISTS (SELECT 1 FROM public.workspaces WHERE code = new_code) INTO is_unique;
    END LOOP;
    RETURN new_code;
END;
$$;


--
-- Name: get_active_discounts_for_marketplace_storage("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_active_discounts_for_marketplace_storage"("p_workspace_id" "uuid", "p_storage_id" "uuid") RETURNS TABLE("product_id" "uuid", "discount_type" "text", "discount_value" numeric, "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "min_stock_threshold" integer, "source" "text", "is_stock_ok" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_workspace_id IS NULL OR p_storage_id IS NULL THEN
    RETURN;
  END IF;

  IF auth.role() = 'authenticated' AND p_workspace_id IS DISTINCT FROM public.current_workspace_id() THEN
    RAISE EXCEPTION 'Workspace access denied';
  END IF;

  RETURN QUERY
  WITH stock_totals AS (
    SELECT
      inventory.product_id,
      COALESCE(SUM(inventory.quantity), 0)::integer AS total_stock
    FROM public.inventory
    WHERE inventory.workspace_id = p_workspace_id
      AND inventory.storage_id = p_storage_id
      AND COALESCE(inventory.is_deleted, false) = false
    GROUP BY inventory.product_id
  ),
  active_product_discounts AS (
    SELECT
      pd.product_id,
      pd.discount_type,
      pd.discount_value,
      pd.starts_at,
      pd.ends_at,
      pd.min_stock_threshold,
      'product'::text AS source,
      ROW_NUMBER() OVER (
        PARTITION BY pd.product_id
        ORDER BY pd.starts_at DESC, pd.created_at DESC, pd.id DESC
      ) AS rn
    FROM public.product_discounts pd
    JOIN public.products p
      ON p.id = pd.product_id
     AND p.workspace_id = p_workspace_id
     AND COALESCE(p.is_deleted, false) = false
    WHERE pd.workspace_id = p_workspace_id
      AND COALESCE(pd.is_deleted, false) = false
      AND pd.is_active = true
      AND pd.starts_at <= timezone('utc', now())
      AND pd.ends_at >= timezone('utc', now())
  ),
  active_category_discounts AS (
    SELECT
      p.id AS product_id,
      cd.discount_type,
      cd.discount_value,
      cd.starts_at,
      cd.ends_at,
      cd.min_stock_threshold,
      'category'::text AS source,
      ROW_NUMBER() OVER (
        PARTITION BY p.id
        ORDER BY cd.starts_at DESC, cd.created_at DESC, cd.id DESC
      ) AS rn
    FROM public.category_discounts cd
    JOIN public.products p
      ON p.category_id = cd.category_id
     AND p.workspace_id = p_workspace_id
     AND COALESCE(p.is_deleted, false) = false
    WHERE cd.workspace_id = p_workspace_id
      AND COALESCE(cd.is_deleted, false) = false
      AND cd.is_active = true
      AND cd.starts_at <= timezone('utc', now())
      AND cd.ends_at >= timezone('utc', now())
  ),
  resolved_discounts AS (
    SELECT
      apd.product_id,
      apd.discount_type,
      apd.discount_value,
      apd.starts_at,
      apd.ends_at,
      apd.min_stock_threshold,
      apd.source
    FROM active_product_discounts apd
    WHERE apd.rn = 1

    UNION ALL

    SELECT
      acd.product_id,
      acd.discount_type,
      acd.discount_value,
      acd.starts_at,
      acd.ends_at,
      acd.min_stock_threshold,
      acd.source
    FROM active_category_discounts acd
    WHERE acd.rn = 1
      AND NOT EXISTS (
        SELECT 1
        FROM active_product_discounts apd
        WHERE apd.product_id = acd.product_id
          AND apd.rn = 1
      )
  )
  SELECT
    rd.product_id,
    rd.discount_type,
    rd.discount_value,
    rd.starts_at,
    rd.ends_at,
    rd.min_stock_threshold,
    rd.source,
    CASE
      WHEN rd.min_stock_threshold IS NULL THEN true
      ELSE COALESCE(st.total_stock, 0) >= rd.min_stock_threshold
    END AS is_stock_ok
  FROM resolved_discounts rd
  LEFT JOIN stock_totals st
    ON st.product_id = rd.product_id;
END;
$$;


--
-- Name: get_active_discounts_for_workspace("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_active_discounts_for_workspace"("p_workspace_id" "uuid") RETURNS TABLE("product_id" "uuid", "discount_type" "text", "discount_value" numeric, "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "min_stock_threshold" integer, "source" "text", "is_stock_ok" boolean)
