      cd.min_stock_threshold,
      'category'::text AS source,
      ROW_NUMBER() OVER (
        PARTITION BY p.id
        ORDER BY cd.starts_at DESC, cd.created_at DESC, cd.id DESC
      ) AS rn
    FROM public.category_discounts cd
    JOIN public.products p
      ON p.category_id = cd.category_id
     AND p.workspace_id = p_workspace_id
     AND COALESCE(p.is_deleted, false) = false
    WHERE cd.workspace_id = p_workspace_id
      AND COALESCE(cd.is_deleted, false) = false
      AND cd.is_active = true
      AND cd.starts_at <= timezone('utc', now())
      AND cd.ends_at >= timezone('utc', now())
  ),
  resolved_discounts AS (
    SELECT
      apd.product_id,
      apd.discount_type,
      apd.discount_value,
      apd.starts_at,
      apd.ends_at,
      apd.min_stock_threshold,
      apd.source
    FROM active_product_discounts apd
    WHERE apd.rn = 1

    UNION ALL

    SELECT
      acd.product_id,
      acd.discount_type,
      acd.discount_value,
      acd.starts_at,
      acd.ends_at,
      acd.min_stock_threshold,
      acd.source
    FROM active_category_discounts acd
    WHERE acd.rn = 1
      AND NOT EXISTS (
        SELECT 1
        FROM active_product_discounts apd
        WHERE apd.product_id = acd.product_id
          AND apd.rn = 1
      )
  )
  SELECT
    rd.product_id,
    rd.discount_type,
    rd.discount_value,
    rd.starts_at,
    rd.ends_at,
    rd.min_stock_threshold,
    rd.source,
    CASE
      WHEN rd.min_stock_threshold IS NULL THEN true
      ELSE COALESCE(st.total_stock, 0) >= rd.min_stock_threshold
    END AS is_stock_ok
  FROM resolved_discounts rd
  LEFT JOIN stock_totals st
    ON st.product_id = rd.product_id;
END;
$$;


--
-- Name: get_auth_data(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_auth_data"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result json;
BEGIN
  SELECT json_build_object(
    'users', (SELECT json_agg(u) FROM auth.users u),
    'identities', (SELECT json_agg(i) FROM auth.identities i)
  ) INTO result;
  RETURN result;
END;
$$;


--
-- Name: get_net_revenue("uuid", timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_net_revenue"("p_workspace_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("total_revenue" numeric, "total_cost" numeric, "net_profit" numeric, "total_sales_count" bigint, "total_items_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF p_workspace_id IS NULL THEN
    SELECT workspace_id
    INTO p_workspace_id
    FROM public.profiles
    WHERE id = auth.uid();
  END IF;

  RETURN QUERY
  SELECT
    COALESCE(SUM((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)), 0),
    COALESCE(SUM((si.quantity - si.returned_quantity) * COALESCE(si.converted_cost_price, si.cost_price)), 0),
    COALESCE(SUM(
      ((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price))
      - ((si.quantity - si.returned_quantity) * COALESCE(si.converted_cost_price, si.cost_price))
    ), 0),
    COUNT(DISTINCT s.id),
    SUM(si.quantity - si.returned_quantity)
  FROM public.sales AS s
  INNER JOIN public.sale_items AS si ON s.id = si.sale_id
  WHERE s.workspace_id = p_workspace_id
    AND COALESCE(s.is_returned, false) = false
    AND (p_start_date IS NULL OR s.created_at >= p_start_date)
    AND (p_end_date IS NULL OR s.created_at <= p_end_date);
END;
$$;


--
-- Name: get_pending_notification_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_pending_notification_events"() RETURNS TABLE("id" "uuid", "workspace_id" "uuid", "user_id" "uuid", "status" "text", "entity_type" "text", "entity_id" "text", "attempt_count" integer, "payload" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'notifications', 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
      e.id,
      e.workspace_id,
      e.user_id,
      e.status::TEXT,
      e.entity_type::TEXT,
      e.entity_id,
      e.attempt_count,
      e.payload,
      e.created_at
    FROM notifications.events e
    WHERE e.status = 'pending'
    ORDER BY e.created_at ASC
    LIMIT 100;
END;
$$;


--
-- Name: get_pending_push_notification_targets(integer, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_pending_push_notification_targets"("p_limit" integer DEFAULT 100, "p_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("notification_id" "uuid", "workspace_id" "uuid", "user_id" "uuid", "notification_type" "text", "title" "text", "body" "text", "action_url" "text", "payload" "jsonb", "created_at" timestamp with time zone, "token_id" "uuid", "device_token" "text", "platform" "text", "language" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
  WITH pending_notifications AS (
    SELECT
      n.id,
      n.workspace_id,
      n.user_id,
      n.notification_type,
      n.title,
      n.body,
      n.action_url,
      n.payload,
      n.created_at
    FROM notifications.inbox n
    WHERE n.push_status = 'pending'
      AND n.archived_at IS NULL
      AND (p_workspace_id IS NULL OR n.workspace_id = p_workspace_id)
    ORDER BY n.created_at ASC, n.id ASC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500)
  )
  SELECT
    pn.id,
    pn.workspace_id,
    pn.user_id,
    pn.notification_type,
    pn.title,
    pn.body,
    pn.action_url,
    pn.payload,
    pn.created_at,
    dt.id,
    dt.device_token,
    dt.platform,
    dt.language
  FROM pending_notifications pn
  LEFT JOIN notifications.device_tokens dt
    ON dt.user_id = pn.user_id
   AND dt.workspace_id = pn.workspace_id
  ORDER BY pn.created_at ASC, pn.id ASC, dt.updated_at DESC NULLS LAST, dt.id ASC;
$$;


--
-- Name: get_sales_summary("uuid", timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_sales_summary"("p_workspace_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  IF p_workspace_id IS NULL THEN
    SELECT workspace_id
    INTO p_workspace_id
    FROM public.profiles
    WHERE id = auth.uid();
  END IF;

  SELECT jsonb_build_object(
    'totalRevenue', COALESCE(SUM(CASE WHEN COALESCE(s.is_returned, false) = false THEN (si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price) ELSE 0 END), 0),
    'totalCost', COALESCE(SUM(CASE WHEN COALESCE(s.is_returned, false) = false THEN (si.quantity - si.returned_quantity) * COALESCE(si.converted_cost_price, si.cost_price) ELSE 0 END), 0),
    'netProfit', COALESCE(SUM(CASE WHEN COALESCE(s.is_returned, false) = false THEN ((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)) - ((si.quantity - si.returned_quantity) * COALESCE(si.converted_cost_price, si.cost_price)) ELSE 0 END), 0),
    'totalSales', COUNT(DISTINCT CASE WHEN COALESCE(s.is_returned, false) = false THEN s.id END),
    'totalItems', SUM(CASE WHEN COALESCE(s.is_returned, false) = false THEN si.quantity - si.returned_quantity ELSE 0 END),
    'averageSaleValue', COALESCE(AVG(CASE WHEN COALESCE(s.is_returned, false) = false THEN s.total_amount END), 0),
    'returnedSales', COUNT(DISTINCT CASE WHEN s.is_returned = true THEN s.id END),
    'returnedItems', SUM(si.returned_quantity)
  )
  INTO result
  FROM public.sales AS s
  INNER JOIN public.sale_items AS si ON s.id = si.sale_id
  WHERE s.workspace_id = p_workspace_id
    AND (p_start_date IS NULL OR s.created_at >= p_start_date)
    AND (p_end_date IS NULL OR s.created_at <= p_end_date);

  RETURN result;
END;
$$;


--
-- Name: get_team_performance("uuid", timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_team_performance"("p_workspace_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("cashier_id" "uuid", "cashier_name" "text", "total_sales_count" bigint, "total_revenue" numeric, "total_items_count" bigint, "average_sale_value" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF p_workspace_id IS NULL THEN
        SELECT current_workspace INTO p_workspace_id FROM public.profiles WHERE id = auth.uid();
    END IF;

    RETURN QUERY
    SELECT 
        s.cashier_id,
        COALESCE(p.name, 'Unknown') as cashier_name,
        COUNT(DISTINCT s.id) as total_sales_count,
        COALESCE(SUM((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)), 0) as total_revenue,
        SUM(si.quantity - si.returned_quantity) as total_items_count,
        COALESCE(AVG(s.total_amount), 0) as average_sale_value
    FROM public.sales s
    INNER JOIN public.sale_items si ON s.id = si.sale_id
    LEFT JOIN public.profiles p ON s.cashier_id = p.id
    WHERE s.workspace_id = p_workspace_id
      AND COALESCE(s.is_returned, FALSE) = FALSE
      AND (p_start_date IS NULL OR s.created_at >= p_start_date)
      AND (p_end_date IS NULL OR s.created_at <= p_end_date)
    GROUP BY s.cashier_id, p.name
    ORDER BY total_revenue DESC;
END;
$$;


--
-- Name: get_top_products("uuid", timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_top_products"("p_workspace_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 10) RETURNS TABLE("product_id" "uuid", "product_name" "text", "product_sku" "text", "total_quantity_sold" bigint, "total_revenue" numeric, "total_sales_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF p_workspace_id IS NULL THEN
        SELECT current_workspace INTO p_workspace_id FROM public.profiles WHERE id = auth.uid();
    END IF;

    RETURN QUERY
    SELECT 
        pr.id as product_id,
        pr.name as product_name,
        pr.sku as product_sku,
        SUM(si.quantity - si.returned_quantity) as total_quantity_sold,
        COALESCE(SUM((si.quantity - si.returned_quantity) * COALESCE(si.converted_unit_price, si.unit_price)), 0) as total_revenue,
        COUNT(DISTINCT si.sale_id) as total_sales_count
    FROM public.sale_items si
    INNER JOIN public.sales s ON si.sale_id = s.id
    INNER JOIN public.products pr ON si.product_id = pr.id
    WHERE s.workspace_id = p_workspace_id
      AND COALESCE(s.is_returned, FALSE) = FALSE
      AND (p_start_date IS NULL OR s.created_at >= p_start_date)
      AND (p_end_date IS NULL OR s.created_at <= p_end_date)
    GROUP BY pr.id, pr.name, pr.sku
    ORDER BY total_quantity_sold DESC
    LIMIT p_limit;
END;
$$;


--
-- Name: handle_inventory_snapshot_refresh(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_inventory_snapshot_refresh"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM public.refresh_product_inventory_snapshot(OLD.product_id);
        RETURN OLD;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.product_id IS DISTINCT FROM OLD.product_id THEN
        PERFORM public.refresh_product_inventory_snapshot(OLD.product_id);
    END IF;

    PERFORM public.refresh_product_inventory_snapshot(NEW.product_id);
    RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  raw_ws_id text;
  valid_ws_id uuid;
BEGIN
  raw_ws_id := NEW.raw_user_meta_data->>'workspace_id';

  IF raw_ws_id IS NOT NULL AND raw_ws_id <> '' THEN
    BEGIN
      valid_ws_id := raw_ws_id::uuid;
    EXCEPTION WHEN OTHERS THEN
      valid_ws_id := NULL;
    END;
  ELSE
    valid_ws_id := NULL;
  END IF;

  VALUES (
    NEW.id,
    NEW.raw_user_meta_data->>'name',
    NEW.raw_user_meta_data->>'role',
    valid_ws_id,
    valid_ws_id
  );

  RETURN NEW;
END;
$$;


--
-- Name: increment_custom_template_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."increment_custom_template_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF (
    OLD.layout_json IS DISTINCT FROM NEW.layout_json
    OR OLD.label IS DISTINCT FROM NEW.label
  ) THEN
    NEW.version = OLD.version + 1;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: increment_sales_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."increment_sales_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.version = OLD.version + 1;
  RETURN NEW;
END;
$$;


--
-- Name: insert_demo("uuid", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."insert_demo"("p_workspace_id" "uuid", "p_expires_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
