--
-- Name: list_notifications_inbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_notifications_inbox"("p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "event_id" "uuid", "workspace_id" "uuid", "user_id" "uuid", "notification_type" "text", "scope" "text", "priority" "text", "dedupe_key" "text", "title" "text", "body" "text", "action_url" "text", "action_label" "text", "payload" "jsonb", "read_at" timestamp with time zone, "archived_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
  SELECT
    n.id,
    n.event_id,
    n.workspace_id,
    n.user_id,
    n.notification_type,
    n.scope,
    n.priority,
    n.dedupe_key,
    n.title,
    n.body,
    n.action_url,
    n.action_label,
    n.payload,
    n.read_at,
    n.archived_at,
    n.created_at,
    n.updated_at
  FROM notifications.inbox n
  WHERE n.user_id = auth.uid()
    AND n.workspace_id = public.current_workspace_id()
  ORDER BY n.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500);
$$;


--
-- Name: lookup_workspace_by_code("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."lookup_workspace_by_code"("p_code" "text") RETURNS TABLE("id" "uuid", "name" "text", "code" "text", "plan" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT w.id, w.name, w.code, public.normalize_workspace_plan(w.plan) AS plan
  FROM public.workspaces w
  WHERE w.code = UPPER(TRIM(COALESCE(p_code, '')))
    AND w.deleted_at IS NULL
  LIMIT 1;
$$;


--
-- Name: mark_all_notifications_inbox_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mark_all_notifications_inbox_read"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
DECLARE
  v_updated_count integer := 0;
BEGIN
  WITH updated_rows AS (
    UPDATE notifications.inbox
    SET read_at = COALESCE(read_at, now()),
        updated_at = now()
    WHERE user_id = auth.uid()
      AND workspace_id = public.current_workspace_id()
      AND archived_at IS NULL
      AND read_at IS NULL
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_updated_count
  FROM updated_rows;

  RETURN COALESCE(v_updated_count, 0);
END;
$$;


--
-- Name: mark_notification_inbox_archived("uuid", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mark_notification_inbox_archived"("p_notification_id" "uuid", "p_archived" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
BEGIN
  UPDATE notifications.inbox
  SET archived_at = CASE
      WHEN COALESCE(p_archived, true) THEN COALESCE(archived_at, now())
      ELSE NULL
    END,
    updated_at = now()
  WHERE id = p_notification_id
    AND user_id = auth.uid()
    AND workspace_id = public.current_workspace_id();

  RETURN FOUND;
END;
$$;


--
-- Name: mark_notification_inbox_read("uuid", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mark_notification_inbox_read"("p_notification_id" "uuid", "p_read" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
BEGIN
  UPDATE notifications.inbox
  SET read_at = CASE
      WHEN COALESCE(p_read, true) THEN COALESCE(read_at, now())
      ELSE NULL
    END,
    updated_at = now()
  WHERE id = p_notification_id
    AND user_id = auth.uid()
    AND workspace_id = public.current_workspace_id();

  RETURN FOUND;
END;
$$;


--
-- Name: migrate_products_to_main_storage("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."migrate_products_to_main_storage"("p_workspace_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_main_storage_id uuid;
BEGIN
        workspace_id,
        name,
        is_system,
        is_protected,
        is_primary,
        created_at,
        updated_at,
        is_deleted
    )
    SELECT
        p_workspace_id,
        'Main',
        true,
        true,
        true,
        timezone('utc', now()),
        timezone('utc', now()),
        false
    WHERE NOT EXISTS (
        SELECT 1
        FROM public.storages
        WHERE workspace_id = p_workspace_id
          AND LOWER(name) = 'main'
          AND COALESCE(is_deleted, false) = false
    );

    SELECT id
    INTO v_main_storage_id
    FROM public.storages
    WHERE workspace_id = p_workspace_id
      AND LOWER(name) = 'main'
      AND COALESCE(is_deleted, false) = false
    ORDER BY created_at NULLS LAST, id
    LIMIT 1;

    UPDATE public.storages
    SET
        is_primary = (id = v_main_storage_id),
        updated_at = CASE
            WHEN id = v_main_storage_id AND COALESCE(is_primary, false) = false THEN timezone('utc', now())
            ELSE updated_at
        END
    WHERE workspace_id = p_workspace_id
      AND COALESCE(is_deleted, false) = false
      AND COALESCE(is_primary, false) IS DISTINCT FROM (id = v_main_storage_id);

        id,
        workspace_id,
        product_id,
        storage_id,
        quantity,
        created_at,
        updated_at,
        version,
        is_deleted
    )
    SELECT
        gen_random_uuid(),
        p.workspace_id,
        p.id,
        COALESCE(p.storage_id, v_main_storage_id),
        COALESCE(p.quantity, 0),
        COALESCE(p.created_at, timezone('utc', now())),
        COALESCE(p.updated_at, timezone('utc', now())),
        GREATEST(COALESCE(p.version, 1), 1),
        false
    FROM public.products p
    WHERE p.workspace_id = p_workspace_id
      AND COALESCE(p.is_deleted, false) = false
      AND COALESCE(p.quantity, 0) > 0
      AND COALESCE(p.storage_id, v_main_storage_id) IS NOT NULL
    ON CONFLICT (workspace_id, product_id, storage_id) DO UPDATE
    SET
        quantity = EXCLUDED.quantity,
        updated_at = EXCLUDED.updated_at,
        version = GREATEST(public.inventory.version, EXCLUDED.version),
        is_deleted = false;

    UPDATE public.products
    SET
        storage_id = COALESCE(storage_id, v_main_storage_id),
        updated_at = timezone('utc', now())
    WHERE workspace_id = p_workspace_id
      AND COALESCE(is_deleted, false) = false
      AND COALESCE(quantity, 0) > 0
      AND storage_id IS NULL
      AND v_main_storage_id IS NOT NULL;
END;
$$;


--
-- Name: normalize_custom_template_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."normalize_custom_template_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND (OLD.workspace_id <> NEW.workspace_id OR OLD.module_type_key <> NEW.module_type_key) THEN
    RAISE EXCEPTION 'A custom template cannot be moved to another workspace or module type';
  END IF;

  IF NOT NEW.active THEN
    NEW."primary" := false;

    IF TG_OP = 'INSERT'
       AND NOT EXISTS (
         SELECT 1
         FROM public.custom_templates candidate
         WHERE candidate.workspace_id = NEW.workspace_id
           AND candidate.module_type_key = NEW.module_type_key
           AND candidate."primary"
       ) THEN
      RAISE EXCEPTION 'The first custom template for a module type must be active';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD."primary"
     AND NOT NEW.active
     AND NOT EXISTS (
       SELECT 1
       FROM public.custom_templates candidate
       WHERE candidate.workspace_id = NEW.workspace_id
         AND candidate.module_type_key = NEW.module_type_key
         AND candidate.id <> NEW.id
         AND candidate.active
     ) THEN
    RAISE EXCEPTION 'A primary custom template cannot be deactivated without another active template';
  END IF;

  IF pg_trigger_depth() = 1
     AND NEW.active
     AND NOT NEW."primary"
     AND NOT EXISTS (
       SELECT 1
       FROM public.custom_templates candidate
       WHERE candidate.workspace_id = NEW.workspace_id
         AND candidate.module_type_key = NEW.module_type_key
         AND candidate.id <> NEW.id
         AND candidate."primary"
     ) THEN
    NEW."primary" := true;
  END IF;

  IF NEW."primary" AND pg_trigger_depth() = 1 THEN
    UPDATE public.custom_templates
    SET "primary" = false
    WHERE workspace_id = NEW.workspace_id
      AND module_type_key = NEW.module_type_key
      AND id <> NEW.id
      AND "primary";
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: normalize_marketplace_storage_selection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."normalize_marketplace_storage_selection"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.is_deleted, false) THEN
    NEW.is_marketplace := false;
  END IF;

  IF COALESCE(NEW.is_marketplace, false) THEN
    UPDATE public.storages
    SET
      is_marketplace = false,
      updated_at = CASE
        WHEN COALESCE(is_marketplace, false) = true THEN timezone('utc', now())
        ELSE updated_at
      END
    WHERE workspace_id = NEW.workspace_id
      AND id IS DISTINCT FROM NEW.id
      AND COALESCE(is_deleted, false) = false
      AND COALESCE(is_marketplace, false) = true;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: normalize_marketplace_workspace_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."normalize_marketplace_workspace_settings"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.visibility := COALESCE(NULLIF(lower(trim(COALESCE(NEW.visibility, 'private'))), ''), 'private');
  NEW.store_slug := NULLIF(lower(trim(COALESCE(NEW.store_slug, ''))), '');
  NEW.store_description := NULLIF(trim(COALESCE(NEW.store_description, '')), '');
  IF NEW.visibility NOT IN ('private', 'public') THEN
    RAISE EXCEPTION 'Workspace visibility must be private or public';
  END IF;
  IF NEW.visibility = 'public' AND NEW.deleted_at IS NULL THEN
    IF COALESCE(NEW.data_mode, 'cloud') = 'local' THEN
      RAISE EXCEPTION 'Local workspaces cannot be published to the marketplace';
    END IF;
    IF NEW.store_slug IS NULL THEN
      RAISE EXCEPTION 'A store slug is required before a workspace can be published';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: normalize_workspace_plan("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."normalize_workspace_plan"("p_plan" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN lower(coalesce(p_plan, '')) IN ('basic', 'business', 'enterprise')
      THEN lower(p_plan)
    ELSE 'basic'
  END;
$$;


--
-- Name: normalize_workspace_plan("public"."workspace_plan_type"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."normalize_workspace_plan"("p_plan" "public"."workspace_plan_type") RETURNS "public"."workspace_plan_type"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT p_plan;
$$;


--
-- Name: prevent_demo_business_data_writes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_demo_business_data_writes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_workspace_id uuid;
  target_data_mode text;
  request_role text := current_setting('request.jwt.claim.role', true);
BEGIN
  IF request_role IS DISTINCT FROM 'authenticated' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  target_workspace_id := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.workspace_id
    ELSE NEW.workspace_id
  END;

  IF target_workspace_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  SELECT data_mode
  INTO target_data_mode
  FROM public.workspaces
  WHERE id = target_workspace_id;

  IF target_data_mode = 'demo' THEN
    RAISE EXCEPTION 'Demo business data is local-only';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_demo_profile_client_updates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_demo_profile_client_updates"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_workspace_id uuid;
  target_data_mode text;
  request_role text := current_setting('request.jwt.claim.role', true);
BEGIN
  IF request_role <> 'authenticated' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  target_workspace_id := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.workspace_id
    ELSE NEW.workspace_id
  END;

  SELECT data_mode
  INTO target_data_mode
  FROM public.workspaces
  WHERE id = target_workspace_id;

  IF target_data_mode = 'demo' THEN
    RAISE EXCEPTION 'Demo profile settings are local-only';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_demo_workspace_client_updates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_demo_workspace_client_updates"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  request_role text := current_setting('request.jwt.claim.role', true);
BEGIN
  IF request_role = 'authenticated'
    AND COALESCE(OLD.data_mode, 'cloud') = 'demo' THEN
    RAISE EXCEPTION 'Demo workspace settings are local-only';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_restricted_workspace_client_updates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_restricted_workspace_client_updates"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  request_role text := current_setting('request.jwt.claim.role', true);
BEGIN
  IF request_role = 'authenticated' THEN
    IF NEW.code IS DISTINCT FROM OLD.code
      OR NEW.created_at IS DISTINCT FROM OLD.created_at
      OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
      OR NEW.locked_workspace IS DISTINCT FROM OLD.locked_workspace
      OR NEW.subscription_expires_at IS DISTINCT FROM OLD.subscription_expires_at
      OR COALESCE(NEW.member_count, 0) IS DISTINCT FROM COALESCE(OLD.member_count, 0) THEN
      RAISE EXCEPTION 'Restricted workspace fields cannot be updated from the client';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_workspace_mode_switch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_workspace_mode_switch"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.data_mode IS DISTINCT FROM OLD.data_mode AND COALESCE(OLD.is_configured, false) THEN
    IF COALESCE(OLD.data_mode::text, 'cloud') = 'local' OR COALESCE(NEW.data_mode::text, 'cloud') = 'local' THEN
      RAISE EXCEPTION 'Workspace mode cannot enter or leave local mode after initial configuration';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: process_sale_return("uuid", "uuid", "jsonb", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."process_sale_return"("p_return_id" "uuid", "p_sale_id" "uuid", "p_items" "jsonb", "p_return_reason" "text", "p_refund_method" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_sale_record RECORD;
  v_existing_return RECORD;
  v_item_record RECORD;
  v_item_payload jsonb;
  v_batch_allocation jsonb;
  v_target_batch_record RECORD;
  v_workspace_id uuid;
  v_user_role text;
  v_plan text;
  v_pos boolean;
  v_requested_quantity integer;
  v_return_quantity integer;
  v_storage_id uuid;
  v_primary_storage_id uuid;
  v_original_storage_missing boolean := false;
  v_total_return_value numeric := 0;
  v_unit_refund_amount numeric := 0;
  v_line_refund_amount numeric := 0;
  v_sale_fully_returned boolean := false;
  v_processed_items integer := 0;
  v_existing_batch_allocations jsonb := '[]'::jsonb;
  v_remaining_batch_allocations jsonb := '[]'::jsonb;
  v_restored_batch_allocations jsonb := '[]'::jsonb;
  v_remaining_to_restore integer := 0;
  v_batch_quantity integer := 0;
  v_restore_quantity integer := 0;
  v_leftover_batch_quantity integer := 0;
  v_batch_id uuid;
  v_restored_batch_id uuid;
  v_batch_number text;
  v_batch_price numeric;
  v_batch_cost_price numeric;
  v_batch_currency text;
  v_batch_expiry_date date;
  v_batch_manufacturing_date date;
  v_new_batch_id uuid;
  v_line_id uuid;
  v_return_lines jsonb := '[]'::jsonb;
BEGIN
  IF p_return_id IS NULL THEN
    RAISE EXCEPTION 'Return ID is required';
  END IF;

  IF p_sale_id IS NULL THEN
    RAISE EXCEPTION 'Sale ID is required';
  END IF;

  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'At least one return item is required';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM (
      SELECT value->>'sale_item_id' AS sale_item_id, COUNT(*) AS item_count
      FROM jsonb_array_elements(p_items)
      GROUP BY value->>'sale_item_id'
    ) duplicate_items
    WHERE duplicate_items.sale_item_id IS NULL
       OR duplicate_items.item_count > 1
  ) THEN
    RAISE EXCEPTION 'Return items must contain unique sale item IDs';
  END IF;

  SELECT *
  INTO v_sale_record
  FROM public.sales
  WHERE id = p_sale_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sale not found';
  END IF;

  v_workspace_id := v_sale_record.workspace_id;

  SELECT role
  INTO v_user_role
  FROM public.profiles
  WHERE id = auth.uid()
    AND workspace_id = v_workspace_id;

  IF v_user_role NOT IN ('admin', 'staff') THEN
    RAISE EXCEPTION 'Unauthorized: Only admins and staff can return items';
  END IF;

  SELECT plan
  INTO v_plan
  FROM public.workspaces
  WHERE id = v_workspace_id;

  v_pos := public.workspace_module_allowed(v_workspace_id, v_plan, 'pos');

  IF NOT COALESCE(v_pos, false) THEN
    RAISE EXCEPTION 'POS feature is not enabled for this workspace';
  END IF;

  SELECT *
  INTO v_existing_return
  FROM public.sale_returns
  WHERE id = p_return_id;

  IF FOUND THEN
    IF v_existing_return.sale_id IS DISTINCT FROM p_sale_id
       OR v_existing_return.workspace_id IS DISTINCT FROM v_workspace_id THEN
      RAISE EXCEPTION 'Return ID is already assigned to another sale';
    END IF;

    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', sri.id,
          'sale_item_id', sri.sale_item_id,
          'quantity', sri.quantity,
          'refund_amount', sri.refund_amount,
          'restored_storage_id', sri.restored_storage_id,
          'restored_batch_allocations', sri.restored_batch_allocations
        )
        ORDER BY sri.created_at, sri.id
      ),
      '[]'::jsonb
    )
    INTO v_return_lines
    FROM public.sale_return_items sri
    WHERE sri.return_id = p_return_id;

    RETURN jsonb_build_object(
      'success', true,
      'message', 'Return already processed',
      'return_id', p_return_id,
      'return_value', v_existing_return.refund_amount,
      'items', v_return_lines,
      'idempotent_replay', true
    );
  END IF;

  v_primary_storage_id := public.ensure_primary_storage(v_workspace_id);

    id,
    workspace_id,
    sale_id,
    reason,
    status,
    refund_method,
    refund_amount,
    returned_by,
    returned_at,
    source,
    created_at,
    updated_at
  )
  VALUES (
    p_return_id,
    v_workspace_id,
    p_sale_id,
    COALESCE(NULLIF(BTRIM(p_return_reason), ''), 'Return'),
    'posted',
    NULLIF(BTRIM(p_refund_method), ''),
    0,
    auth.uid(),
    now(),
    'app',
    now(),
    timezone('utc', now())
  );

  FOR v_item_payload IN
    SELECT value
    FROM jsonb_array_elements(p_items)
  LOOP
    SELECT si.*
    INTO v_item_record
    FROM public.sale_items si
    WHERE si.id = NULLIF(v_item_payload->>'sale_item_id', '')::uuid
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Sale item not found';
    END IF;

    IF v_item_record.sale_id IS DISTINCT FROM p_sale_id THEN
      RAISE EXCEPTION 'Selected sale items must belong to the requested sale';
    END IF;

    v_requested_quantity := COALESCE((v_item_payload->>'quantity')::integer, 0);

    IF v_requested_quantity <= 0 THEN
      RAISE EXCEPTION 'Return quantity must be greater than zero';
    END IF;

    IF v_requested_quantity > (
      v_item_record.quantity - COALESCE(v_item_record.returned_quantity, 0)
    ) THEN
      RAISE EXCEPTION 'Return quantity exceeds the remaining quantity for sale item %', v_item_record.id;
    END IF;

    v_return_quantity := v_requested_quantity;
    v_storage_id := v_item_record.storage_id;
    v_original_storage_missing := false;

    IF v_storage_id IS NOT NULL THEN
      PERFORM 1
      FROM public.storages
      WHERE id = v_storage_id
        AND workspace_id = v_workspace_id
        AND COALESCE(is_deleted, false) = false;

      IF NOT FOUND THEN
        v_original_storage_missing := true;
        v_storage_id := v_primary_storage_id;
      END IF;
    END IF;

    IF v_storage_id IS NULL THEN
      SELECT CASE WHEN COUNT(*) = 1 THEN MIN(i.storage_id::text)::uuid ELSE NULL END
      INTO v_storage_id
      FROM public.inventory i
      JOIN public.storages st
        ON st.id = i.storage_id
       AND st.workspace_id = v_workspace_id
       AND COALESCE(st.is_deleted, false) = false
      WHERE i.workspace_id = v_workspace_id
        AND i.product_id = v_item_record.product_id
        AND COALESCE(i.is_deleted, false) = false;
    END IF;

    IF v_storage_id IS NULL THEN
      SELECT p.storage_id
      INTO v_storage_id
      FROM public.products p
      JOIN public.storages st
        ON st.id = p.storage_id
       AND st.workspace_id = v_workspace_id
       AND COALESCE(st.is_deleted, false) = false
      WHERE p.id = v_item_record.product_id
        AND p.workspace_id = v_workspace_id;
    END IF;

    IF v_storage_id IS NULL THEN
      v_storage_id := v_primary_storage_id;
    END IF;

    IF v_storage_id IS NULL THEN
      RAISE EXCEPTION 'Storage not found for returned product %', v_item_record.product_id;
    END IF;

      id,
      workspace_id,
      product_id,
      storage_id,
      quantity,
      created_at,
      updated_at,
      version,
      is_deleted
    )
    VALUES (
      gen_random_uuid(),
      v_workspace_id,
      v_item_record.product_id,
      v_storage_id,
      v_return_quantity,
      now(),
      now(),
      1,
      false
    )
    ON CONFLICT (workspace_id, product_id, storage_id) DO UPDATE
    SET
      quantity = public.inventory.quantity + EXCLUDED.quantity,
      updated_at = now(),
      version = COALESCE(public.inventory.version, 0) + 1,
      is_deleted = false;

    v_existing_batch_allocations := CASE
      WHEN jsonb_typeof(v_item_record.batch_allocations) = 'array'
        THEN v_item_record.batch_allocations
      ELSE '[]'::jsonb
    END;
    v_remaining_batch_allocations := '[]'::jsonb;
    v_restored_batch_allocations := '[]'::jsonb;

    IF jsonb_array_length(v_existing_batch_allocations) > 0 THEN
      v_remaining_to_restore := v_return_quantity;

      FOR v_batch_allocation IN
        SELECT value
        FROM jsonb_array_elements(v_existing_batch_allocations)
      LOOP
        v_batch_quantity := COALESCE((v_batch_allocation->>'quantity')::integer, 0);
        v_restore_quantity := LEAST(v_remaining_to_restore, v_batch_quantity);
        v_leftover_batch_quantity := GREATEST(v_batch_quantity - v_restore_quantity, 0);
        v_batch_id := NULLIF(v_batch_allocation->>'batch_id', '')::uuid;
        v_batch_number := COALESCE(
          NULLIF(v_batch_allocation->>'batch_number', ''),
          'Restored Batch'
        );
        v_batch_price := NULLIF(v_batch_allocation->>'price', '')::numeric;
        v_batch_cost_price := NULLIF(v_batch_allocation->>'cost_price', '')::numeric;
        v_batch_currency := lower(
          COALESCE(NULLIF(v_batch_allocation->>'currency', ''), 'usd')
        );
        v_batch_expiry_date := NULLIF(v_batch_allocation->>'expiry_date', '')::date;
        v_batch_manufacturing_date := NULLIF(
          v_batch_allocation->>'manufacturing_date',
          ''
        )::date;
        v_target_batch_record := NULL;
        v_restored_batch_id := NULL;

        IF v_restore_quantity > 0 THEN
          IF v_batch_id IS NOT NULL THEN
            SELECT *
            INTO v_target_batch_record
            FROM public.stock_batches
            WHERE id = v_batch_id
              AND workspace_id = v_workspace_id
              AND product_id = v_item_record.product_id
              AND storage_id = v_storage_id
            FOR UPDATE;
          END IF;

          IF v_target_batch_record IS NULL THEN
            SELECT *
            INTO v_target_batch_record
            FROM public.stock_batches
            WHERE workspace_id = v_workspace_id
              AND product_id = v_item_record.product_id
              AND storage_id = v_storage_id
              AND lower(batch_number) = lower(v_batch_number)
            ORDER BY COALESCE(is_deleted, false) ASC, created_at ASC NULLS LAST, id ASC
            LIMIT 1
            FOR UPDATE;
          END IF;

          IF v_target_batch_record IS NOT NULL THEN
            v_restored_batch_id := v_target_batch_record.id;

            UPDATE public.stock_batches
            SET
              quantity = COALESCE(v_target_batch_record.quantity, 0) + v_restore_quantity,
              price = COALESCE(v_target_batch_record.price, v_batch_price),
              cost_price = COALESCE(v_target_batch_record.cost_price, v_batch_cost_price),
              currency = lower(COALESCE(v_target_batch_record.currency, v_batch_currency, 'usd')),
              expiry_date = COALESCE(v_target_batch_record.expiry_date, v_batch_expiry_date),
              manufacturing_date = COALESCE(
                v_target_batch_record.manufacturing_date,
                v_batch_manufacturing_date
              ),
              updated_at = now(),
              version = COALESCE(version, 0) + 1,
              is_deleted = false
            WHERE id = v_target_batch_record.id;
          ELSE
            v_new_batch_id := CASE
              WHEN v_batch_id IS NOT NULL
               AND NOT EXISTS (
                 SELECT 1
                 FROM public.stock_batches
                 WHERE id = v_batch_id
               )
                THEN v_batch_id
              ELSE gen_random_uuid()
            END;
            v_restored_batch_id := v_new_batch_id;

              id,
              workspace_id,
              product_id,
              storage_id,
              batch_number,
              quantity,
              price,
              cost_price,
              currency,
              expiry_date,
              manufacturing_date,
              created_at,
              updated_at,
              version,
              is_deleted
            )
            VALUES (
              v_new_batch_id,
              v_workspace_id,
              v_item_record.product_id,
              v_storage_id,
              v_batch_number,
              v_restore_quantity,
              v_batch_price,
              v_batch_cost_price,
              v_batch_currency,
              v_batch_expiry_date,
              v_batch_manufacturing_date,
              now(),
              now(),
              1,
              false
            );
          END IF;

          v_restored_batch_allocations := v_restored_batch_allocations || jsonb_build_array(
            jsonb_build_object(
              'batch_id', v_restored_batch_id,
              'batch_number', v_batch_number,
              'quantity', v_restore_quantity,
              'price', v_batch_price,
              'cost_price', v_batch_cost_price,
              'currency', v_batch_currency,
              'expiry_date', v_batch_expiry_date,
              'manufacturing_date', v_batch_manufacturing_date
            )
          );
        END IF;

        IF v_leftover_batch_quantity > 0 THEN
          v_remaining_batch_allocations := v_remaining_batch_allocations || jsonb_build_array(
            jsonb_build_object(
              'batch_id', v_batch_id,
              'batch_number', v_batch_number,
              'quantity', v_leftover_batch_quantity,
              'price', v_batch_price,
              'cost_price', v_batch_cost_price,
              'currency', v_batch_currency,
              'expiry_date', v_batch_expiry_date,
              'manufacturing_date', v_batch_manufacturing_date
            )
          );
        END IF;

        v_remaining_to_restore := v_remaining_to_restore - v_restore_quantity;
      END LOOP;

      IF v_remaining_to_restore > 0 THEN
        RAISE EXCEPTION 'Return quantity exceeds stored batch allocations for sale item %', v_item_record.id;
      END IF;
    END IF;

    v_unit_refund_amount := COALESCE(
      v_item_record.converted_unit_price,
      v_item_record.unit_price,
      0
    );
    v_line_refund_amount := v_return_quantity * v_unit_refund_amount;
    v_line_id := COALESCE(
      NULLIF(v_item_payload->>'id', '')::uuid,
      gen_random_uuid()
    );

      id,
      workspace_id,
      return_id,
      sale_id,
      sale_item_id,
      quantity,
      unit_refund_amount,
      refund_amount,
      restored_storage_id,
      restored_batch_allocations,
      created_at,
      updated_at
    )
    VALUES (
      v_line_id,
      v_workspace_id,
      p_return_id,
      p_sale_id,
      v_item_record.id,
      v_return_quantity,
      v_unit_refund_amount,
      v_line_refund_amount,
      v_storage_id,
      CASE
        WHEN jsonb_array_length(v_restored_batch_allocations) > 0
          THEN v_restored_batch_allocations
        ELSE NULL
      END,
      now(),
      timezone('utc', now())
    );

    UPDATE public.sale_items
    SET
      storage_id = CASE
        WHEN storage_id IS NULL OR v_original_storage_missing THEN v_storage_id
        ELSE storage_id
      END,
      original_batch_allocations = COALESCE(
        original_batch_allocations,
        v_item_record.batch_allocations
      ),
      returned_quantity = COALESCE(returned_quantity, 0) + v_return_quantity,
      is_returned = (
        COALESCE(returned_quantity, 0) + v_return_quantity
      ) >= quantity,
      return_reason = COALESCE(NULLIF(BTRIM(p_return_reason), ''), 'Return'),
      returned_at = now(),
      returned_by = auth.uid(),
      batch_allocations = CASE
        WHEN jsonb_array_length(v_remaining_batch_allocations) > 0
          THEN v_remaining_batch_allocations
        ELSE NULL
      END
    WHERE id = v_item_record.id;

    v_total_return_value := v_total_return_value + v_line_refund_amount;
    v_processed_items := v_processed_items + 1;
    v_return_lines := v_return_lines || jsonb_build_array(
      jsonb_build_object(
        'id', v_line_id,
        'sale_item_id', v_item_record.id,
        'quantity', v_return_quantity,
        'unit_refund_amount', v_unit_refund_amount,
        'refund_amount', v_line_refund_amount,
        'restored_storage_id', v_storage_id,
        'restored_batch_allocations', CASE
          WHEN jsonb_array_length(v_restored_batch_allocations) > 0
            THEN v_restored_batch_allocations
          ELSE NULL
        END
      )
    );
  END LOOP;

  IF v_processed_items = 0 THEN
    RAISE EXCEPTION 'No returnable items were processed';
  END IF;

  SELECT NOT EXISTS (
    SELECT 1
    FROM public.sale_items
    WHERE sale_id = p_sale_id
      AND COALESCE(returned_quantity, 0) < quantity
  )
  INTO v_sale_fully_returned;

  UPDATE public.sales
  SET
    original_total_amount = COALESCE(original_total_amount, total_amount, 0),
    total_amount = GREATEST(0, COALESCE(total_amount, 0) - v_total_return_value),
    returned_amount = COALESCE(returned_amount, 0) + v_total_return_value,
    return_status = CASE WHEN v_sale_fully_returned THEN 'full' ELSE 'partial' END,
    is_returned = v_sale_fully_returned,
    return_reason = CASE
      WHEN v_sale_fully_returned
        THEN COALESCE(NULLIF(BTRIM(p_return_reason), ''), 'Return')
      ELSE return_reason
    END,
    returned_at = CASE WHEN v_sale_fully_returned THEN now() ELSE returned_at END,
    returned_by = CASE WHEN v_sale_fully_returned THEN auth.uid() ELSE returned_by END,
    updated_at = timezone('utc', now())
  WHERE id = p_sale_id;

  UPDATE public.sale_returns
  SET
    refund_amount = v_total_return_value,
    updated_at = timezone('utc', now())
  WHERE id = p_return_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Items returned successfully',
    'return_id', p_return_id,
    'return_value', v_total_return_value,
    'items', v_return_lines,
    'idempotent_replay', false
  );
END;
$$;


--
-- Name: queue_marketplace_pending_order_notifications("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."queue_marketplace_pending_order_notifications"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
DECLARE
  v_order public.marketplace_orders%ROWTYPE;
  v_due_date date;
  v_item_count integer := 0;
BEGIN
  SELECT *
  INTO v_order
  FROM public.marketplace_orders
  WHERE id = p_order_id
    AND status = 'pending'
    AND COALESCE(is_deleted, false) = false;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_due_date := timezone('utc', v_order.created_at)::date;

  SELECT COALESCE(SUM(GREATEST(COALESCE((item.value ->> 'quantity')::integer, 1), 1)), 0)
  INTO v_item_count
  FROM jsonb_array_elements(COALESCE(v_order.items, '[]'::jsonb)) AS item(value);

  PERFORM public.upsert_notification_event(
    v_order.workspace_id,
    p.id,
    'marketplace_order_pending',
    v_order.id::text,
    v_due_date,
    jsonb_build_object(
      'entity_type', 'marketplace_order_pending',
      'title', format('Pending marketplace order %s', v_order.order_number),
      'order_id', v_order.id,
      'order_number', v_order.order_number,
      'customer_name', v_order.customer_name,
      'customer_phone', v_order.customer_phone,
      'customer_city', v_order.customer_city,
      'amount', v_order.total,
      'currency', COALESCE(NULLIF(v_order.currency, ''), 'iqd'),
      'created_at', v_order.created_at,
      'due_date', v_due_date,
      'item_count', v_item_count
    )
  )
  FROM public.profiles p
  WHERE p.workspace_id = v_order.workspace_id
    AND p.role IN ('admin', 'staff');
END;
$$;


--
-- Name: reassign_custom_template_primary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reassign_custom_template_primary"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  replacement_id uuid;
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'UPDATE' AND OLD."primary" AND NOT NEW."primary" THEN
    SELECT candidate.id
    INTO replacement_id
    FROM public.custom_templates candidate
    WHERE candidate.workspace_id = NEW.workspace_id
      AND candidate.module_type_key = NEW.module_type_key
      AND candidate.id <> NEW.id
      AND candidate.active
    ORDER BY candidate.updated_at DESC, candidate.created_at DESC, candidate.id
    LIMIT 1;

    IF replacement_id IS NOT NULL THEN
      UPDATE public.custom_templates
      SET "primary" = true
      WHERE id = replacement_id;
    ELSIF EXISTS (
      SELECT 1
      FROM public.custom_templates candidate
      WHERE candidate.workspace_id = OLD.workspace_id
        AND candidate.module_type_key = OLD.module_type_key
    ) THEN
      RAISE EXCEPTION 'A primary custom template cannot be deleted without another active template';
    END IF;
  ELSIF TG_OP = 'DELETE' AND OLD."primary" THEN
    SELECT candidate.id
    INTO replacement_id
    FROM public.custom_templates candidate
    WHERE candidate.workspace_id = OLD.workspace_id
      AND candidate.module_type_key = OLD.module_type_key
      AND candidate.active
    ORDER BY candidate.updated_at DESC, candidate.created_at DESC, candidate.id
    LIMIT 1;

    IF replacement_id IS NOT NULL THEN
      UPDATE public.custom_templates
      SET "primary" = true
      WHERE id = replacement_id;
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: refresh_product_inventory_snapshot("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_product_inventory_snapshot"("p_product_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_total_quantity integer := 0;
    v_storage_count integer := 0;
    v_single_storage_id uuid := null;
BEGIN
    SELECT
        COALESCE(SUM(quantity), 0)::integer,
        COUNT(*)::integer,
        CASE WHEN COUNT(*) = 1 THEN MIN(storage_id::text)::uuid ELSE NULL END
    INTO v_total_quantity, v_storage_count, v_single_storage_id
    FROM public.inventory
    WHERE product_id = p_product_id
      AND COALESCE(is_deleted, false) = false;

    UPDATE public.products
    SET
        quantity = v_total_quantity,
        storage_id = CASE WHEN v_storage_count = 1 THEN v_single_storage_id ELSE NULL END,
        updated_at = timezone('utc', now()),
        version = COALESCE(version, 0) + 1
    WHERE id = p_product_id
      AND (
        quantity IS DISTINCT FROM v_total_quantity
        OR storage_id IS DISTINCT FROM CASE WHEN v_storage_count = 1 THEN v_single_storage_id ELSE NULL END
      );
END;
$$;


--
-- Name: request_dispatch_notifications("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."request_dispatch_notifications"("p_target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_project_url text;
  v_cron_secret text;
  v_request_id bigint;
BEGIN
  SELECT decrypted_secret
  INTO v_project_url
  FROM vault.decrypted_secrets
  WHERE name = 'project_url';

  SELECT decrypted_secret
  INTO v_cron_secret
  FROM vault.decrypted_secrets
  WHERE name = 'notification_cron_secret';

  IF COALESCE(v_project_url, '') = '' THEN
    RAISE EXCEPTION 'Vault secret project_url is required';
  END IF;

  IF COALESCE(v_cron_secret, '') = '' THEN
    RAISE EXCEPTION 'Vault secret notification_cron_secret is required';
  END IF;

  SELECT net.http_post(
    url := v_project_url || '/functions/v1/dispatch-notifications',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Cron-Secret', v_cron_secret
    ),
    body := jsonb_build_object('workspace_id', p_target_workspace_id)
  )
  INTO v_request_id;

  RETURN v_request_id;
END;
$$;


--
-- Name: restore_branch("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."restore_branch"("p_source_workspace_id" "uuid", "p_branch_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_branch_record public.workspace_branches%ROWTYPE;
  v_source_workspace public.workspaces%ROWTYPE;
  v_active_branch_count integer;
BEGIN
  SELECT *
  INTO v_source_workspace
  FROM public.workspaces
  WHERE id = p_source_workspace_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Source workspace not found';
  END IF;

  SELECT *
  INTO v_branch_record
  FROM public.workspace_branches
  WHERE source_workspace_id = p_source_workspace_id
    AND branch_workspace_id = p_branch_workspace_id
    AND archived_at IS NOT NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Archived branch relationship not found for source % and branch %',
      p_source_workspace_id,
      p_branch_workspace_id;
  END IF;

  SELECT count(*)
  INTO v_active_branch_count
  FROM public.workspace_branches
  WHERE source_workspace_id = p_source_workspace_id
    AND archived_at IS NULL
    AND id IS DISTINCT FROM v_branch_record.id;

  IF v_active_branch_count >= public.workspace_max_branches(
    p_source_workspace_id,
    v_source_workspace.plan::text
  ) THEN
    RAISE EXCEPTION 'Workspace branch limit reached for current plan'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.workspaces
  SET deleted_at = NULL,
      locked_workspace = v_source_workspace.locked_workspace,
      subscription_expires_at = v_source_workspace.subscription_expires_at
  WHERE id = p_branch_workspace_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Branch workspace not found';
  END IF;

  UPDATE public.workspace_branches
  SET archived_at = NULL,
      archived_by = NULL,
      archive_reason = NULL
  WHERE id = v_branch_record.id;

  RETURN jsonb_build_object(
    'success', true,
    'source_workspace_id', p_source_workspace_id,
    'branch_workspace_id', p_branch_workspace_id
  );
END;
$$;


--
-- Name: return_sale_items("uuid"[], "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."return_sale_items"("p_sale_item_ids" "uuid"[], "p_return_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    item_record RECORD;
    p_workspace_id UUID;
    v_user_role TEXT;
    v_allow_pos BOOLEAN;
    sale_id UUID;
BEGIN
    -- Check if array is empty
    IF p_sale_item_ids IS NULL OR array_length(p_sale_item_ids, 1) IS NULL THEN
        RAISE EXCEPTION 'No items selected for return';
    END IF;

    -- Get first item to determine workspace and sale
    SELECT si.*, s.workspace_id
    INTO item_record
    FROM public.sale_items si
    JOIN public.sales s ON s.id = si.sale_id
    WHERE si.id = ANY(p_sale_item_ids)
    LIMIT 1;
    
    -- Extract workspace_id from the record
    p_workspace_id := item_record.workspace_id;
    
    IF item_record IS NULL THEN
        RAISE EXCEPTION 'Sale items not found';
    END IF;

    -- Check if POS feature is enabled
    SELECT allow_pos INTO v_allow_pos
    FROM public.workspaces
    WHERE id = p_workspace_id;

    IF NOT COALESCE(v_allow_pos, false) THEN
        RAISE EXCEPTION 'POS feature is not enabled for this workspace';
    END IF;

    -- Check user permissions (Admin or Staff can return items)
    SELECT role INTO v_user_role
    FROM public.profiles 
    WHERE id = auth.uid() 
    AND workspace_id = p_workspace_id;

    IF v_user_role NOT IN ('admin', 'staff') THEN
        RAISE EXCEPTION 'Unauthorized: Only admins and staff can return items';
    END IF;

    -- Process each item
    FOR item_record IN 
        SELECT si.*, s.id as sale_id
        FROM public.sale_items si
        JOIN public.sales s ON s.id = si.sale_id
        WHERE si.id = ANY(p_sale_item_ids)
    LOOP
        -- Check if item is already returned
        IF item_record.is_returned = TRUE THEN
            CONTINUE; -- Skip already returned items
        END IF;

        -- Update the item as returned
        UPDATE public.sale_items
        SET 
            is_returned = TRUE,
            return_reason = p_return_reason,
            returned_at = NOW(),
            returned_by = auth.uid()
        WHERE id = item_record.id;

        -- Restore inventory
        UPDATE public.products
        SET quantity = quantity + item_record.quantity
        WHERE id = item_record.product_id
          AND workspace_id = p_workspace_id;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'message', 'Items returned successfully');
END;
$$;


--
-- Name: return_sale_items("uuid"[], integer[], "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."return_sale_items"("p_sale_item_ids" "uuid"[], "p_return_quantities" integer[], "p_return_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_sale_id uuid;
  v_items jsonb;
BEGIN
  IF p_sale_item_ids IS NULL
     OR array_length(p_sale_item_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'No items selected for return';
  END IF;

  IF p_return_quantities IS NULL
     OR array_length(p_return_quantities, 1)
        IS DISTINCT FROM array_length(p_sale_item_ids, 1) THEN
    RAISE EXCEPTION 'Return quantities must match selected sale items';
  END IF;

  SELECT sale_id
  INTO v_sale_id
  FROM public.sale_items
  WHERE id = p_sale_item_ids[1];

  IF v_sale_id IS NULL THEN
    RAISE EXCEPTION 'Sale items not found';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', gen_random_uuid(),
      'sale_item_id', item_id,
      'quantity', return_quantity
    )
  )
  INTO v_items
  FROM unnest(p_sale_item_ids, p_return_quantities)
    AS requested_items(item_id, return_quantity);

  RETURN public.process_sale_return(
    gen_random_uuid(),
    v_sale_id,
    v_items,
    p_return_reason,
    NULL
  );
END;
$$;


--
-- Name: return_whole_sale("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."return_whole_sale"("p_sale_id" "uuid", "p_return_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_workspace_id uuid;
  v_user_role text;
  v_items jsonb;
BEGIN
  SELECT s.workspace_id, p.role
  INTO v_workspace_id, v_user_role
  FROM public.sales s
  JOIN public.profiles p
    ON p.id = auth.uid()
   AND p.current_workspace = s.workspace_id
  WHERE s.id = p_sale_id;

  IF v_user_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Unauthorized: Only admins can return whole sales';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', gen_random_uuid(),
      'sale_item_id', id,
      'quantity', quantity - COALESCE(returned_quantity, 0)
    )
  )
  INTO v_items
  FROM public.sale_items
  WHERE sale_id = p_sale_id
    AND quantity - COALESCE(returned_quantity, 0) > 0;

  IF v_items IS NULL OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'No returnable items found in this sale';
  END IF;

  RETURN public.process_sale_return(
    gen_random_uuid(),
    p_sale_id,
    v_items,
    p_return_reason,
    NULL
  );
END;
$$;


--
-- Name: rotate_app_permissions_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rotate_app_permissions_keys"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE public.app_permissions
    SET key_value = public.generate_random_alphanumeric_key(32)
    WHERE key_name IN (
        'connection_admin',
        'super_admin_passkey',
        'update_key'
    );

    PERFORM public.rotate_registration_keys();
END;
$$;


--
-- Name: rotate_registration_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rotate_registration_keys"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    ON CONFLICT (key_name) DO UPDATE
    SET
        key_value = EXCLUDED.key_value,
        updated_at = now();
END;
$$;


--
-- Name: rotate_signup_safe_app_permissions_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rotate_signup_safe_app_permissions_keys"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
    update public.app_permissions
    set key_value = public.generate_random_alphanumeric_key(32)
    where key_name in (
        'connection_admin',
        'update_key'
    );
end;
$$;


