-- Name: source_workspace_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."source_workspace_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT workspace_id
  FROM public.profiles
  WHERE id = auth.uid();
$$;


--
-- Name: switch_workspace_data_mode("public"."workspace_data_mode"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."switch_workspace_data_mode"("p_new_mode" "public"."workspace_data_mode") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_workspace_id uuid;
    v_current_mode workspace_data_mode;
BEGIN
    -- Get caller's workspace
    v_workspace_id := (auth.jwt() -> 'user_metadata' ->> 'workspace_id')::uuid;
    IF v_workspace_id IS NULL THEN
        RAISE EXCEPTION 'No workspace found for current user';
    END IF;

    -- Get current mode
    SELECT data_mode INTO v_current_mode
    FROM workspaces
    WHERE id = v_workspace_id;

    IF v_current_mode IS NULL THEN
        RAISE EXCEPTION 'Workspace not found';
    END IF;

    -- Only allow cloud <-> hybrid switching
    IF v_current_mode = 'local' OR p_new_mode = 'local' THEN
        RAISE EXCEPTION 'Cannot switch to or from local mode. Only cloud <-> hybrid switching is allowed.';
    END IF;

    -- No-op if same mode
    IF v_current_mode = p_new_mode THEN
        RETURN;
    END IF;

    -- Perform the switch
    UPDATE workspaces
    SET data_mode = p_new_mode
    WHERE id = v_workspace_id;
END;
$$;


--
-- Name: sync_branch_workspace_status_from_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_branch_workspace_status_from_source"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE public.workspaces AS branch_workspace
  SET
    locked_workspace = NEW.locked_workspace,
    subscription_expires_at = NEW.subscription_expires_at
  WHERE branch_workspace.id IN (
      SELECT wb.branch_workspace_id
      FROM public.workspace_branches wb
      WHERE wb.source_workspace_id = NEW.id
        AND wb.archived_at IS NULL
    )
    AND branch_workspace.deleted_at IS NULL
    AND (
      branch_workspace.locked_workspace IS DISTINCT FROM NEW.locked_workspace
      OR branch_workspace.subscription_expires_at IS DISTINCT FROM NEW.subscription_expires_at
    );

  RETURN NEW;
END;
$$;


--
-- Name: sync_new_branch_workspace_status_from_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_new_branch_workspace_status_from_source"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE public.workspaces AS branch_workspace
  SET
    locked_workspace = source_workspace.locked_workspace,
    subscription_expires_at = source_workspace.subscription_expires_at
  FROM public.workspaces AS source_workspace
  WHERE branch_workspace.id = NEW.branch_workspace_id
    AND source_workspace.id = NEW.source_workspace_id
    AND (
      branch_workspace.locked_workspace IS DISTINCT FROM source_workspace.locked_workspace
      OR branch_workspace.subscription_expires_at IS DISTINCT FROM source_workspace.subscription_expires_at
    );

  RETURN NEW;
END;
$$;


--
-- Name: sync_sales_currency_with_settlement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sync_sales_currency_with_settlement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_currency text;
BEGIN
  v_currency := lower(coalesce(
    nullif(NEW.settlement_currency, ''),
    nullif(NEW.currency, ''),
    'usd'
  ));

  NEW.settlement_currency := v_currency;
  NEW.currency := v_currency;

  RETURN NEW;
END;
$$;


