  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: transition_marketplace_order("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."transition_marketplace_order"("order_id" "uuid", "next_status" "text", "cancel_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'crm'
    AS $$
DECLARE
  v_order public.marketplace_orders%ROWTYPE;
  v_workspace public.workspaces%ROWTYPE;
  v_next_status text := lower(trim(COALESCE(next_status, '')));
  v_cancel_reason text := NULLIF(trim(COALESCE(cancel_reason, '')), '');
  v_item jsonb;
  v_line_item jsonb;
  v_product_id uuid;
  v_requested_qty integer;
  v_declared_storage_id uuid;
  v_resolved_storage_id uuid;
  v_inventory_quantity integer;
  v_warning_messages text[] := ARRAY[]::text[];
  v_missing_storage_count integer := 0;
  v_inventory_completed boolean := false;
  v_business_partner_id uuid;
  v_customer_id uuid;
  v_sales_order_id uuid;
  v_sales_order_number text;
  v_phone_norm text;
  v_email_norm text;
  v_existing_customer_id uuid;
  v_existing_partner_is_ecommerce boolean := false;
  v_delivery_timestamp timestamp with time zone := timezone('utc', now());
  v_shipping_address text;
  v_order_notes text;
  v_sales_order_items jsonb := '[]'::jsonb;
  v_product_name text;
  v_product_sku text;
  v_product_cost_price numeric;
  v_product_storage_id uuid;
  v_item_storage_id uuid;
  v_item_currency text;
  v_item_name text;
  v_item_sku text;
  v_item_unit_price numeric;
  v_item_line_total numeric;
  v_common_storage_id uuid;
  v_common_storage_initialized boolean := false;
  v_has_storage_conflict boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF public.current_workspace_id() IS NULL THEN
    RAISE EXCEPTION 'Workspace context is missing';
  END IF;

  IF public.current_user_role() NOT IN ('admin', 'staff') THEN
    RAISE EXCEPTION 'Only admins and staff can manage marketplace orders';
  END IF;

  IF v_next_status NOT IN ('confirmed', 'processing', 'shipped', 'delivered', 'cancelled') THEN
    RAISE EXCEPTION 'Unsupported marketplace order status';
  END IF;

  SELECT *
  INTO v_order
  FROM public.marketplace_orders
  WHERE id = order_id
    AND workspace_id = public.current_workspace_id()
    AND COALESCE(is_deleted, false) = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Marketplace order not found';
  END IF;

  SELECT *
  INTO v_workspace
  FROM public.workspaces
  WHERE id = v_order.workspace_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Workspace not found for marketplace order';
  END IF;

  IF v_order.status IN ('delivered', 'cancelled') THEN
    RAISE EXCEPTION 'This marketplace order is already finalized';
  END IF;

  CASE v_order.status
    WHEN 'pending' THEN
      IF v_next_status NOT IN ('confirmed', 'cancelled') THEN
        RAISE EXCEPTION 'Pending orders can only move to confirmed or cancelled';
      END IF;
    WHEN 'confirmed' THEN
      IF v_next_status NOT IN ('processing', 'cancelled') THEN
        RAISE EXCEPTION 'Confirmed orders can only move to processing or cancelled';
      END IF;
    WHEN 'processing' THEN
      IF v_next_status NOT IN ('shipped', 'cancelled') THEN
        RAISE EXCEPTION 'Processing orders can only move to shipped or cancelled';
      END IF;
    WHEN 'shipped' THEN
      IF v_next_status <> 'delivered' THEN
        RAISE EXCEPTION 'Shipped orders can only move to delivered';
      END IF;
    ELSE
      RAISE EXCEPTION 'Unsupported current marketplace order status';
  END CASE;

  IF v_next_status = 'confirmed' THEN
    UPDATE public.marketplace_orders
    SET
      status = 'confirmed',
      confirmed_at = COALESCE(confirmed_at, timezone('utc', now())),
      version = COALESCE(version, 0) + 1
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
      'order_id', v_order.id,
      'status', 'confirmed',
      'inventory_deducted', v_order.inventory_deducted,
      'warning', NULL,
      'warnings', '[]'::jsonb
    );
  END IF;

  IF v_next_status = 'processing' THEN
    UPDATE public.marketplace_orders
    SET
      status = 'processing',
      processing_at = COALESCE(processing_at, timezone('utc', now())),
      version = COALESCE(version, 0) + 1
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
      'order_id', v_order.id,
      'status', 'processing',
      'inventory_deducted', v_order.inventory_deducted,
      'warning', NULL,
      'warnings', '[]'::jsonb
    );
  END IF;

  IF v_next_status = 'shipped' THEN
    UPDATE public.marketplace_orders
    SET
      status = 'shipped',
      shipped_at = COALESCE(shipped_at, timezone('utc', now())),
      version = COALESCE(version, 0) + 1
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
      'order_id', v_order.id,
      'status', 'shipped',
      'inventory_deducted', v_order.inventory_deducted,
      'warning', NULL,
      'warnings', '[]'::jsonb
    );
  END IF;

  IF v_next_status = 'cancelled' THEN
    UPDATE public.marketplace_orders
    SET
      status = 'cancelled',
      cancelled_at = COALESCE(cancelled_at, timezone('utc', now())),
      cancel_reason = v_cancel_reason,
      version = COALESCE(version, 0) + 1
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
      'order_id', v_order.id,
      'status', 'cancelled',
      'inventory_deducted', v_order.inventory_deducted,
      'warning', NULL,
      'warnings', '[]'::jsonb
    );
  END IF;

  IF NOT COALESCE(v_order.inventory_deducted, false) THEN
    FOR v_item IN
      SELECT *
      FROM jsonb_array_elements(COALESCE(v_order.items, '[]'::jsonb))
    LOOP
      v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
      v_requested_qty := COALESCE((v_item->>'quantity')::integer, 0);
      v_declared_storage_id := NULLIF(v_item->>'storage_id', '')::uuid;

      IF v_product_id IS NULL OR v_requested_qty <= 0 THEN
        CONTINUE;
      END IF;

      v_resolved_storage_id := v_declared_storage_id;

      IF v_resolved_storage_id IS NULL THEN
        SELECT CASE WHEN COUNT(*) = 1 THEN MIN(storage_id::text)::uuid ELSE NULL END
        INTO v_resolved_storage_id
        FROM public.inventory
        WHERE workspace_id = v_order.workspace_id
          AND product_id = v_product_id
          AND COALESCE(is_deleted, false) = false;
      END IF;

      IF v_resolved_storage_id IS NULL THEN
        SELECT storage_id
        INTO v_resolved_storage_id
        FROM public.products
        WHERE id = v_product_id
          AND workspace_id = v_order.workspace_id
          AND COALESCE(is_deleted, false) = false;
      END IF;

      IF v_resolved_storage_id IS NULL THEN
        v_missing_storage_count := v_missing_storage_count + 1;
        v_warning_messages := array_append(
          v_warning_messages,
          format('No storage could be resolved for %s', COALESCE(NULLIF(v_item->>'name', ''), v_product_id::text))
        );
        CONTINUE;
      END IF;

      SELECT quantity
      INTO v_inventory_quantity
      FROM public.inventory
      WHERE workspace_id = v_order.workspace_id
        AND product_id = v_product_id
        AND storage_id = v_resolved_storage_id
      LIMIT 1
      FOR UPDATE;

      IF COALESCE(v_inventory_quantity, 0) < v_requested_qty THEN
        v_warning_messages := array_append(
          v_warning_messages,
          format('Inventory for %s will go negative after delivery', COALESCE(NULLIF(v_item->>'name', ''), v_product_id::text))
        );
      END IF;

        id,
        workspace_id,
        product_id,
        storage_id,
        quantity,
        created_at,
        updated_at,
        version,
        is_deleted
      )
      VALUES (
        gen_random_uuid(),
        v_order.workspace_id,
        v_product_id,
        v_resolved_storage_id,
        0 - v_requested_qty,
        timezone('utc', now()),
        timezone('utc', now()),
        1,
        false
      )
      ON CONFLICT (workspace_id, product_id, storage_id)
      DO UPDATE SET
        quantity = COALESCE(public.inventory.quantity, 0) + EXCLUDED.quantity,
        updated_at = timezone('utc', now()),
        version = COALESCE(public.inventory.version, 0) + 1,
        is_deleted = false;
    END LOOP;

    v_inventory_completed := v_missing_storage_count = 0;
  ELSE
    v_inventory_completed := true;
  END IF;

  IF v_missing_storage_count > 0 THEN
    v_warning_messages := array_append(
      v_warning_messages,
      'Inventory was not fully deducted because some items were missing a resolved storage.'
    );
  END IF;

  v_business_partner_id := v_order.business_partner_id;
  v_customer_id := v_order.customer_id;
  v_sales_order_id := v_order.sales_order_id;

  IF v_sales_order_id IS NULL THEN
    v_phone_norm := NULLIF(regexp_replace(COALESCE(v_order.customer_phone, ''), '\D', '', 'g'), '');
    v_email_norm := NULLIF(lower(trim(COALESCE(v_order.customer_email, ''))), '');

    SELECT
      bp.id,
      COALESCE(bp.customer_facet_id, c.id),
      COALESCE(bp.is_ecommerce, false)
    INTO
      v_business_partner_id,
      v_existing_customer_id,
      v_existing_partner_is_ecommerce
    FROM crm.business_partners bp
    LEFT JOIN crm.customers c
      ON c.business_partner_id = bp.id
     AND c.workspace_id = bp.workspace_id
     AND COALESCE(c.is_deleted, false) = false
    WHERE bp.workspace_id = v_order.workspace_id
      AND COALESCE(bp.is_deleted, false) = false
      AND bp.merged_into_business_partner_id IS NULL
      AND bp.role IN ('customer', 'both')
      AND (
        (v_phone_norm IS NOT NULL AND regexp_replace(COALESCE(bp.phone, ''), '\D', '', 'g') = v_phone_norm)
        OR (v_email_norm IS NOT NULL AND lower(trim(COALESCE(bp.email, ''))) = v_email_norm)
      )
    ORDER BY
      CASE
        WHEN v_phone_norm IS NOT NULL AND regexp_replace(COALESCE(bp.phone, ''), '\D', '', 'g') = v_phone_norm THEN 0
        ELSE 1
      END,
      CASE
        WHEN v_email_norm IS NOT NULL AND lower(trim(COALESCE(bp.email, ''))) = v_email_norm THEN 0
        ELSE 1
      END,
      bp.updated_at DESC NULLS LAST
    LIMIT 1;

    IF v_business_partner_id IS NULL THEN
        workspace_id,
        name,
        contact_name,
        email,
        phone,
        address,
        city,
        country,
        notes,
        default_currency,
        role,
        credit_limit,
        customer_facet_id,
        supplier_facet_id,
        total_sales_orders,
        total_sales_value,
        receivable_balance,
        total_purchase_orders,
        total_purchase_value,
        payable_balance,
        total_loan_count,
        loan_outstanding_balance,
        net_exposure,
        merged_into_business_partner_id,
        is_ecommerce,
        created_at,
        updated_at,
        sync_status,
        version,
        is_deleted
      )
      VALUES (
        v_order.workspace_id,
        v_order.customer_name,
        NULL,
        v_order.customer_email,
        v_order.customer_phone,
        v_order.customer_address,
        v_order.customer_city,
        NULL,
        format('Created automatically from marketplace order %s', v_order.order_number),
        lower(COALESCE(v_order.currency, v_workspace.default_currency::text, 'usd')),
        'customer',
        0,
        NULL,
        NULL,
        0,
        0,
        0,
        0,
        0,
        0,
        0,
        0,
        0,
        NULL,
        true,
        v_order.created_at,
        v_delivery_timestamp,
        'synced',
        1,
        false
      )
      RETURNING id
      INTO v_business_partner_id;

      v_existing_partner_is_ecommerce := true;
    END IF;

    IF COALESCE(v_existing_customer_id, v_customer_id) IS NULL THEN
        workspace_id,
        business_partner_id,
        name,
        email,
        phone,
        address,
        city,
        country,
        notes,
        default_currency,
        total_orders,
        total_spent,
        outstanding_balance,
        created_at,
        updated_at,
        sync_status,
        version,
        is_deleted,
        credit_limit,
        is_ecommerce
      )
      VALUES (
        v_order.workspace_id,
        v_business_partner_id,
        v_order.customer_name,
        v_order.customer_email,
        v_order.customer_phone,
        v_order.customer_address,
        v_order.customer_city,
        NULL,
        format('Created automatically from marketplace order %s', v_order.order_number),
        lower(COALESCE(v_order.currency, v_workspace.default_currency::text, 'usd')),
        0,
        0,
        0,
        v_order.created_at,
        v_delivery_timestamp,
        'synced',
        1,
        false,
        0,
        COALESCE(v_existing_partner_is_ecommerce, false)
      )
      RETURNING id
      INTO v_customer_id;

      UPDATE crm.business_partners
      SET
        customer_facet_id = v_customer_id,
        updated_at = v_delivery_timestamp,
        version = COALESCE(version, 0) + 1
      WHERE id = v_business_partner_id;
    ELSE
      v_customer_id := COALESCE(v_existing_customer_id, v_customer_id);
    END IF;

    FOR v_item IN
      SELECT *
      FROM jsonb_array_elements(COALESCE(v_order.items, '[]'::jsonb))
    LOOP
      v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
      v_requested_qty := COALESCE((v_item->>'quantity')::integer, 0);

      IF v_requested_qty <= 0 THEN
        CONTINUE;
      END IF;

      v_product_name := NULL;
      v_product_sku := NULL;
      v_product_cost_price := NULL;
      v_product_storage_id := NULL;

      IF v_product_id IS NOT NULL THEN
        SELECT
          name,
          sku,
          cost_price,
          storage_id
        INTO
          v_product_name,
          v_product_sku,
          v_product_cost_price,
          v_product_storage_id
        FROM public.products
        WHERE id = v_product_id
          AND workspace_id = v_order.workspace_id
          AND COALESCE(is_deleted, false) = false
        LIMIT 1;
      END IF;

      v_item_currency := lower(COALESCE(NULLIF(v_item->>'currency', ''), v_order.currency, v_workspace.default_currency::text, 'usd'));
      v_item_name := COALESCE(v_product_name, NULLIF(v_item->>'name', ''), 'Unknown Product');
      v_item_sku := COALESCE(v_product_sku, NULLIF(v_item->>'sku', ''), '');
      v_item_unit_price := COALESCE((v_item->>'unit_price')::numeric, 0);
      v_item_line_total := COALESCE((v_item->>'line_total')::numeric, v_item_unit_price * v_requested_qty);
      v_item_storage_id := COALESCE(NULLIF(v_item->>'storage_id', '')::uuid, v_product_storage_id);

      IF v_item_storage_id IS NOT NULL THEN
        IF NOT v_common_storage_initialized THEN
          v_common_storage_id := v_item_storage_id;
          v_common_storage_initialized := true;
        ELSIF v_common_storage_id IS DISTINCT FROM v_item_storage_id THEN
          v_has_storage_conflict := true;
        END IF;
      ELSE
        v_has_storage_conflict := true;
      END IF;

      v_line_item := jsonb_build_object(
        'id', gen_random_uuid()::text,
        'productId', COALESCE(v_product_id::text, v_item->>'product_id', gen_random_uuid()::text),
        'storageId', v_item_storage_id,
        'productName', v_item_name,
        'productSku', v_item_sku,
        'quantity', v_requested_qty,
        'lineTotal', v_item_line_total,
        'originalCurrency', v_item_currency,
        'originalUnitPrice', v_item_unit_price,
        'convertedUnitPrice', v_item_unit_price,
        'settlementCurrency', lower(COALESCE(v_order.currency, v_workspace.default_currency::text, 'usd')),
        'costPrice', COALESCE(v_product_cost_price, 0),
        'convertedCostPrice', COALESCE(v_product_cost_price, 0),
        'reservedQuantity', v_requested_qty,
        'fulfilledQuantity', v_requested_qty
      );

      v_sales_order_items := v_sales_order_items || jsonb_build_array(v_line_item);
    END LOOP;

    IF v_has_storage_conflict THEN
      v_common_storage_id := NULL;
    END IF;

    v_shipping_address := NULLIF(
      trim(concat_ws(', ',
        NULLIF(trim(COALESCE(v_order.customer_address, '')), ''),
        NULLIF(trim(COALESCE(v_order.customer_city, '')), '')
      )),
      ''
    );

    v_order_notes := format('Marketplace order %s', v_order.order_number);
    IF v_order.customer_notes IS NOT NULL THEN
      v_order_notes := format('%s%sCustomer note: %s', v_order_notes, E'\n\n', v_order.customer_notes);
    END IF;

      order_number,
      workspace_id,
      business_partner_id,
      customer_id,
      customer_name,
      subtotal,
      discount,
      tax,
      total,
      currency,
      exchange_rate,
      exchange_rate_source,
      exchange_rate_timestamp,
      exchange_rates,
      status,
      expected_delivery_date,
      actual_delivery_date,
      is_paid,
      paid_at,
      payment_method,
      reserved_at,
      source_storage_id,
      shipping_address,
      notes,
      items,
      is_locked,
      source_channel,
      marketplace_order_id,
      created_at,
      updated_at,
      sync_status,
      version,
      is_deleted
    )
    VALUES (
      '',
      v_order.workspace_id,
      v_business_partner_id,
      v_customer_id,
      v_order.customer_name,
      COALESCE(v_order.subtotal, 0),
      0,
      0,
      COALESCE(v_order.total, v_order.subtotal, 0),
      lower(COALESCE(v_order.currency, v_workspace.default_currency::text, 'usd')),
      1,
      'marketplace',
      v_order.created_at,
      '[]'::jsonb,
      'completed',
      v_order.shipped_at,
      v_delivery_timestamp,
      false,
      NULL,
      'credit',
      NULL,
      v_common_storage_id,
      v_shipping_address,
      v_order_notes,
      v_sales_order_items,
      false,
      'marketplace',
      v_order.id,
      v_order.created_at,
      v_delivery_timestamp,
      'synced',
      1,
      false
    )
    RETURNING id, order_number
    INTO v_sales_order_id, v_sales_order_number;
  END IF;

  UPDATE public.marketplace_orders
  SET
    status = 'delivered',
    delivered_at = COALESCE(delivered_at, v_delivery_timestamp),
    inventory_deducted = COALESCE(v_order.inventory_deducted, false) OR v_inventory_completed,
    business_partner_id = COALESCE(v_business_partner_id, business_partner_id),
    customer_id = COALESCE(v_customer_id, customer_id),
    sales_order_id = COALESCE(v_sales_order_id, sales_order_id),
    version = COALESCE(version, 0) + 1
  WHERE id = v_order.id;

  RETURN jsonb_build_object(
    'order_id', v_order.id,
    'status', 'delivered',
    'inventory_deducted', COALESCE(v_order.inventory_deducted, false) OR v_inventory_completed,
    'sales_order_id', v_sales_order_id,
    'customer_id', v_customer_id,
    'business_partner_id', v_business_partner_id,
    'warning',
      CASE
        WHEN COALESCE(array_length(v_warning_messages, 1), 0) > 0
          THEN array_to_string(v_warning_messages, '; ')
        ELSE NULL
      END,
    'warnings', to_jsonb(COALESCE(v_warning_messages, ARRAY[]::text[]))
  );
END;
$$;


--
-- Name: trigger_rotate_keys_on_register(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trigger_rotate_keys_on_register"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Registration keys now rotate inside check_registration_passkey()
    -- so validation and rotation happen atomically in a single transaction.
    RETURN NEW;
END;
$$;


--
-- Name: trigger_set_stock_batches_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trigger_set_stock_batches_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: update_notification_event_status("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_notification_event_status"("p_event_id" "uuid", "p_status" "text", "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'notifications', 'public'
    AS $$
BEGIN
    UPDATE notifications.events
    SET 
        status = p_status::notifications.event_status,
        last_attempt_at = NOW(),
        attempt_count = COALESCE(attempt_count, 0) + 1,
        error_log = p_error
    WHERE id = p_event_id;
END;
$$;


--
-- Name: update_notification_event_status("uuid", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_notification_event_status"("p_event_id" "uuid", "p_status" "text", "p_error" "text" DEFAULT NULL::"text", "p_attempt_count" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'notifications', 'public'
    AS $$
BEGIN
    UPDATE notifications.events
    SET 
        status = p_status,
        last_attempt_at = NOW(),
        attempt_count = COALESCE(p_attempt_count, attempt_count + 1),
        error = p_error,
        updated_at = NOW()
    WHERE id = p_event_id;
END;
$$;


--
-- Name: update_notification_push_delivery("uuid", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_notification_push_delivery"("p_notification_id" "uuid", "p_status" "text", "p_error" "text" DEFAULT NULL::"text", "p_attempt_delta" integer DEFAULT 1) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
DECLARE
  v_status text := lower(trim(COALESCE(p_status, '')));
  v_error text := NULLIF(trim(COALESCE(p_error, '')), '');
  v_attempt_delta integer := GREATEST(COALESCE(p_attempt_delta, 1), 0);
BEGIN
  IF v_status NOT IN ('pending', 'sent', 'failed', 'skipped') THEN
    RAISE EXCEPTION 'Unsupported push status: %', COALESCE(v_status, '<null>');
  END IF;

  UPDATE notifications.inbox
  SET
    push_status = v_status,
    push_sent_at = CASE
      WHEN v_status = 'sent' THEN COALESCE(push_sent_at, now())
      WHEN v_status = 'pending' THEN NULL
      ELSE push_sent_at
    END,
    push_last_attempt_at = CASE
      WHEN v_status = 'pending' THEN NULL
      ELSE now()
    END,
    push_error = CASE
      WHEN v_status IN ('sent', 'pending') THEN NULL
      ELSE v_error
    END,
    push_attempt_count = CASE
      WHEN v_status = 'pending' THEN 0
      ELSE push_attempt_count + v_attempt_delta
    END,
    updated_at = now()
  WHERE id = p_notification_id;
END;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: update_workspace_member_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_workspace_member_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
    if (TG_OP = 'INSERT' and NEW.workspace_id is not null) then
        update public.workspaces set member_count = member_count + 1 where id = NEW.workspace_id;
    elsif (TG_OP = 'DELETE' and OLD.workspace_id is not null) then
        update public.workspaces set member_count = member_count - 1 where id = OLD.workspace_id;
    elsif (TG_OP = 'UPDATE') then
        if (OLD.workspace_id is distinct from NEW.workspace_id) then
            if (OLD.workspace_id is not null) then
                update public.workspaces set member_count = member_count - 1 where id = OLD.workspace_id;
            end if;
            if (NEW.workspace_id is not null) then
                update public.workspaces set member_count = member_count + 1 where id = NEW.workspace_id;
            end if;
        end if;
    end if;
    return NEW;
end;
$$;


--
-- Name: upsert_device_token("uuid", "text", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."upsert_device_token"("p_user_id" "uuid", "p_platform" "text", "p_device_token" "text", "p_workspace_id" "uuid" DEFAULT NULL::"uuid", "p_language" "text" DEFAULT 'en'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
DECLARE
  v_workspace_id uuid;
  v_platform text;
  v_device_token text;
  v_language text;
  v_device_token_id uuid;
BEGIN
  v_platform := lower(trim(COALESCE(p_platform, '')));
  v_device_token := trim(COALESCE(p_device_token, ''));
  v_language := lower(trim(COALESCE(p_language, 'en')));

  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'User id is required';
  END IF;

  IF v_platform NOT IN ('android', 'web') THEN
    RAISE EXCEPTION 'Unsupported platform: %', COALESCE(v_platform, '<null>');
  END IF;

  IF v_device_token = '' THEN
    RAISE EXCEPTION 'Device token is required';
  END IF;

  IF length(v_device_token) > 4096 THEN
    RAISE EXCEPTION 'Device token is too long';
  END IF;

  IF v_language = 'ar' OR v_language LIKE 'ar-%' THEN
    v_language := 'ar';
  ELSIF v_language = 'ku' OR v_language = 'ckb' OR v_language LIKE 'ku-%' OR v_language LIKE 'ckb-%' THEN
    v_language := 'ku';
  ELSE
    v_language := 'en';
  END IF;

  v_workspace_id := p_workspace_id;
  IF v_workspace_id IS NULL THEN
    SELECT p.current_workspace
    INTO v_workspace_id
    FROM public.profiles p
    WHERE p.id = p_user_id;
  END IF;

  IF v_workspace_id IS NULL THEN
    RAISE EXCEPTION 'Workspace not found for user %', p_user_id;
  END IF;

    user_id,
    workspace_id,
    platform,
    device_token,
    language
  )
  VALUES (
    p_user_id,
    v_workspace_id,
    v_platform,
    v_device_token,
    v_language
  )
  ON CONFLICT (device_token) DO UPDATE
  SET
    user_id = EXCLUDED.user_id,
    workspace_id = EXCLUDED.workspace_id,
    platform = EXCLUDED.platform,
    language = EXCLUDED.language,
    updated_at = now()
  RETURNING id INTO v_device_token_id;

  RETURN v_device_token_id;
END;
$$;


--
-- Name: upsert_notification_event("uuid", "uuid", "text", "text", "date", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."upsert_notification_event"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_entity_type" "text", "p_entity_id" "text", "p_due_date" "date", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
DECLARE
  v_event_id uuid;
BEGIN
    workspace_id,
    user_id,
    entity_type,
    entity_id,
    due_date,
    payload,
    status,
    attempt_count,
    last_attempt_at,
    error
  )
  VALUES (
    p_workspace_id,
    p_user_id,
    p_entity_type,
    p_entity_id,
    p_due_date,
    COALESCE(p_payload, '{}'::jsonb),
    'pending',
    0,
    NULL,
    NULL
  )
  ON CONFLICT (user_id, entity_type, entity_id, due_date) DO UPDATE
  SET
    workspace_id = EXCLUDED.workspace_id,
    payload = EXCLUDED.payload,
    status = 'pending',
    attempt_count = 0,
    last_attempt_at = NULL,
    error = NULL,
    updated_at = now()
  WHERE notifications.events.workspace_id IS DISTINCT FROM EXCLUDED.workspace_id
     OR notifications.events.payload IS DISTINCT FROM EXCLUDED.payload
     OR notifications.events.status IN ('failed', 'pending')
     OR NOT EXISTS (
       SELECT 1
       FROM notifications.inbox i
       WHERE i.event_id = notifications.events.id
     )
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    SELECT e.id
    INTO v_event_id
    FROM notifications.events e
    WHERE e.user_id = p_user_id
      AND e.entity_type = p_entity_type
      AND e.entity_id = p_entity_id
      AND e.due_date = p_due_date;
  END IF;

  RETURN v_event_id;
END;
$$;


--
-- Name: upsert_notification_inbox("uuid", "uuid", "uuid", "text", "text", "text", "text", "text", "text", "text", "text", "jsonb", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."upsert_notification_inbox"("p_event_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid", "p_notification_type" "text", "p_scope" "text" DEFAULT 'user'::"text", "p_priority" "text" DEFAULT 'normal'::"text", "p_dedupe_key" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT ''::"text", "p_body" "text" DEFAULT NULL::"text", "p_action_url" "text" DEFAULT NULL::"text", "p_action_label" "text" DEFAULT NULL::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_created_at" timestamp with time zone DEFAULT "now"()) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'notifications'
    AS $$
DECLARE
  v_notification_id uuid;
BEGIN
    event_id,
    workspace_id,
    user_id,
    notification_type,
    scope,
    priority,
    dedupe_key,
    title,
    body,
    action_url,
    action_label,
    payload,
    push_status,
    push_sent_at,
    push_last_attempt_at,
    push_error,
    push_attempt_count,
    created_at
  )
  VALUES (
    p_event_id,
    p_workspace_id,
    p_user_id,
    p_notification_type,
    COALESCE(NULLIF(TRIM(COALESCE(p_scope, '')), ''), 'user'),
    COALESCE(NULLIF(TRIM(COALESCE(p_priority, '')), ''), 'normal'),
    NULLIF(TRIM(COALESCE(p_dedupe_key, '')), ''),
    COALESCE(NULLIF(TRIM(COALESCE(p_title, '')), ''), 'Notification'),
    NULLIF(TRIM(COALESCE(p_body, '')), ''),
    NULLIF(TRIM(COALESCE(p_action_url, '')), ''),
    NULLIF(TRIM(COALESCE(p_action_label, '')), ''),
    COALESCE(p_payload, '{}'::jsonb),
    'pending',
    NULL,
    NULL,
    NULL,
    0,
    COALESCE(p_created_at, now())
  )
  ON CONFLICT (event_id) DO UPDATE
  SET
    workspace_id = EXCLUDED.workspace_id,
    user_id = EXCLUDED.user_id,
    notification_type = EXCLUDED.notification_type,
    scope = EXCLUDED.scope,
    priority = EXCLUDED.priority,
    dedupe_key = COALESCE(EXCLUDED.dedupe_key, notifications.inbox.dedupe_key),
    title = EXCLUDED.title,
    body = EXCLUDED.body,
    action_url = EXCLUDED.action_url,
    action_label = EXCLUDED.action_label,
    payload = EXCLUDED.payload,
    push_status = 'pending',
    push_sent_at = NULL,
    push_last_attempt_at = NULL,
    push_error = NULL,
    push_attempt_count = 0,
    created_at = LEAST(notifications.inbox.created_at, EXCLUDED.created_at),
    updated_at = now()
  RETURNING id INTO v_notification_id;

  RETURN v_notification_id;
END;
$$;


--
-- Name: workspace_capability_allowed("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."workspace_capability_allowed"("p_workspace_id" "uuid", "p_plan" "text", "p_capability" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT CASE
    WHEN public.workspace_has_override(p_workspace_id, 'capability', p_capability) THEN
      COALESCE(public.workspace_get_override_value(p_workspace_id, 'capability', p_capability), 'grant') = 'grant'
    ELSE public.workspace_plan_has_capability(p_plan, p_capability)
  END;
$$;


--
-- Name: workspace_currency_allowed("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."workspace_currency_allowed"("p_workspace_id" "uuid", "p_plan" "text", "p_currency" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT CASE
    WHEN public.workspace_has_override(p_workspace_id, 'currency', p_currency) THEN
      COALESCE(public.workspace_get_override_value(p_workspace_id, 'currency', p_currency), 'grant') = 'grant'
    ELSE public.workspace_plan_allows_currency(p_plan, p_currency)
  END;
$$;


--
-- Name: workspace_get_override_value("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."workspace_get_override_value"("p_workspace_id" "uuid", "p_type" "text", "p_key" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  SELECT value
  FROM public.workspace_access_overrides
  WHERE workspace_id = p_workspace_id
    AND type = p_type
    AND key = p_key
  LIMIT 1;
$$;


--
-- Name: workspace_has_fx_accounting_data("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."workspace_has_fx_accounting_data"("p_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM fx.exchange_transactions WHERE workspace_id = p_workspace_id AND is_deleted = false
    UNION ALL
    SELECT 1 FROM fx.fx_safes WHERE workspace_id = p_workspace_id AND is_deleted = false
    UNION ALL
    SELECT 1 FROM fx.fx_safe_balances WHERE workspace_id = p_workspace_id AND is_deleted = false
    UNION ALL
    SELECT 1 FROM fx.fx_safe_movements WHERE workspace_id = p_workspace_id AND is_deleted = false
    LIMIT 1
  );
$$;


