-- Name: workspace_has_override("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."workspace_has_override"("p_workspace_id" "uuid", "p_type" "text", "p_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.workspace_access_overrides
    WHERE workspace_id = p_workspace_id
      AND type = p_type
      AND key = p_key
  );
$$;


