    CONSTRAINT "clinical_appointments_fee_check" CHECK (("consultation_fee" >= (0)::numeric)),
    CONSTRAINT "clinical_appointments_paid_amount_check" CHECK (("paid_amount" >= (0)::numeric)),
    CONSTRAINT "clinical_appointments_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['no_fee'::"text", 'unpaid'::"text", 'partial'::"text", 'paid'::"text"]))),
    CONSTRAINT "clinical_appointments_priority_check" CHECK (("priority" = ANY (ARRAY['normal'::"text", 'urgent'::"text", 'emergency'::"text"]))),
