--
-- Name: employees; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."employees" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "email" "text",
    "phone" "text",
    "gender" "text",
    "role" "text" NOT NULL,
    "location" "text",
    "joining_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "salary" numeric(15,2) DEFAULT 0 NOT NULL,
    "salary_currency" "text" DEFAULT 'usd'::"text" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "has_dividends" boolean DEFAULT false,
    "dividend_type" "text",
    "dividend_amount" numeric(15,2) DEFAULT 0,
    "dividend_currency" "text" DEFAULT 'usd'::"text",
    "salary_payday" integer DEFAULT 30,
    "dividend_payday" integer DEFAULT 30,
    "is_fired" boolean DEFAULT false,
    "linked_user_id" "uuid",
    CONSTRAINT "employees_dividend_type_check" CHECK (("dividend_type" = ANY (ARRAY['fixed'::"text", 'percentage'::"text"]))),
    CONSTRAINT "employees_gender_check" CHECK (("gender" = ANY (ARRAY['male'::"text", 'female'::"text", 'other'::"text"])))
);


