-- Name: COLUMN "employees"."has_dividends"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."employees"."has_dividends" IS 'Whether the employee (usually management) receives dividends/ownership shares';


--
-- Name: COLUMN "employees"."dividend_type"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN "public"."employees"."dividend_type" IS 'Calculation method for dividends: fixed amount or percentage of net profit';


