--
-- Name: inventory_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."inventory_transactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "storage_id" "uuid" NOT NULL,
    "transaction_type" "text" NOT NULL,
    "quantity_delta" integer NOT NULL,
    "previous_quantity" integer DEFAULT 0 NOT NULL,
    "new_quantity" integer DEFAULT 0 NOT NULL,
    "reference_id" "text",
    "reference_type" "text",
    "notes" "text",
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "adjustment_reason" "text",
    CONSTRAINT "inventory_transactions_adjustment_reason_check" CHECK ((("adjustment_reason" IS NULL) OR ("adjustment_reason" = ANY (ARRAY['purchase'::"text", 'return'::"text", 'correction'::"text", 'damage'::"text", 'theft'::"text", 'expired'::"text", 'production'::"text", 'other'::"text"])))),
    CONSTRAINT "inventory_transactions_delta_check" CHECK (("quantity_delta" <> 0)),
    CONSTRAINT "inventory_transactions_new_quantity_check" CHECK (("new_quantity" >= 0)),
    CONSTRAINT "inventory_transactions_previous_quantity_check" CHECK (("previous_quantity" >= 0)),
    CONSTRAINT "inventory_transactions_type_check" CHECK (("transaction_type" = ANY (ARRAY['stock_adjustment'::"text", 'transfer_in'::"text", 'transfer_out'::"text", 'sale'::"text", 'return'::"text", 'initial_stock'::"text"])))
);


