--
-- Name: loans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."loans" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "sale_id" "uuid",
    "loan_no" "text" NOT NULL,
    "source" "text" NOT NULL,
    "borrower_name" "text" NOT NULL,
    "borrower_phone" "text" NOT NULL,
    "borrower_address" "text" NOT NULL,
    "borrower_national_id" "text" NOT NULL,
    "principal_amount" numeric NOT NULL,
    "total_paid_amount" numeric DEFAULT 0 NOT NULL,
    "balance_amount" numeric NOT NULL,
    "settlement_currency" "text" NOT NULL,
    "installment_count" integer NOT NULL,
    "installment_frequency" "text" NOT NULL,
    "first_due_date" "date",
    "next_due_date" "date",
    "status" "text" NOT NULL,
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "overdue_reminder_snoozed_at" timestamp with time zone,
    "overdue_reminder_snoozed_for_due_date" "date",
    "linked_party_type" "text",
    "linked_party_id" "uuid",
    "linked_party_name" "text",
    "loan_category" "text" DEFAULT 'standard'::"text" NOT NULL,
    "direction" "text" DEFAULT 'lent'::"text" NOT NULL,
    "exchange_rate_snapshot" "jsonb",
    "order_id" "uuid",
    "order_type" "text",
    CONSTRAINT "loans_category_check" CHECK (("loan_category" = ANY (ARRAY['standard'::"text", 'simple'::"text"]))),
    CONSTRAINT "loans_direction_check" CHECK (("direction" = ANY (ARRAY['lent'::"text", 'borrowed'::"text"]))),
    CONSTRAINT "loans_installment_frequency_check" CHECK (("installment_frequency" = ANY (ARRAY['weekly'::"text", 'biweekly'::"text", 'monthly'::"text"]))),
    CONSTRAINT "loans_linked_party_presence_check" CHECK (((("linked_party_type" IS NULL) AND ("linked_party_id" IS NULL) AND ("linked_party_name" IS NULL)) OR (("linked_party_type" IS NOT NULL) AND ("linked_party_id" IS NOT NULL) AND ("linked_party_name" IS NOT NULL)))),
    CONSTRAINT "loans_linked_party_type_check" CHECK ((("linked_party_type" IS NULL) OR ("linked_party_type" = 'business_partner'::"text"))),
    CONSTRAINT "loans_order_type_check" CHECK ((("order_type" IS NULL) OR ("order_type" = ANY (ARRAY['sales'::"text", 'purchase'::"text"])))),
    CONSTRAINT "loans_source_check" CHECK (("source" = ANY (ARRAY['pos'::"text", 'manual'::"text", 'order'::"text"]))),
    CONSTRAINT "loans_source_link_check" CHECK (((("source" = 'order'::"text") AND ("order_id" IS NOT NULL) AND ("order_type" IS NOT NULL) AND ("sale_id" IS NULL)) OR (("source" <> 'order'::"text") AND ("order_id" IS NULL) AND ("order_type" IS NULL)))),
    CONSTRAINT "loans_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'overdue'::"text", 'completed'::"text"])))
);


